    @_reference_instance_thread.setter
    def _reference_instance_thread(self, value) -> None:
        if value is None:
            self.thread_task_manager.stop(TASK_REFERENCE_INSTANCE, cancel=False)
        else:
            self.background_task_controller.register_external_thread(TASK_REFERENCE_INSTANCE, value)

    @property
    def _reference_instance_worker(self):
        return self.background_task_controller.worker(TASK_REFERENCE_INSTANCE)

    @_reference_instance_worker.setter
    def _reference_instance_worker(self, value) -> None:
        self.background_task_controller.set_worker_override(TASK_REFERENCE_INSTANCE, value)

    @property
    def _preview_analysis_mode(self) -> str:
        return self.preview_analysis_task_controller.mode

    @_preview_analysis_mode.setter
    def _preview_analysis_mode(self, value: str) -> None:
        self.preview_analysis_task_controller.mode = value

    @property
    def _preview_analysis_dialog(self):
        return self.preview_analysis_task_controller.dialog

    @_preview_analysis_dialog.setter
    def _preview_analysis_dialog(self, value) -> None:
        self.preview_analysis_task_controller.dialog = value

    @property
    def _preview_analysis_worker(self):
        return self.preview_analysis_task_controller.worker

    @_preview_analysis_worker.setter
    def _preview_analysis_worker(self, value) -> None:
        self.preview_analysis_task_controller.worker = value

    @property
    def _preview_analysis_finalizing(self) -> bool:
        return self.preview_analysis_task_controller.finalizing

    @_preview_analysis_finalizing.setter
    def _preview_analysis_finalizing(self, value: bool) -> None:
        self.preview_analysis_task_controller.finalizing = bool(value)

    def _build_ui(self) -> None:
        self.setStatusBar(QStatusBar())
        self._object_snap_status_button = ObjectSnapStatusButton(self.statusBar())
        self._object_snap_status_button.setSnapState(
            self._app_settings.object_snap_enabled,
            self._app_settings.object_snap_kinds,
        )
        self._object_snap_status_button.enabledChanged.connect(
            self._on_object_snap_enabled_changed
        )
        self._object_snap_status_button.kindsChanged.connect(
            self._on_object_snap_kinds_changed
        )
        self.statusBar().addPermanentWidget(self._object_snap_status_button, 0)
        self._zoom_status_button = ViewZoomStatusButton(self.statusBar())
        self._zoom_status_button.fitRequested.connect(self.fit_current_image)
        self._zoom_status_button.actualRequested.connect(self.actual_size_current_image)
        self._zoom_status_button.zoomRequested.connect(self._set_current_view_zoom)
        self._zoom_status_button.customZoomRequested.connect(
            self._prompt_current_view_zoom
        )
        self.statusBar().addPermanentWidget(self._zoom_status_button, 0)
        self._version_label = QLabel(f"v{__version__}")
        self._version_label.setToolTip(f"{self.windowTitle()} {__version__}")
        self._version_label.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.statusBar().addPermanentWidget(self._version_label, 0)
        self._update_statusbar_aux_labels()
        self._create_actions()
        self._build_menus()
        self._build_toolbar()

        container = QWidget()
        layout = QVBoxLayout(container)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        layout.addWidget(self._build_center_panel(), 1)
        self.setCentralWidget(container)

        self._project_dock = WorkspaceDockWidget("项目与类别", "projectNavigatorDock", self)
        self._project_dock.setAllowedAreas(Qt.DockWidgetArea.LeftDockWidgetArea)
        self._project_dock.setPanelWidget(self._build_left_panel())
        self.addDockWidget(Qt.DockWidgetArea.LeftDockWidgetArea, self._project_dock)

        self._inspector_dock = WorkspaceDockWidget("测量概览与属性", "measurementInspectorDock", self)
        self._inspector_dock.setAllowedAreas(Qt.DockWidgetArea.RightDockWidgetArea)
        self._inspector_dock.setPanelWidget(self._build_right_panel())
        self.addDockWidget(Qt.DockWidgetArea.RightDockWidgetArea, self._inspector_dock)

        self._results_dock = WorkspaceDockWidget("结果", "measurementResultsDock", self)
        self._results_dock.setAllowedAreas(Qt.DockWidgetArea.BottomDockWidgetArea)
        self._results_dock.setPanelWidget(self._build_results_panel())
        self.addDockWidget(Qt.DockWidgetArea.BottomDockWidgetArea, self._results_dock)
        self._results_dock.hide()

        self.setCorner(Qt.Corner.BottomLeftCorner, Qt.DockWidgetArea.BottomDockWidgetArea)
        self.setCorner(Qt.Corner.BottomRightCorner, Qt.DockWidgetArea.BottomDockWidgetArea)
        self._adaptive_layout = AdaptiveLayoutController(
            self,
            project_dock=self._project_dock,
            inspector_dock=self._inspector_dock,
            results_dock=self._results_dock,
            layout_settings=self._app_settings.workspace_layout,
            parent=self,
        )
        self._adaptive_layout.layoutPreferencesChanged.connect(self._schedule_workspace_layout_save)
        self._inspector_dock.extentChanged.connect(
            lambda _size: self._schedule_inspector_layout_restore()
        )
        for dock in (self._project_dock, self._inspector_dock, self._results_dock):
            dock.visibilityChanged.connect(self._on_workspace_dock_visibility_changed)
        self._fullscreen_controller = FullscreenMeasurementController(
            self,
            adaptive_layout=self._adaptive_layout,
            extra_chrome=(self._image_resolution_label, self._version_label),
            preserved_widgets=(self._measure_toolbar, self.statusBar()),
            state_version=2,
            parent=self,
        )
        self._fullscreen_controller.activeChanged.connect(
            self._on_fullscreen_active_changed
        )
        QTimer.singleShot(
            0,
            lambda: self._adaptive_layout
            and self._adaptive_layout.apply_pending_layout(),
        )

