    def _wire_records_pane(self, pane: MeasurementRecordsPane) -> None:
        pane.delete_selected_button.setIcon(themed_icon("delete", color="#F28482"))
        pane.delete_category_button.setIcon(themed_icon("delete", color="#F28482"))
        pane.delete_all_button.setIcon(themed_icon("delete", color="#F28482"))
        pane.measurementActivated.connect(self._activate_measurement_id)
        pane.deleteSelectedRequested.connect(
            lambda _measurement_ids: self.delete_selected_measurement()
        )
        pane.deleteCategoryRequested.connect(self.delete_measurements_by_category)
        pane.deleteAllRequested.connect(self.delete_all_measurements)
        if pane.compact:
            pane.headerStateChanged.connect(
                lambda state: self._store_records_header_state(state, inspector=True)
            )
        else:
            pane.headerStateChanged.connect(
                lambda state: self._store_records_header_state(state, inspector=False)
            )

    def _store_records_header_state(self, state: str, *, inspector: bool) -> None:
        if inspector:
            self._app_settings.inspector_measurement_results_header_state = str(state or "")
        else:
            self._app_settings.measurement_results_header_state = str(state or "")
        self._schedule_workspace_layout_save()

    def _set_inspector_section_state(self, field_name: str, expanded: bool) -> None:
        setattr(self._app_settings.workspace_layout, field_name, bool(expanded))
        if self._inspector_content is not None:
            self._inspector_content.updateGeometry()
        self._schedule_workspace_layout_save()

    def _on_inspector_records_expanded(self, expanded: bool) -> None:
        section = self._records_section
        if section is None:
            return
        state = self._app_settings.workspace_layout
        state.records_expanded = bool(expanded)
        if expanded:
            section.setContentHeight(state.inspector_records_height, emit_signal=False)
        if self._inspector_content is not None:
            self._inspector_content.updateGeometry()
        self._schedule_workspace_layout_save()

    def _on_inspector_records_height_changed(self, height: int) -> None:
        self._app_settings.workspace_layout.inspector_records_height = int(height)
        if self._inspector_content is not None:
            self._inspector_content.updateGeometry()
        self._schedule_workspace_layout_save()

    def _schedule_inspector_layout_restore(self, *, immediate: bool = False) -> None:
        timer = getattr(self, "_inspector_layout_restore_timer", None)
        if timer is None:
            return
        try:
            timer.start(0 if immediate else 40)
        except RuntimeError:
            # Late resize notifications can arrive while the window is being
            # destroyed.  There is no layout left to restore in that case.
            return

    def _restore_inspector_section_sizes(self) -> None:
        section = self._records_section
        if section is None:
            return
        state = self._app_settings.workspace_layout
        section.setContentHeight(state.inspector_records_height, emit_signal=False)
        state.inspector_records_height = section.contentHeight()
        if self._inspector_content is not None:
            self._inspector_content.updateGeometry()

    def _restore_inspector_section_defaults(self) -> None:
        defaults = self._app_settings.workspace_layout
        sections = (
            (self._statistics_section, defaults.statistics_expanded),
            (self._calibration_section, defaults.calibration_expanded),
            (self._records_section, defaults.records_expanded),
            (self._area_recognition_section, defaults.area_recognition_expanded),
            (self._object_properties_section, defaults.object_properties_expanded),
        )
        for section, expanded in sections:
            if section is not None:
                section.setExpanded(expanded)
        QTimer.singleShot(0, self._restore_inspector_section_sizes)

    def _build_acquisition_right_panel(self, parent: QWidget) -> QWidget:
        scroll = QScrollArea(parent)
        scroll.setObjectName("acquisitionInspectorScroll")
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        scroll.setMinimumWidth(280)

        panel = QWidget(scroll)
        panel.setMinimumWidth(0)
        panel.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        layout = QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        device_box = QGroupBox("采集设备", panel)
        device_layout = QVBoxLayout(device_box)
        self._acquisition_device_label = QLabel("尚未选择采集设备", device_box)
        self._acquisition_device_label.setWordWrap(True)
        self._acquisition_device_label.setMinimumWidth(0)
        self._acquisition_device_label.setSizePolicy(
            QSizePolicy.Policy.Ignored,
            QSizePolicy.Policy.Preferred,
        )
        device_layout.addWidget(self._acquisition_device_label)
        switch_button = QToolButton(device_box)
        switch_button.setDefaultAction(self.switch_capture_device_action)
        switch_button.setText("切换设备")
        switch_button.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon)
        device_layout.addWidget(switch_button)
        layout.addWidget(device_box)

        preview_box = QGroupBox("实时预览与单帧采集", panel)
        preview_layout = QVBoxLayout(preview_box)
        self._acquisition_preview_label = QLabel("等待实时预览", preview_box)
        self._acquisition_preview_label.setWordWrap(True)
        self._acquisition_preview_label.setMinimumWidth(0)
        self._acquisition_preview_label.setSizePolicy(
            QSizePolicy.Policy.Ignored,
            QSizePolicy.Policy.Preferred,
        )
        preview_layout.addWidget(self._acquisition_preview_label)
        capture_button = QToolButton(preview_box)
        capture_button.setDefaultAction(self.capture_frame_action)
        capture_button.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon)
        preview_layout.addWidget(capture_button)
        optimize_button = QToolButton(preview_box)
        optimize_button.setDefaultAction(self.optimize_capture_signal_action)
        optimize_button.setText("优化参数")
        optimize_button.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon)
        preview_layout.addWidget(optimize_button)
        layout.addWidget(preview_box)

        analysis_box = QGroupBox("预览分析", panel)
        analysis_layout = QVBoxLayout(analysis_box)
        analysis_hint = QLabel("分析最多保持一帧在途；完成或取消动作始终显示在画布上方。", analysis_box)
        analysis_hint.setWordWrap(True)
        analysis_layout.addWidget(analysis_hint)
        self._acquisition_focus_stack_button = QToolButton(analysis_box)
        self._acquisition_focus_stack_button.setText("景深合成")
        self._acquisition_focus_stack_button.setCheckable(True)
        self._acquisition_focus_stack_button.clicked.connect(
            lambda checked=False: self._toggle_preview_analysis_mode("focus_stack", checked)
        )
        analysis_layout.addWidget(self._acquisition_focus_stack_button)
        self._acquisition_map_button = QToolButton(analysis_box)
        self._acquisition_map_button.setText("地图构建")
        self._acquisition_map_button.setCheckable(True)
        self._acquisition_map_button.clicked.connect(
            lambda checked=False: self._toggle_preview_analysis_mode("map_build", checked)
        )
        analysis_layout.addWidget(self._acquisition_map_button)
        layout.addWidget(analysis_box)
        layout.addStretch(1)

        scroll.setWidget(panel)
        return scroll

    def _show_measurement_columns_menu(self, position: QPoint) -> None:
        if self._bottom_records_pane is not None:
            self._bottom_records_pane._show_columns_menu(position)  # noqa: SLF001
            return
        header = self.measurement_table.horizontalHeader()
        model = self.measurement_table.model()
        menu = QMenu(header)
        for column in range(model.columnCount() if model is not None else 0):
            label = str(model.headerData(column, Qt.Orientation.Horizontal) or column)
            action = menu.addAction(label)
            action.setCheckable(True)
            action.setChecked(not self.measurement_table.isColumnHidden(column))
            action.toggled.connect(
                lambda visible, target_column=column: self.measurement_table.setColumnHidden(
                    target_column,
                    not visible,
                )
            )
        menu.addSeparator()
        reset_action = menu.addAction("恢复默认列")
        reset_action.triggered.connect(self._reset_measurement_columns)
        menu.exec(header.mapToGlobal(position))

    def _reset_measurement_columns(self) -> None:
        if self._bottom_records_pane is not None:
            self._bottom_records_pane.reset_columns()

