    def _add_loaded_document(self, request: ImageLoadRequest, image: QImage) -> None:
        absolute_path = request.path
        target_document = request.document or ImageDocument(
            id=new_id("image"),
            path=absolute_path,
            image_size=(image.width(), image.height()),
        )
        target_document.image_size = (image.width(), image.height())
        if request.document is None:
            target_document.path = absolute_path
            target_document.source_type = "filesystem"
        elif target_document.source_type == "filesystem":
            # Publish a repaired path only after decoding succeeded. Failed or
            # cancelled project loads retain their original path tokens.
            target_document.path = absolute_path
            target_document.absolute_path = absolute_path
            if target_document.uses_sidecar():
                target_document.sidecar_path = target_document.default_sidecar_path()
        target_document.initialize_runtime_state()
        if target_document.calibration is None:
            loaded_from_sidecar = False
            if not target_document.calibration_load_error and target_document.uses_sidecar():
                loaded_from_sidecar = CalibrationSidecarIO.load_document(target_document)
            if target_document.calibration_load_error:
                if target_document.calibration_load_payload is not None and not any(
                    issue.get("kind") in {"document_calibration", "sidecar_calibration"}
                    and str(issue.get("document_id", "")) == target_document.id
                    for issue in self.project.load_issues
                ):
                    self.project.load_issues.append(
                        {
                            "kind": "sidecar_calibration",
                            "document_id": target_document.id,
                            "sidecar_path": target_document.sidecar_path or target_document.default_sidecar_path(),
                            "message": target_document.calibration_load_error,
                            "raw_payload": copy.deepcopy(target_document.calibration_load_payload),
                        }
                    )
                target_document.recalculate_measurements()
                self.statusBar().showMessage(
                    f"{Path(absolute_path).name} 的标尺无效，已保留几何并暂停单位换算，请重新标定。",
                    7000,
                )
            elif self.project.project_default_calibration is not None:
                use_project_default = not loaded_from_sidecar
                if loaded_from_sidecar and target_document.calibration is not None:
                    use_project_default = self._prompt_project_default_conflict(
                        image_name=Path(absolute_path).name,
                        document_calibration=target_document.calibration,
                    )
                if use_project_default:
                    self._set_document_project_default_calibration(target_document)
                    target_document.mark_calibration_saved()
        else:
            target_document.mark_calibration_saved()
        target_document.recalculate_measurements()
        self._apply_project_group_templates_to_document(target_document)
        target_document.mark_session_saved()

        self._mount_document(
            target_document,
            image,
            tooltip=absolute_path if request.document is None else self._document_tooltip(target_document),
            raster_plane=request.raster_plane,
            raster_metadata=request.raster_metadata,
            restored_view_state=request.document is not None,
        )
        self.project_session_controller.mark_document_resolved(target_document.id)

    def _attach_canvas_navigator(
        self,
        document_id: str,
        canvas: DocumentCanvas,
        *,
        source_image: QImage | None,
    ) -> CanvasNavigatorWidget:
        navigator = CanvasNavigatorWidget(canvas)
        navigator.set_navigator_enabled(
            bool(self._app_settings.show_canvas_navigator)
        )
        navigator.set_source_image(source_image)
        if isinstance(canvas, DigitalSlideCanvas):
            canvas.overviewImageChanged.connect(navigator.set_source_image)
            canvas.set_overview_enabled(
                bool(self._app_settings.show_canvas_navigator)
            )
            overview = canvas.overview_image()
            if not overview.isNull():
                navigator.set_source_image(overview)
        navigator.centerRequested.connect(
            lambda point, target_id=document_id: self._on_canvas_navigator_center_requested(
                target_id,
                point,
            )
        )
        navigator.set_viewport_snapshot(canvas.viewport_snapshot())
        self._canvas_navigators[document_id] = navigator
        return navigator

    def _connect_canvas_roi_signals(self, canvas: DocumentCanvas) -> None:
        signal = getattr(canvas, "roiGeometryCommitted", None)
        connect = getattr(signal, "connect", None)
        if callable(connect):
            connect(self._on_canvas_roi_geometry_committed)

    def _connect_canvas_construction_signals(
        self,
        canvas: DocumentCanvas,
    ) -> None:
        canvas.constructionCreateRequested.connect(
            self._on_canvas_construction_create_requested
        )
        canvas.constructionEdited.connect(
            self._on_canvas_construction_edited
        )
        canvas.constructionCommandChanged.connect(
            self._on_canvas_construction_command_changed
        )
        canvas.snapCandidateChanged.connect(
            self._on_canvas_snap_candidate_changed
        )

    def _mount_document(
        self,
        document: ImageDocument,
        image: QImage,
        *,
        tooltip: str,
        raster_plane: RasterPlane | None = None,
        raster_metadata: RasterMetadata | None = None,
        restored_view_state: bool = False,
    ) -> None:
        if document.history is not None:
            document.history.set_workspace_budget(self._workspace_history_budget)
        canvas = DocumentCanvas()
        canvas.set_document(document, image)
        canvas.set_settings(self._app_settings)
        canvas.set_tool_mode(
            self._tool_mode,
            overlay_kind=self._overlay_tool_kind,
            construction_kind=self._construction_tool_kind,
        )
        if is_magic_segment_tool_mode(self._tool_mode):
            self._sync_canvas_magic_subtract_input_mode(canvas)
        canvas.set_show_area_fill(self._show_area_fill)
        canvas.lineCommitted.connect(self._on_canvas_line_committed)
        canvas.objectSelectionChanged.connect(self._on_canvas_object_selection_changed)
        canvas.measurementEdited.connect(self._on_canvas_measurement_edited)
        canvas.pathSessionChanged.connect(self._on_canvas_path_session_changed)
        canvas.areaEditRejected.connect(self._on_canvas_area_edit_rejected)
        canvas.overlayCreateRequested.connect(self._on_canvas_overlay_create_requested)
        canvas.overlayEdited.connect(self._on_canvas_overlay_edited)
        canvas.scaleAnchorPicked.connect(self._on_canvas_scale_anchor_picked)
        canvas.viewZoomChanged.connect(
            lambda _zoom, document_id=document.id: self._on_canvas_view_zoom_changed(
                document_id
            )
        )
        canvas.viewTransformChanged.connect(
            lambda snapshot, document_id=document.id: self._on_canvas_view_transform_changed(
                document_id,
                snapshot,
            )
        )
        canvas.magicSegmentRequested.connect(self._on_canvas_magic_segment_requested)
        canvas.magicSegmentSessionChanged.connect(self._on_canvas_magic_segment_session_changed)
        self._connect_canvas_roi_signals(canvas)
        self._connect_canvas_construction_signals(canvas)

        self._remove_unresolved_placeholder_ui(document.id)
        insert_index = self.project_session_controller.ui_insert_index(document.id, self._document_order)
        self.project.documents.insert(insert_index, document)
        self._document_order.insert(insert_index, document.id)
        self._images[document.id] = image
        self._display_cache_transforms[document.id] = (
            document.display_transform
        )
        authoritative_plane = raster_plane or qimage_to_raster_plane(image)
        self._rasters[document.id] = authoritative_plane
        if raster_metadata is not None:
            self._raster_metadata[document.id] = raster_metadata
        else:
            self._raster_metadata.pop(document.id, None)
        document.raster_pixel_type = authoritative_plane.pixel_type
        self._canvases[document.id] = canvas
        self._attach_canvas_navigator(document.id, canvas, source_image=image)

        tab_index = self.tab_widget.insertTab(insert_index, canvas, self._document_display_name(document))
        self.tab_widget.setTabToolTip(tab_index, tooltip)
        list_item = QListWidgetItem(self._document_display_name(document))
        list_item.setData(Qt.ItemDataRole.UserRole, document.id)
        list_item.setToolTip(tooltip)
        self.image_list.insertItem(insert_index, list_item)
        self.tab_widget.setCurrentIndex(tab_index)
        self.image_list.setCurrentRow(tab_index)
        self._apply_open_view_mode(canvas, restored_view_state=restored_view_state)
        self._update_ui_for_current_document()

    def _add_digital_slide_document_from_path(
        self,
        path: str | Path,
        *,
        document: ImageDocument | None,
        source_type: str | None = None,
        document_path: str | None = None,
        metadata: dict[str, object] | None = None,
        tooltip: str | None = None,
        interaction_path_override: str | Path | None = None,
    ) -> None:
        source_path = Path(path).expanduser().resolve()
        try:
            interaction_path = (
                Path(interaction_path_override).expanduser().resolve()
                if interaction_path_override is not None
                else self._localize_digital_slide_source(source_path)
            )
        except DigitalSlideCacheCancelled:
            self.statusBar().showMessage("已取消打开网络数字化切片。", 5000)
            return
        except Exception as exc:  # noqa: BLE001 - normalize network/cache failures
            QMessageBox.warning(
                self,
                "打开数字化切片",
                f"无法准备数字化切片的本机读取副本：\n{source_path}\n\n{exc}",
            )
            return
        store = DigitalSlideStore(interaction_path)
        try:
            manifest = store.read_manifest()
        except Exception as exc:
            store.close()
            QMessageBox.warning(self, "打开数字化切片", f"无法读取数字化切片：\n{source_path}\n\n{exc}")
            return
        target_document = document or ImageDocument(
            id=new_id("slide"),
            path=document_path or str(source_path),
            image_size=(manifest.width, manifest.height),
            source_type=source_type or "filesystem",
            document_kind=DOCUMENT_KIND_DIGITAL_SLIDE,
            metadata=dict(metadata or {}),
        )
        target_document.document_kind = DOCUMENT_KIND_DIGITAL_SLIDE
        target_document.image_size = (manifest.width, manifest.height)
        if document is None:
            target_document.source_type = source_type or "filesystem"
            target_document.path = document_path or str(source_path)
        if target_document.source_type == "filesystem":
            # Relocation becomes persistent only after the SQLite manifest was
            # opened successfully.
            target_document.path = str(source_path)
            target_document.absolute_path = str(source_path)
        if metadata:
            merged = dict(target_document.metadata)
            merged.update(metadata)
            target_document.metadata = merged
        slide_meta = dict(target_document.metadata.get("digital_slide", {})) if isinstance(target_document.metadata.get("digital_slide"), dict) else {}
        if target_document.source_type == "project_asset":
            # A project loaded from a network share should also be saved from
            # the consistent local snapshot, not reread tile-by-tile over SMB.
            slide_meta["working_path"] = str(interaction_path)
        target_document.metadata["digital_slide"] = slide_meta
        target_document.initialize_runtime_state()
        if target_document.history is not None:
            target_document.history.set_workspace_budget(self._workspace_history_budget)
        if target_document.calibration is None and self.project.project_default_calibration is not None:
            target_document.calibration = self._digital_slide_scaled_calibration(
                self.project.project_default_calibration,
                manifest,
            )
            target_document.metadata.pop("calibration_line", None)
            target_document.mark_calibration_saved()
        target_document.mark_session_saved()
        target_document.mark_calibration_saved()

        canvas = DigitalSlideCanvas()
        try:
            canvas.set_slide_document(target_document, store)
        except Exception as exc:
            canvas.shutdown()
            try:
                store.close()
            except Exception:
                pass
            canvas.deleteLater()
            QMessageBox.warning(
                self,
                "打开数字化切片",
                f"无法初始化数字化切片视图：\n{source_path}\n\n{exc}",
            )
            return
        canvas.set_settings(self._app_settings)
        canvas.set_tool_mode(
            self._tool_mode,
            overlay_kind=self._overlay_tool_kind,
            construction_kind=self._construction_tool_kind,
        )
        canvas.set_show_area_fill(self._show_area_fill)
        canvas.lineCommitted.connect(self._on_canvas_line_committed)
        canvas.objectSelectionChanged.connect(self._on_canvas_object_selection_changed)
        canvas.measurementEdited.connect(self._on_canvas_measurement_edited)
        canvas.pathSessionChanged.connect(self._on_canvas_path_session_changed)
        canvas.areaEditRejected.connect(self._on_canvas_area_edit_rejected)
        canvas.overlayCreateRequested.connect(self._on_canvas_overlay_create_requested)
        canvas.overlayEdited.connect(self._on_canvas_overlay_edited)
        canvas.scaleAnchorPicked.connect(self._on_canvas_scale_anchor_picked)
        canvas.viewZoomChanged.connect(
            lambda _zoom, document_id=target_document.id: self._on_canvas_view_zoom_changed(
                document_id
            )
        )
        canvas.viewTransformChanged.connect(
            lambda snapshot, document_id=target_document.id: self._on_canvas_view_transform_changed(
                document_id,
                snapshot,
            )
        )
        canvas.magicSegmentRequested.connect(self._on_canvas_magic_segment_requested)
        canvas.magicSegmentSessionChanged.connect(self._on_canvas_magic_segment_session_changed)
        self._connect_canvas_roi_signals(canvas)
        self._connect_canvas_construction_signals(canvas)
        canvas.viewportChanged.connect(self._on_digital_slide_viewport_changed)
        canvas.navigationModeChanged.connect(self._on_digital_slide_navigation_mode_changed)

        self._remove_unresolved_placeholder_ui(target_document.id)
        insert_index = self.project_session_controller.ui_insert_index(target_document.id, self._document_order)
        self.project.documents.insert(insert_index, target_document)
        self._document_order.insert(insert_index, target_document.id)
        self._canvases[target_document.id] = canvas
        self._slide_stores[target_document.id] = store
        self._attach_canvas_navigator(
            target_document.id,
            canvas,
            source_image=None,
        )

        tab_index = self.tab_widget.insertTab(insert_index, canvas, self._document_display_name(target_document))
        self.tab_widget.setTabToolTip(tab_index, tooltip or str(source_path))
        list_item = QListWidgetItem(self._document_display_name(target_document))
        list_item.setData(Qt.ItemDataRole.UserRole, target_document.id)
        list_item.setToolTip(tooltip or str(source_path))
        self.image_list.insertItem(insert_index, list_item)
        self.project_session_controller.mark_document_resolved(target_document.id)
        self.tab_widget.setCurrentIndex(tab_index)
        self.image_list.setCurrentRow(tab_index)
        canvas.schedule_initial_fit()
        self._update_ui_for_current_document()
        if interaction_path != source_path:
            self.statusBar().showMessage(
                f"已从本机临时副本打开网络切片：{source_path.name}",
                6000,
            )

    def _localize_digital_slide_source(self, source_path: Path) -> Path:
        cache = self._digital_slide_local_cache
        if not cache.requires_local_copy(source_path):
            return source_path
        progress = QProgressDialog(
            "正在将网络数字化切片复制到本机临时目录…",
            "取消",
            0,
            1000,
            self,
        )
        progress.setWindowTitle("打开网络数字化切片")
        progress.setWindowModality(Qt.WindowModality.WindowModal)
        progress.setMinimumDuration(250)
        progress.setAutoClose(False)
        progress.setAutoReset(False)

        def update_progress(copied: int, total: int) -> None:
            denominator = max(1, int(total))
            progress.setValue(min(1000, int(round((int(copied) / denominator) * 1000))))
            progress.setLabelText(
                "正在将网络数字化切片复制到本机临时目录…\n"
                f"{source_path.name}\n"
                f"{int(copied) / (1024**2):.1f} / {int(total) / (1024**2):.1f} MiB"
            )
            QApplication.processEvents()

        try:
            return cache.localize(
                source_path,
                progress_callback=update_progress,
                cancellation_requested=progress.wasCanceled,
            )
        finally:
            progress.close()
            progress.deleteLater()

    def _on_digital_slide_viewport_changed(self, x: int, y: int, focus_index: int) -> None:
        document = self.current_document()
        if document is None or not document.is_digital_slide():
            return
        self._update_image_resolution_label(document)

    def _current_digital_slide_canvas(self) -> DigitalSlideCanvas | None:
        document = self.current_document()
        if document is None or not document.is_digital_slide():
            return None
        canvas = self._canvases.get(document.id)
        return canvas if isinstance(canvas, DigitalSlideCanvas) else None

    def _set_current_digital_slide_smooth_navigation(self, checked: bool) -> None:
        canvas = self._current_digital_slide_canvas()
        if canvas is None:
            self._sync_digital_slide_navigation_action()
            return
        canvas.set_navigation_mode("smooth" if checked else "step")
        self._sync_digital_slide_navigation_action()
        self._update_image_resolution_label()

    def _on_digital_slide_navigation_mode_changed(self, mode: str) -> None:
        self._sync_digital_slide_navigation_action()
        self._update_image_resolution_label()

    def _sync_digital_slide_navigation_action(self) -> None:
        action = self.digital_slide_smooth_navigation_action
        if action is None:
            return
        canvas = self._current_digital_slide_canvas()
        enabled = canvas is not None and not self._preview_active
        action.blockSignals(True)
        action.setEnabled(enabled)
        action.setChecked(bool(canvas is not None and canvas.navigation_mode() == "smooth"))
        action.blockSignals(False)

    def save_project(self, path: str | None = None) -> ProjectSaveResult:
        return self.project_session_controller.save_project(path)

    def load_project(self) -> ProjectLoadResult:
        return self.project_session_controller.load_project()

    def _load_project_from_path(self, path: str | Path) -> ProjectLoadResult:
        return self.project_session_controller.load_project_from_path(path)

    def enqueue_application_open_request(self, request: ApplicationOpenRequest) -> None:
        self.associated_file_open_controller.enqueue(request)

    def _activate_from_external_request(self) -> None:
        state = self.windowState()
        if state & Qt.WindowState.WindowMinimized:
            self.setWindowState(
                (state & ~Qt.WindowState.WindowMinimized) | Qt.WindowState.WindowActive
            )
        self.show()
        self.raise_()
        self.activateWindow()
        QApplication.alert(self, 0)

    def _associated_open_document_id(self, path: Path) -> str | None:
        target = self._normalize_image_path(path).casefold()
        for document in self.project.documents:
            if not document.is_digital_slide():
                continue
            resolved_path = self._resolved_document_path(document)
            if resolved_path and self._normalize_image_path(resolved_path).casefold() == target:
                return document.id
        return None

    def export_results(self, preset: ExportSelection | None = None) -> None:
        self.export_controller.export_results(preset)

    def _prepare_raw_record_template_for_export(self, selection: ExportSelection) -> RawRecordTemplate | None:
        return self.export_controller.prepare_raw_record_template_for_export(selection)

    def _raw_record_template_for_path(self, template_path: str) -> RawRecordTemplate | None:
        return self.export_controller.raw_record_template_for_path(template_path)

    def fit_current_image(self) -> None:
        canvas = self.current_canvas()
        if canvas is not None:
            canvas.fit_to_view()

    def actual_size_current_image(self) -> None:
        canvas = self.current_canvas()
        if canvas is not None:
            canvas.actual_size()

    def _set_current_view_zoom(self, zoom: float) -> None:
        canvas = self.current_canvas()
        if canvas is not None:
            canvas.set_view_zoom(float(zoom))

    def _prompt_current_view_zoom(self) -> None:
        canvas = self.current_canvas()
        if canvas is None:
            return
        percentage, accepted = QInputDialog.getDouble(
            self,
            "自定义视图缩放",
            "缩放比例（%）：",
            float(canvas.view_zoom()) * 100.0,
            0.01,
            4000.0,
            2,
        )
        if accepted:
            canvas.set_view_zoom(float(percentage) / 100.0)

    def _sync_current_view_transform(self) -> None:
        canvas = self.current_canvas()
        document = self.current_document()
        if canvas is None or document is None:
            if self._zoom_status_button is not None:
                self._zoom_status_button.set_viewport_snapshot(None)
            return
        self._on_canvas_view_transform_changed(
            document.id,
            canvas.viewport_snapshot(),
        )

    def _toggle_canvas_navigator(self, checked: bool = False) -> None:
        enabled = bool(checked)
        self._app_settings.show_canvas_navigator = enabled
        if not enabled:
            self._navigator_center_timer.stop()
            self._pending_navigator_center = None
        for navigator in self._canvas_navigators.values():
            navigator.set_navigator_enabled(enabled)
        for canvas in self._canvases.values():
            if isinstance(canvas, DigitalSlideCanvas):
                canvas.set_overview_enabled(enabled)
        self._save_app_settings(context="导航概览")
        self.statusBar().showMessage(
            "已显示整图缩略图和视场位置" if enabled else "导航概览已隐藏",
            2500,
        )

    def _on_canvas_navigator_center_requested(
        self,
        document_id: str,
        point: Point,
    ) -> None:
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return
        if isinstance(canvas, DigitalSlideCanvas):
            # Navigator drag events can arrive much faster than SQLite can
            # compose a viewport. Debounce to the latest requested point so a
            # drag performs one final exact load instead of blocking on every
            # mouse-move event.
            self._pending_navigator_center = (document_id, point)
            self._navigator_center_timer.start()
            return
        canvas.center_on_image_point(point)

    def _apply_pending_navigator_center(self) -> None:
        pending = self._pending_navigator_center
        self._pending_navigator_center = None
        if pending is None:
            return
        document_id, point = pending
        document = self.current_document()
        canvas = self._canvases.get(document_id)
        if (
            document is None
            or document.id != document_id
            or not isinstance(canvas, DigitalSlideCanvas)
        ):
            return
        canvas.center_on_image_point(point)

    def _toggle_fullscreen_measurement(self, checked: bool = False) -> None:
        controller = self._fullscreen_controller
        if controller is None:
            return
        if not checked:
            controller.exit()
            return
        if (
            self.current_document() is None
            or self._preview_active
            or self._workspace_mode is not WorkspaceMode.MEASURE
        ):
            self.fullscreen_measurement_action.blockSignals(True)
            self.fullscreen_measurement_action.setChecked(False)
            self.fullscreen_measurement_action.blockSignals(False)
            self.statusBar().showMessage(
                "请先打开图片并切换到“测量分析”工作区。",
                4000,
            )
            return
        if not controller.enter() and not controller.is_active:
            self.fullscreen_measurement_action.blockSignals(True)
            self.fullscreen_measurement_action.setChecked(False)
            self.fullscreen_measurement_action.blockSignals(False)

    def _on_fullscreen_active_changed(self, active: bool) -> None:
        action = self.fullscreen_measurement_action
        action.blockSignals(True)
        action.setChecked(bool(active))
        action.setText("退出全屏" if active else "全屏测量")
        action.setToolTip(
            "退出全屏测量（F11）"
            if active
            else "进入沉浸式全屏测量（F11；Esc 在没有活动绘制时退出）"
        )
        action.setIcon(
            themed_icon(
                "exit_fullscreen" if active else "fullscreen",
                color=self._tool_icon_color("fullscreen"),
            )
        )
        action.blockSignals(False)
        if active:
            QTimer.singleShot(0, self._show_fullscreen_hint)
            QTimer.singleShot(0, self._focus_current_canvas)
        else:
            self._hide_fullscreen_hint(delete=True)
        self._update_action_states()

    def _show_fullscreen_hint(self) -> None:
        canvas = self.current_canvas()
        controller = self._fullscreen_controller
        if canvas is None or controller is None or not controller.is_active:
            return
        self._hide_fullscreen_hint(delete=True)
        label = QLabel(
            "已进入全屏测量  ·  F11 退出  ·  Esc 会先取消当前绘制",
            canvas,
        )
        label.setObjectName("fullscreenMeasurementHint")
        label.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        if self._is_dark_palette():
            label.setStyleSheet(
                "QLabel { color: #F4F7FA; background: rgba(16, 24, 32, 218);"
                " border: 1px solid rgba(126, 148, 166, 180);"
                " border-radius: 8px; padding: 9px 15px; font-weight: 600; }"
            )
        else:
            label.setStyleSheet(
                "QLabel { color: #24313D; background: rgba(250, 252, 253, 232);"
                " border: 1px solid rgba(112, 130, 145, 170);"
                " border-radius: 8px; padding: 9px 15px; font-weight: 600; }"
            )
        label.adjustSize()
        self._fullscreen_hint_generation += 1
        generation = self._fullscreen_hint_generation
        self._fullscreen_hint_label = label
        label.destroyed.connect(
            lambda _object=None, token=generation: self._on_fullscreen_hint_destroyed(
                token
            )
        )
        self._position_fullscreen_hint()
        label.show()
        label.raise_()
        # Some Qt platform plugins settle the central-widget geometry one or
        # two event turns after showFullScreen(). Re-center the transient hint
        # after that layout pass so it cannot drift to the right on entry.
        QTimer.singleShot(0, self._position_fullscreen_hint)
        QTimer.singleShot(160, self._position_fullscreen_hint)
        self._fullscreen_hint_timer.start(3200)

    def _position_fullscreen_hint(self) -> None:
        label = self._fullscreen_hint_label
        canvas = self.current_canvas()
        if label is None:
            return
        if not is_qobject_valid(label):
            self._on_fullscreen_hint_destroyed(self._fullscreen_hint_generation)
            return
        if (
            canvas is None
            or not is_qobject_valid(canvas)
            or label.parentWidget() is not canvas
        ):
            return
        label.move(
            max(12, (canvas.width() - label.width()) // 2),
            16,
        )
        label.raise_()

    def _fade_fullscreen_hint(self) -> None:
        label = self._fullscreen_hint_label
        if label is None:
            return
        if not is_qobject_valid(label):
            self._on_fullscreen_hint_destroyed(self._fullscreen_hint_generation)
            return
        if not label.isVisible():
            self._hide_fullscreen_hint(delete=True)
            return
        self._discard_fullscreen_hint_animation()
        effect = label.graphicsEffect()
        if not isinstance(effect, QGraphicsOpacityEffect):
            effect = QGraphicsOpacityEffect(label)
            effect.setOpacity(1.0)
            label.setGraphicsEffect(effect)
        animation = QPropertyAnimation(effect, b"opacity", self)
        animation.setDuration(350)
        animation.setStartValue(float(effect.opacity()))
        animation.setEndValue(0.0)
        animation.setEasingCurve(QEasingCurve.Type.OutCubic)
        animation.finished.connect(self._finish_fullscreen_hint_fade)
        self._fullscreen_hint_animation = animation
        animation.start()

    def _finish_fullscreen_hint_fade(self) -> None:
        self._hide_fullscreen_hint(delete=True)

    def _discard_fullscreen_hint_animation(self) -> None:
        animation = self._fullscreen_hint_animation
        self._fullscreen_hint_animation = None
        if animation is None or not is_qobject_valid(animation):
            return
        animation.stop()
        animation.deleteLater()

    def _on_fullscreen_hint_destroyed(self, generation: int) -> None:
        if generation != self._fullscreen_hint_generation:
            return
        self._fullscreen_hint_label = None
        if is_qobject_valid(self._fullscreen_hint_timer):
            self._fullscreen_hint_timer.stop()
        self._discard_fullscreen_hint_animation()

    def _hide_fullscreen_hint(self, *, delete: bool = True) -> None:
        if is_qobject_valid(self._fullscreen_hint_timer):
            self._fullscreen_hint_timer.stop()
        self._discard_fullscreen_hint_animation()
        label = self._fullscreen_hint_label
        if label is None:
            return
        if delete:
            # Clear ownership before touching Qt so a re-entrant transition or
            # a parent-driven delete cannot expose this wrapper again.
            self._fullscreen_hint_label = None
        if not is_qobject_valid(label):
            self._fullscreen_hint_label = None
            return
        label.hide()
        if delete:
            label.deleteLater()

    def open_settings_dialog(self, *, initial_page: int = 0) -> None:
        dialog = SettingsDialog(
            self._app_settings,
            document=self.current_document(),
            digital_slide_locked=self._slide_acquisition_active(),
            screenshot_settings=self._screenshot_settings,
            parent=self,
        )
        requested_page = max(0, min(dialog._settings_pages.count() - 1, int(initial_page)))
        dialog._settings_navigation.setCurrentRow(requested_page)
        screenshot_status = self._screenshot_agent_client.status(timeout_ms=180)
        status_error = str(screenshot_status.error or "")
        if self._screenshot_settings_load_error:
            status_error = (
                f"截图设置读取失败：{self._screenshot_settings_load_error}"
                + (f"；{status_error}" if status_error else "")
            )
        dialog._screenshot_settings_widget.set_agent_status(
            screenshot_status.running,
            status_error,
        )
        dialog.screenshotCu5DiagnosticRequested.connect(
            lambda: self._diagnose_cu5_preview(dialog)
        )
        dialog.screenshotCu5CandidateSelectionRequested.connect(
            lambda selector: self._select_cu5_preview_candidate(dialog, selector)
        )
        apply_button = dialog.button_box.button(QDialogButtonBox.StandardButton.Apply)
        if apply_button is not None:
            apply_button.clicked.connect(lambda: self._apply_settings_dialog(dialog, close_after=False))
        if dialog.exec() != dialog.DialogCode.Accepted:
            return
        self._apply_settings_dialog(dialog, close_after=True)

    def open_digital_slide_compression_dialog(self) -> None:
        source_path: Path | None = None
        document = self.current_document()
        if document is not None and document.is_digital_slide():
            candidate = self._resolved_document_path(document)
            if candidate.suffix.lower() == DIGITAL_SLIDE_SUFFIX:
                source_path = candidate
        dialog = DigitalSlideCompressionDialog(
            self._app_settings,
            source_path=source_path,
            parent=self,
        )
        dialog.exec()

    def _apply_settings_dialog(self, dialog: SettingsDialog, *, close_after: bool) -> None:
        new_settings = dialog.app_settings()
        new_screenshot_settings = dialog.screenshot_settings()
        if self._slide_acquisition_active():
            new_settings = self._settings_with_locked_digital_slide_values(new_settings)
        self._activate_app_settings(new_settings)
        refresh_widget_theme(dialog)
        self._save_app_settings(context="设置")
        self._apply_screenshot_settings(new_screenshot_settings, parent=dialog)

        should_pick_scale_anchor = dialog.wants_scale_anchor_pick()
        if should_pick_scale_anchor and self.current_document() is not None:
            if not close_after:
                dialog.accept()
                return
            self._begin_scale_anchor_pick(self.current_document())
        elif close_after:
            self.statusBar().showMessage("设置已更新", 3000)

    def _set_screenshot_tool_action_checked(self, checked: bool) -> None:
        self._screenshot_action_update = True
        try:
            self.screenshot_tool_action.setChecked(bool(checked))
        finally:
            self._screenshot_action_update = False

    def _save_screenshot_settings(
        self,
        *,
        parent: QWidget | None = None,
        preserve_agent_owned: bool = True,
        allow_unsupported_replace: bool = False,
    ) -> bool:
        if self._screenshot_settings_read_only:
            QMessageBox.warning(
                parent or self,
                "截图工具设置",
                "截图设置由更新版本的软件写入，当前版本不会覆盖该文件。\n"
                "如需重置，请在首选项的截图工具页面修改设置并确认替换。",
            )
            return False
        try:
            requested = self._screenshot_settings.normalized()

            def merge_main_owned(persisted: ScreenshotSettings) -> ScreenshotSettings:
                # These fields are learned by the detached agent. A candidate
                # chooser may explicitly replace only the selector; it must
                # still preserve the latest region captured by the companion.
                return replace(
                    requested,
                    last_region=persisted.last_region,
                    cu5_selector=(
                        dict(persisted.cu5_selector)
                        if preserve_agent_owned
                        else dict(requested.cu5_selector)
                    ),
                ).normalized()

            self._screenshot_settings = ScreenshotSettingsIO.update(
                merge_main_owned,
                allow_unsupported_replace=allow_unsupported_replace,
            )
        except UnsupportedScreenshotSettingsVersion as exc:
            self._screenshot_settings_read_only = True
            self._screenshot_settings_load_error = str(exc)
            QMessageBox.warning(
                parent or self,
                "截图工具设置",
                "截图设置刚刚由更新版本的软件写入，当前版本不会覆盖该文件。\n"
                "请重新打开首选项；如需降级，请在截图工具页面明确确认重置。",
            )
            return False
        except OSError as exc:
            QMessageBox.warning(
                parent or self,
                "截图工具设置",
                f"无法写入截图工具设置文件：\n{exc}",
            )
            return False
        return True

    def _screenshot_settings_update_payload(self) -> dict[str, object]:
        payload = self._screenshot_settings.to_dict()
        # Agent-owned runtime discoveries are merged from its current state.
        # Omitting them also avoids a full-settings update racing a just-saved
        # last capture region or CU-family selector fingerprint.
        payload.pop("last_region", None)
        payload.pop("cu5_selector", None)
        return payload

    def _adopt_agent_owned_screenshot_settings(self, result: object) -> None:
        if not isinstance(result, dict):
            return
        payload = result.get("settings")
        if not isinstance(payload, dict):
            return
        try:
            remote = ScreenshotSettings.from_dict(payload)
        except (TypeError, ValueError):
            return
        self._screenshot_settings = replace(
            self._screenshot_settings,
            last_region=remote.last_region,
            cu5_selector=dict(remote.cu5_selector),
        ).normalized()

    def _sync_screenshot_autostart(self, *, parent: QWidget | None = None) -> bool:
        if not sys.platform.startswith("win"):
            return True
        try:
            from fdm.platform.windows_autostart import WindowsAutostartManager

            spec = self._screenshot_agent_client.launch_spec
            manager = WindowsAutostartManager(
                value_name="FiberDiameterMeasurementScreenshotTool",
                executable=spec.program,
                arguments=(*spec.arguments, "--background"),
            )
            status = manager.set_enabled(bool(self._screenshot_settings.autostart))
            if self._screenshot_settings.autostart and not status.enabled:
                raise RuntimeError("系统未确认开机启动项。")
        except (OSError, RuntimeError, ValueError) as exc:
            QMessageBox.warning(
                parent or self,
                "截图工具开机启动",
                f"无法更新当前用户的开机启动项：\n{exc}",
            )
            return False
        return True

    def _start_configured_screenshot_tool(self, *, show_error: bool = False) -> bool:
        started_by_request = False
        try:
            launch_status = self._screenshot_agent_client.ensure_started()
            started_by_request = bool(launch_status.result.get("started", False))
            response = self._screenshot_agent_client.update_settings(
                self._screenshot_settings_update_payload()
            )
            self._adopt_agent_owned_screenshot_settings(response.result)
        except ScreenshotAgentClientError as exc:
            if started_by_request:
                try:
                    self._screenshot_agent_client.shutdown(timeout_ms=800)
                except ScreenshotAgentClientError:
                    pass
            self.screenshot_tool_action.setToolTip(f"截图工具启动失败：{exc}")
            if show_error:
                QMessageBox.warning(self, "常驻截图工具", str(exc))
            return False
        integration_errors = response.result.get("integration_errors", [])
        errors = (
            [str(item) for item in integration_errors]
            if isinstance(integration_errors, list)
            else []
        )
        self._set_screenshot_tool_action_checked(True)
        if errors:
            summary = "；".join(errors)
            self.screenshot_tool_action.setToolTip(
                f"截图工具正在运行，但部分系统集成失败：{summary}"
            )
            if show_error:
                QMessageBox.warning(
                    self,
                    "截图工具部分功能未启用",
                    "截图工具已启动，但以下设置未能应用：\n\n"
                    + "\n".join(f"• {item}" for item in errors),
                )
        else:
            self.screenshot_tool_action.setToolTip(
                "截图工具正在独立进程中运行；关闭测量工作台不会中断它"
            )
        return True

    def _toggle_screenshot_tool(self, enabled: bool) -> None:
        if self._screenshot_action_update:
            return
        if self._screenshot_settings_read_only:
            self._set_screenshot_tool_action_checked(
                bool(self._screenshot_settings.enabled)
            )
            self._save_screenshot_settings()
            return
        requested = bool(enabled)
        previous = self._screenshot_settings.normalized()
        self._screenshot_settings = replace(
            previous,
            enabled=requested,
        )
        if not requested:
            # The main switch is authoritative: switching the companion off
            # must not allow HKCU Run to silently resurrect it at next login.
            self._screenshot_settings.autostart = False
        self._screenshot_settings = self._screenshot_settings.normalized()
        if not self._save_screenshot_settings():
            self._screenshot_settings = previous
            self._set_screenshot_tool_action_checked(previous.enabled)
            return
        self._sync_screenshot_autostart()
        if requested:
            if not self._start_configured_screenshot_tool(show_error=True):
                self._screenshot_settings = previous
                self._save_screenshot_settings()
                self._set_screenshot_tool_action_checked(previous.enabled)
                self._sync_screenshot_autostart()
            return
        try:
            self._screenshot_agent_client.shutdown(timeout_ms=800)
        except ScreenshotAgentClientError as exc:
            self.statusBar().showMessage(f"截图工具退出请求失败：{exc}", 6000)
        self.screenshot_tool_action.setToolTip("独立常驻截图工具已关闭")

    def _apply_screenshot_settings(
        self,
        settings: ScreenshotSettings,
        *,
        parent: QWidget | None = None,
    ) -> bool:
        previous = self._screenshot_settings
        previous_read_only = self._screenshot_settings_read_only
        previous_load_error = self._screenshot_settings_load_error
        normalized = settings.normalized()
        replace_future_schema = False
        if self._screenshot_settings_read_only:
            if normalized.to_dict() == previous.normalized().to_dict():
                return True
            response = QMessageBox.question(
                parent or self,
                "重置截图工具设置",
                "现有截图设置来自更新版本，当前版本无法完整读取。\n\n"
                "是否确认用当前页面中的设置替换原文件？",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if response != QMessageBox.StandardButton.Yes:
                return False
            replace_future_schema = True
            self._screenshot_settings_read_only = False
            self._screenshot_settings_load_error = ""
        if normalized.autostart:
            normalized.enabled = True
        self._screenshot_settings = normalized
        if not self._save_screenshot_settings(
            parent=parent,
            allow_unsupported_replace=replace_future_schema,
        ):
            self._screenshot_settings = previous
            self._screenshot_settings_read_only = previous_read_only
            self._screenshot_settings_load_error = previous_load_error
            return False
        autostart_ok = self._sync_screenshot_autostart(parent=parent)
        self._set_screenshot_tool_action_checked(normalized.enabled)
        if normalized.enabled:
            started = self._start_configured_screenshot_tool(show_error=True)
            if not started:
                self._screenshot_settings = previous
                self._save_screenshot_settings(parent=parent)
                self._set_screenshot_tool_action_checked(previous.enabled)
                self._sync_screenshot_autostart(parent=parent)
                return False
        elif previous.enabled:
            try:
                self._screenshot_agent_client.shutdown(timeout_ms=800)
            except ScreenshotAgentClientError as exc:
                self.statusBar().showMessage(f"截图工具退出请求失败：{exc}", 6000)
        return autostart_ok

    def _request_screenshot_capture(self, mode: CaptureMode) -> None:
        enabled_for_request = not self._screenshot_settings.enabled
        previous = self._screenshot_settings.normalized()
        started_by_request = False
        settings_applied = False
        if enabled_for_request:
            self._screenshot_settings = replace(previous, enabled=True).normalized()
            if not self._save_screenshot_settings():
                self._screenshot_settings = previous
                self._set_screenshot_tool_action_checked(previous.enabled)
                return
            self._set_screenshot_tool_action_checked(True)
        try:
            launch_status = self._screenshot_agent_client.ensure_started()
            started_by_request = bool(launch_status.result.get("started", False))
            response = self._screenshot_agent_client.update_settings(
                self._screenshot_settings_update_payload()
            )
            settings_applied = True
            self._adopt_agent_owned_screenshot_settings(response.result)
            integration_errors = response.result.get("integration_errors", [])
            if isinstance(integration_errors, list) and integration_errors:
                QMessageBox.warning(
                    self,
                    "截图工具部分功能未启用",
                    "\n".join(str(item) for item in integration_errors),
                )
            self._screenshot_agent_client.capture(
                mode,
                payload={
                    "delay_ms": self._screenshot_settings.delay_ms,
                    "open_editor": self._screenshot_settings.show_editor,
                },
            )
        except ScreenshotAgentClientError as exc:
            if enabled_for_request:
                self._screenshot_settings = previous
                self._save_screenshot_settings()
                self._set_screenshot_tool_action_checked(previous.enabled)
                if started_by_request:
                    try:
                        self._screenshot_agent_client.shutdown(timeout_ms=800)
                    except ScreenshotAgentClientError:
                        pass
                elif settings_applied:
                    try:
                        self._screenshot_agent_client.update_settings(
                            self._screenshot_settings_update_payload()
                        )
                    except ScreenshotAgentClientError:
                        pass
            QMessageBox.warning(self, "截图失败", str(exc))
            return
        label = "CU 系列实时预览" if mode is CaptureMode.CU5 else "截图"
        self.statusBar().showMessage(f"已向常驻工具发送{label}请求", 3000)

    def _diagnose_cu5_preview(self, dialog: SettingsDialog) -> None:
        page = dialog._screenshot_settings_widget
        page.set_cu5_diagnostic_status("正在检测 CU 系列原生窗口层级...", success=False)
        QApplication.processEvents()
        was_running = self._screenshot_agent_client.status(timeout_ms=180).running
        started_temporarily = not was_running and not self._screenshot_settings.enabled
        try:
            self._screenshot_agent_client.ensure_started()
            response = self._send_cu5_diagnostic_with_selection(dialog)
        except ScreenshotAgentClientError as exc:
            page.set_cu5_diagnostic_status(str(exc), success=False)
            return
        finally:
            if started_temporarily:
                try:
                    self._screenshot_agent_client.shutdown(timeout_ms=800)
                except ScreenshotAgentClientError:
                    pass
        result = dict(response.result)
        rect = result.get("rect")
        if isinstance(rect, dict):
            summary = (
                f"已识别视频区域：{rect.get('width', 0)}×{rect.get('height', 0)} px，"
                f"屏幕位置 ({rect.get('x', 0)}, {rect.get('y', 0)})"
            )
        else:
            summary = str(result.get("message") or "CU 系列检测请求已完成。")
        page.set_cu5_diagnostic_status(summary, success=bool(rect))
        set_candidates = getattr(page, "set_cu5_candidates", None)
        if callable(set_candidates):
            set_candidates(
                result.get("candidates", ()),
                selected_selector=result.get("selector"),
            )

    def _select_cu5_preview_candidate(
        self,
        dialog: SettingsDialog,
        selector: object,
    ) -> None:
        from fdm.services.cu5_preview_locator import Cu5PreviewSelector

        stable_selector = Cu5PreviewSelector.from_value(selector)
        if not stable_selector.active:
            return
        selector = stable_selector.to_dict()
        page = dialog._screenshot_settings_widget
        previous = self._screenshot_settings
        self._screenshot_settings = replace(
            previous,
            cu5_selector=dict(selector),
        ).normalized()
        if not self._save_screenshot_settings(
            parent=dialog,
            preserve_agent_owned=False,
        ):
            self._screenshot_settings = previous
            return
        was_running = self._screenshot_agent_client.status(timeout_ms=180).running
        started_temporarily = not was_running and not self._screenshot_settings.enabled
        page.set_cu5_diagnostic_status("正在验证所选预览对象...", success=False)
        QApplication.processEvents()
        try:
            self._screenshot_agent_client.ensure_started()
            self._screenshot_agent_client.update_settings(
                {"cu5_selector": dict(selector)},
                timeout_ms=1_000,
            )
            response = self._send_cu5_diagnostic_with_selection(dialog)
        except ScreenshotAgentClientError as exc:
            self._screenshot_settings = previous
            rolled_back = self._save_screenshot_settings(
                parent=dialog,
                preserve_agent_owned=False,
            )
            if was_running:
                try:
                    self._screenshot_agent_client.update_settings(
                        {"cu5_selector": dict(previous.cu5_selector)},
                        timeout_ms=1_000,
                    )
                except ScreenshotAgentClientError:
                    rolled_back = False
            suffix = "；已恢复原预览对象" if rolled_back else "；恢复原预览对象失败"
            page.set_cu5_diagnostic_status(f"{exc}{suffix}", success=False)
            return
        finally:
            if started_temporarily:
                try:
                    self._screenshot_agent_client.shutdown(timeout_ms=800)
                except ScreenshotAgentClientError:
                    pass
        result = dict(response.result)
        rect = result.get("rect")
        if isinstance(rect, dict):
            page.set_cu5_diagnostic_status(
                f"已使用所选对象：{rect.get('width', 0)}×{rect.get('height', 0)} px，"
                f"屏幕位置 ({rect.get('x', 0)}, {rect.get('y', 0)})",
                success=True,
            )
        set_candidates = getattr(page, "set_cu5_candidates", None)
        if callable(set_candidates):
            set_candidates(
                result.get("candidates", ()),
                selected_selector=result.get("selector", selector),
            )

    def _send_cu5_diagnostic_with_selection(
        self,
        dialog: SettingsDialog,
    ) -> object:
        command = IPCCommand(command=CommandType.DIAGNOSE_CU5)
        try:
            return self._screenshot_agent_client.send(command, timeout_ms=2_000)
        except ScreenshotAgentCommandError as exc:
            result = dict(exc.response.result)
            candidates = result.get("candidates")
            if result.get("diagnostic") != "ambiguous" or not isinstance(candidates, list):
                raise
            choices: list[tuple[str, dict[str, object]]] = []
            from fdm.services.cu5_preview_locator import Cu5PreviewSelector

            for index, candidate in enumerate(candidates, start=1):
                if not isinstance(candidate, dict):
                    continue
                selector = Cu5PreviewSelector.from_value(candidate.get("selector"))
                rect = candidate.get("rect")
                if not selector.active or not isinstance(rect, dict):
                    continue
                try:
                    width = int(rect.get("width", 0))
                    height = int(rect.get("height", 0))
                    x = int(rect.get("x", 0))
                    y = int(rect.get("y", 0))
                    score = float(candidate.get("score", 0.0))
                except (TypeError, ValueError, OverflowError):
                    continue
                if width <= 0 or height <= 0 or not math.isfinite(score):
                    continue
                label = (
                    f"候选 {index}：{width}×{height} px，"
                    f"位置 ({x}, {y})，得分 {score:.1f}"
                )
                choices.append((label, selector.to_dict()))
            if not choices:
                raise
            labels = [label for label, _selector in choices]
            selected, accepted = QInputDialog.getItem(
                dialog,
                "选择 CU 系列实时预览区域",
                "检测到多个相近的视频区域。请选择一次；软件会保存稳定的窗口特征，"
                "后续无需手动框选：",
                labels,
                0,
                False,
            )
            if not accepted or selected not in labels:
                raise
            selector = choices[labels.index(selected)][1]
            self._screenshot_settings = replace(
                self._screenshot_settings,
                cu5_selector=selector,
            ).normalized()
            if not self._save_screenshot_settings(
                parent=dialog,
                preserve_agent_owned=False,
            ):
                raise ScreenshotAgentClientError("未能保存 CU 系列预览区域特征。")
            self._screenshot_agent_client.update_settings(
                {"cu5_selector": selector},
                timeout_ms=1_000,
            )
            return self._screenshot_agent_client.send(
                IPCCommand(command=CommandType.DIAGNOSE_CU5),
                timeout_ms=2_000,
            )

    def _settings_with_locked_digital_slide_values(self, settings: AppSettings) -> AppSettings:
        preserved = settings.normalized_copy()
        current = self._app_settings.normalized_copy()
        for field_info in fields(AppSettings):
            if field_info.name.startswith("digital_slide_"):
                setattr(preserved, field_info.name, getattr(current, field_info.name))
        return preserved

    def _apply_imported_app_settings(self, settings: AppSettings) -> None:
        self._activate_app_settings(settings)

    def _activate_app_settings(self, settings: AppSettings) -> None:
        self._app_settings = settings
        if self._object_snap_status_button is not None:
            self._object_snap_status_button.setSnapState(
                settings.object_snap_enabled,
                settings.object_snap_kinds,
            )
        if self._adaptive_layout is not None:
            self._adaptive_layout.set_layout_settings(settings.workspace_layout)
            QTimer.singleShot(0, self._adaptive_layout.restore_preferred_extents)
        self._restore_inspector_section_defaults()
        self._apply_theme_mode()
        self._refresh_theme_sensitive_icons()
        if self._measurement_tool_strip is not None:
            self._measurement_tool_strip._apply_theme_styles()
        self._apply_tool_menu_stylesheets()
        self._magic_standard_add_roi_enabled = bool(settings.magic_segment_standard_add_roi_enabled)
        self._magic_standard_subtract_roi_enabled = bool(settings.magic_segment_standard_subtract_roi_enabled)
        self._magic_standard_subtract_input_mode = MagicSegmentSubtractInputMode.normalize(
            getattr(settings, "magic_segment_standard_subtract_input_mode", MagicSegmentSubtractInputMode.SMART)
        )
        self._fiber_quick_roi_enabled = bool(settings.fiber_quick_roi_enabled)
        if is_magic_segment_tool_mode(self._tool_mode):
            for canvas in self._canvases.values():
                self._sync_canvas_magic_subtract_input_mode(canvas)
        self._update_count_numbers_button()
        self._update_magic_segment_controls()
        if settings.selected_capture_device_id:
            self._capture_manager.set_selected_device(settings.selected_capture_device_id)
        self._apply_digital_slide_motion_settings()
        if self._digital_slide_xy_jog_step_spin is not None:
            self._digital_slide_xy_jog_step_spin.blockSignals(True)
            self._digital_slide_xy_jog_step_spin.setValue(settings.digital_slide_xy_jog_step)
            self._digital_slide_xy_jog_step_spin.blockSignals(False)
        if self._digital_slide_focus_jog_step_spin is not None:
            self._digital_slide_focus_jog_step_spin.blockSignals(True)
            self._digital_slide_focus_jog_step_spin.setValue(settings.digital_slide_z_jog_step)
            self._digital_slide_focus_jog_step_spin.blockSignals(False)
        if self._digital_slide_z_lower_edit is not None:
            self._digital_slide_z_lower_edit.blockSignals(True)
            self._set_optional_int_edit(self._digital_slide_z_lower_edit, settings.digital_slide_z_capture_lower)
            self._digital_slide_z_lower_edit.blockSignals(False)
        if self._digital_slide_z_upper_edit is not None:
            self._digital_slide_z_upper_edit.blockSignals(True)
            self._set_optional_int_edit(self._digital_slide_z_upper_edit, settings.digital_slide_z_capture_upper)
            self._digital_slide_z_upper_edit.blockSignals(False)
        if self._digital_slide_z_step_spin is not None:
            self._digital_slide_z_step_spin.blockSignals(True)
            self._digital_slide_z_step_spin.setValue(settings.digital_slide_z_capture_step)
            self._digital_slide_z_step_spin.blockSignals(False)
        if self._digital_slide_storage_codec_combo is not None:
            self._digital_slide_storage_codec_combo.blockSignals(True)
            codec_index = self._digital_slide_storage_codec_combo.findData(normalize_tile_codec(settings.digital_slide_capture_tile_codec))
            self._digital_slide_storage_codec_combo.setCurrentIndex(codec_index if codec_index >= 0 else 0)
            self._digital_slide_storage_codec_combo.blockSignals(False)
        if self._digital_slide_jpeg_quality_slider is not None:
            self._digital_slide_jpeg_quality_slider.blockSignals(True)
            self._digital_slide_jpeg_quality_slider.setValue(normalize_jpeg_quality(settings.digital_slide_capture_jpeg_quality))
            self._digital_slide_jpeg_quality_slider.blockSignals(False)
        self._sync_digital_slide_storage_quality_visibility()
        self._sync_digital_slide_task_state()
        self._update_capture_device_ui()
        self._refresh_preset_combo()
        self._refresh_canvases_for_settings()
        self._refresh_object_inspector()

    def open_shortcut_help_dialog(self) -> None:
        dialog = ShortcutHelpDialog(self)
        dialog.exec()

    def _refresh_canvases_for_settings(self) -> None:
        for canvas in self._canvases.values():
            canvas.set_settings(self._app_settings)
            canvas.set_show_area_fill(self._show_area_fill)
        navigator_enabled = bool(self._app_settings.show_canvas_navigator)
        for navigator in self._canvas_navigators.values():
            navigator.set_navigator_enabled(navigator_enabled)
        self.toggle_canvas_navigator_action.blockSignals(True)
        self.toggle_canvas_navigator_action.setChecked(navigator_enabled)
        self.toggle_canvas_navigator_action.blockSignals(False)
        if self._preview_canvas is not None:
            self._preview_canvas.set_settings(self._app_settings)
            self._preview_canvas.set_show_area_fill(False)
        self._populate_group_list(self.current_document())
        self._populate_measurement_table(self.current_document())
        self._update_action_states()

    def _begin_scale_anchor_pick(self, document: ImageDocument | None) -> None:
        if document is None:
            return
        self._set_current_document(document.id)
        canvas = self._canvases.get(document.id)
        if canvas is None:
            return
        self.statusBar().showMessage("请在画布中单击比例尺起点位置。", 5000)
        canvas.begin_scale_anchor_pick()

    def import_cu_calibration_presets(self) -> None:
        if _CU_SCALE_IMPORT_ERROR is not None:
            QMessageBox.warning(self, "导入CU标尺", f"当前版本缺少 CU 标尺导入模块。\n{_CU_SCALE_IMPORT_ERROR}")
            return
        paths, _ = QFileDialog.getOpenFileNames(self, "导入CU标尺", "", "CU 标尺 (*.scl)")
        if not paths:
            return
        parsed_records: list[object] = []
        failures: list[str] = []
        for path in paths:
            try:
                parsed_records.append(parse_cu_scale_file(path))
            except Exception as exc:
                failures.append(f"{Path(path).name}: {exc}")
        if not parsed_records:
            QMessageBox.warning(self, "导入CU标尺", "\n".join(failures) if failures else "没有可导入的 CU 标尺。")
            return
        parsed_presets = [record.preset for record in parsed_records]
        plan = self._plan_imported_preset_batch(parsed_presets, dedupe_by_content_only=True)
        preview_text = self._build_cu_import_preview_text(parsed_records, plan, failures=failures)
        if not self._confirm_cu_import_preview(preview_text):
            self.statusBar().showMessage("已取消导入 CU 标尺", 3000)
            return
        imported_count, skipped_count, renamed_count = self._apply_imported_preset_plan(plan)
        if imported_count:
            self._save_app_settings(context="导入CU标尺")
            self._refresh_preset_combo()
            self.statusBar().showMessage(f"已导入 {imported_count} 个 CU 标尺预设", 4000)
        if failures or skipped_count or renamed_count or imported_count == 0:
            summary_lines = [
                f"成功导入 {imported_count} 个预设",
                f"跳过重复 {skipped_count} 个",
                f"自动改名 {renamed_count} 个",
            ]
            if failures:
                summary_lines.append("")
                summary_lines.append("失败文件:")
                summary_lines.extend(failures[:8])
            QMessageBox.information(self, "导入CU标尺", "\n".join(summary_lines))

    def add_calibration_preset(self) -> None:
        pixel_distance, actual_distance, unit = self._default_preset_dialog_values(self.current_document())
        dialog = CalibrationPresetDialog(
            self,
            initial_pixel_distance=pixel_distance,
            initial_actual_distance=actual_distance,
            initial_unit=unit,
        )
        if dialog.exec() != dialog.DialogCode.Accepted:
            return
        name, pixel_distance, actual_distance, pixels_per_unit, unit = dialog.values()
        if not name:
            QMessageBox.warning(self, "新增预设", "预设名称不能为空。")
            return
        self._app_settings.calibration_presets.append(
            CalibrationPreset(
                name=name,
                pixels_per_unit=pixels_per_unit,
                unit=unit,
                pixel_distance=pixel_distance,
                actual_distance=actual_distance,
                computed_pixels_per_unit=pixels_per_unit,
            )
        )
        self._save_app_settings(context="新增预设")
        self._refresh_preset_combo(selected_name=name)
        self.statusBar().showMessage(f"已新增标定预设: {name}", 4000)

    def edit_selected_preset(self) -> None:
        selected = self._selected_preset()
        if selected is None:
            return
        preset_index, preset = selected
        initial_pixel_distance = preset.pixel_distance if preset.pixel_distance is not None else max(preset.resolved_pixels_per_unit(), 0.000001)
        initial_actual_distance = preset.actual_distance if preset.actual_distance is not None else 1.0
        dialog = CalibrationPresetDialog(
            self,
            title="编辑标定预设",
            initial_name=preset.name,
            initial_pixel_distance=initial_pixel_distance,
            initial_actual_distance=initial_actual_distance,
            initial_unit=preset.unit,
        )
        if dialog.exec() != dialog.DialogCode.Accepted:
            return
        name, pixel_distance, actual_distance, pixels_per_unit, unit = dialog.values()
        if not name:
            QMessageBox.warning(self, "编辑预设", "预设名称不能为空。")
            return
        self._app_settings.calibration_presets[preset_index] = CalibrationPreset(
            name=name,
            pixels_per_unit=pixels_per_unit,
            unit=unit,
            pixel_distance=pixel_distance,
            actual_distance=actual_distance,
            computed_pixels_per_unit=pixels_per_unit,
        )
        self._save_app_settings(context="编辑预设")
        self._refresh_preset_combo(selected_name=name)
        self.statusBar().showMessage(f"已更新标定预设: {name}", 4000)

    def delete_selected_preset(self) -> None:
        selected = self._selected_preset()
        if selected is None:
            return
        preset_index, preset = selected
        result = QMessageBox.question(
            self,
            "删除预设",
            f"确定删除标定预设“{preset.name}”吗？",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        if result != QMessageBox.StandardButton.Yes:
            return
        del self._app_settings.calibration_presets[preset_index]
        self._save_app_settings(context="删除预设")
        self._refresh_preset_combo()
        self.statusBar().showMessage(f"已删除标定预设: {preset.name}", 4000)

    def apply_selected_preset(self) -> None:
        document = self.current_document()
        selected = self._selected_preset()
        if document is None or selected is None:
            return
        _, preset = selected
        scope = self._prompt_preset_apply_scope(preset)
        if scope is None:
            return

        if scope == "project_all":
            self._apply_project_default_calibration(preset.to_calibration(), label="应用项目统一标尺")
            self.statusBar().showMessage(f"已将标定预设应用到当前项目: {preset.name}", 4000)
            return

        def mutate() -> None:
            document.calibration = preset.to_calibration()
            document.recalculate_measurements()
            document.metadata.pop("calibration_line", None)

        self._apply_document_change(
            document,
            "应用标定预设",
            mutate,
            sync_sidecar=True,
            impact=DocumentChangeImpact.CALIBRATION,
        )
        self.statusBar().showMessage(f"已应用标定预设: {preset.name}", 4000)

    def add_fiber_group(self) -> None:
        document = self.current_document()
        if document is None:
            return
        dialog = FiberGroupDialog(
            self,
            title="新增类别",
            initial_color=self._next_group_color(document),
        )
        if dialog.exec() != dialog.DialogCode.Accepted:
            return
        label, selected_color, apply_to_project = dialog.values()
        token = normalize_group_label(label)
        if apply_to_project and not token:
            QMessageBox.warning(self, "新增类别", "应用到当前项目全局时，类别名称不能为空。")
            return

        template = self._project_group_template_for_label(token) if token else None
        existing_group = document.find_group_by_label(token) if token else None
        if template is not None:
            color = template.color
        elif apply_to_project:
            color = self._normalize_group_color(selected_color, fallback=self._next_group_color(document))
        elif existing_group is not None:
            color = existing_group.color
        else:
            color = self._normalize_group_color(selected_color, fallback=self._next_group_color(document))
        template_added = False
        if apply_to_project:
            template_added = self._ensure_project_group_template(label=token, color=color)

        def mutate() -> None:
            if token:
                self._ensure_document_named_group(
                    document,
                    label=token,
                    color=color,
                    activate=True,
                    sync_color=apply_to_project or template is not None,
                )
            else:
                group = document.create_group(
                    color=color,
                    label="",
                )
                document.set_active_group(group.id)

        current_changed = self._apply_document_change(document, "新增类别", mutate)
        sync_changed = self._sync_project_group_templates(label="同步项目全局类别") if apply_to_project else False
        self._update_ui_for_current_document()
        self._focus_current_canvas()

        if apply_to_project:
            if current_changed or sync_changed or template_added:
                self.statusBar().showMessage(f"已更新项目全局类别: {token}", 3000)
            else:
                self.statusBar().showMessage(f"项目全局类别已存在: {token}", 3000)
            return
        if token and not current_changed:
            self.statusBar().showMessage(f"同名类别已存在，已切换到现有类别: {token}", 3000)
            return
        self.statusBar().showMessage("已新增类别", 3000)

    def rename_active_group(self) -> None:
        document = self.current_document()
        if document is None:
            return
        group = document.get_group(document.active_group_id)
        if group is None:
            if document.active_group_id is None:
                self._rename_uncategorized_group(document)
            return
        dialog = FiberGroupDialog(
            self,
            title="编辑类别",
            initial_label=group.label,
            initial_color=group.color,
            apply_to_project_default=False,
            show_apply_to_project=True,
        )
        if dialog.exec() != dialog.DialogCode.Accepted:
            return
        label, selected_color, apply_to_project = dialog.values()
        target_label = normalize_group_label(label)
        if apply_to_project and not target_label:
            QMessageBox.warning(self, "编辑类别", "应用到当前项目全局时，类别名称不能为空。")
            return
        selected_qcolor = QColor(selected_color)
        target_color = selected_qcolor.name() if selected_qcolor.isValid() else selected_color.strip() or group.color
        current_label = normalize_group_label(group.label)
        current_qcolor = QColor(group.color)
        current_color = current_qcolor.name() if current_qcolor.isValid() else group.color
        if target_label == current_label and target_color == current_color and not apply_to_project:
            return
        merge_target = document.find_group_by_label(target_label) if target_label else None
        if merge_target is not None and merge_target.id != group.id:
            response = QMessageBox.question(
                self,
                "合并类别",
                f"当前图片中已存在类别“{target_label}”。\n\n确认后会将“{group.display_name()}”合并到该类别。",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if response != QMessageBox.StandardButton.Yes:
                return
            template_changed = (
                self._apply_project_group_template_edit(original_label=current_label, target_label=target_label, color=target_color)
                if apply_to_project
                else False
            )

            def mutate_merge() -> None:
                source = document.get_group(group.id)
                target = document.get_group(merge_target.id)
                if source is None or target is None:
                    return
                if apply_to_project or self._project_group_template_for_label(target_label) is not None:
                    target.color = target_color
                source_label = normalize_group_label(source.label)
                target_token = normalize_group_label(target.label)
                document.merge_group_into(source.id, target.id)
                if self._project_group_template_for_label(source_label) is not None:
                    document.suppress_project_group_label(source_label)
                if self._project_group_template_for_label(target_token) is not None:
                    document.unsuppress_project_group_label(target_token)

            changed = self._apply_document_change(document, "合并类别", mutate_merge)
            sync_changed = (
                self._sync_project_group_template_edit_to_documents(
                    original_label=current_label,
                    target_label=target_label,
                    color=target_color,
                    history_label="同步项目全局类别",
                )
                if apply_to_project
                else False
            )
            if apply_to_project:
                self._update_ui_for_current_document()
                self._focus_current_canvas()
                if changed or sync_changed or template_changed:
                    self.statusBar().showMessage(f"已更新项目全局类别: {target_label}", 3000)
                else:
                    self.statusBar().showMessage(f"项目全局类别已存在: {target_label}", 3000)
                return
            if changed:
                self.statusBar().showMessage("类别已合并", 3000)
            return

        template_changed = (
            self._apply_project_group_template_edit(original_label=current_label, target_label=target_label, color=target_color)
            if apply_to_project
            else False
        )

        def mutate_rename() -> None:
            target = document.get_group(group.id)
            if target is None:
                return
            original_label = normalize_group_label(target.label)
            target.label = target_label
            target.color = target_color
            if original_label and original_label != target_label and self._project_group_template_for_label(original_label) is not None:
                document.suppress_project_group_label(original_label)
            if self._project_group_template_for_label(target_label) is not None:
                document.unsuppress_project_group_label(target_label)

        changed = self._apply_document_change(document, "编辑类别", mutate_rename)
        sync_changed = (
            self._sync_project_group_template_edit_to_documents(
                original_label=current_label,
                target_label=target_label,
                color=target_color,
                history_label="同步项目全局类别",
            )
            if apply_to_project
            else False
        )
        if apply_to_project:
            self._update_ui_for_current_document()
            self._focus_current_canvas()
            if changed or sync_changed or template_changed:
                self.statusBar().showMessage(f"已更新项目全局类别: {target_label}", 3000)
            else:
                self.statusBar().showMessage(f"项目全局类别已存在: {target_label}", 3000)
            return
        if changed:
            self.statusBar().showMessage("类别已更新", 3000)

    def _rename_uncategorized_group(self, document: ImageDocument) -> None:
        dialog = FiberGroupDialog(
            self,
            title="编辑未分类",
            initial_label="",
            initial_color=self._app_settings.default_measurement_color,
            apply_to_project_default=False,
            show_apply_to_project=True,
        )
        if dialog.exec() != dialog.DialogCode.Accepted:
            return
        label, selected_color, apply_to_project = dialog.values()
        target_label = normalize_group_label(label)
        if apply_to_project and not target_label:
            QMessageBox.warning(self, "编辑未分类", "应用到当前项目全局时，类别名称不能为空。")
            return
        if not target_label:
            QMessageBox.warning(self, "编辑未分类", "类别名称不能为空。")
            return
        template = self._project_group_template_for_label(target_label)
        merge_target = document.find_group_by_label(target_label)
        if template is not None:
            target_color = template.color
        elif apply_to_project:
            target_color = self._normalize_group_color(selected_color, fallback=self._app_settings.default_measurement_color)
        elif merge_target is not None:
            target_color = merge_target.color
        else:
            target_color = self._normalize_group_color(selected_color, fallback=self._app_settings.default_measurement_color)
        template_added = False
        if merge_target is not None:
            response = QMessageBox.question(
                self,
                "合并类别",
                f"当前图片中已存在类别“{target_label}”。\n\n确认后会将未分类测量合并到该类别。",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if response != QMessageBox.StandardButton.Yes:
                return
            if apply_to_project:
                template_added = self._ensure_project_group_template(label=target_label, color=target_color)

            def mutate_merge() -> None:
                target = document.get_group(merge_target.id)
                if target is None:
                    return
                if apply_to_project or template is not None:
                    target.color = target_color
                document.move_uncategorized_measurements_to_group(target.id)
                target_token = normalize_group_label(target.label)
                if self._project_group_template_for_label(target_token) is not None:
                    document.unsuppress_project_group_label(target_token)

            changed = self._apply_document_change(document, "合并未分类", mutate_merge)
            sync_changed = (
                self._sync_project_group_templates(label="同步项目全局类别", labels={target_label})
                if apply_to_project
                else False
            )
            self._update_ui_for_current_document()
            self._focus_current_canvas()
            if apply_to_project:
                if changed or sync_changed or template_added:
                    self.statusBar().showMessage(f"已更新项目全局类别: {target_label}", 3000)
                else:
                    self.statusBar().showMessage(f"项目全局类别已存在: {target_label}", 3000)
                return
            if changed:
                self.statusBar().showMessage("未分类已合并到现有类别", 3000)
            return

        if apply_to_project:
            template_added = self._ensure_project_group_template(label=target_label, color=target_color)

        def mutate_create() -> None:
            group = document.create_group(color=target_color, label=target_label)
            document.move_uncategorized_measurements_to_group(group.id)
            document.set_active_group(group.id)
            if self._project_group_template_for_label(target_label) is not None:
                document.unsuppress_project_group_label(target_label)

        changed = self._apply_document_change(document, "编辑未分类", mutate_create)
        sync_changed = (
            self._sync_project_group_templates(label="同步项目全局类别", labels={target_label})
            if apply_to_project
            else False
        )
        self._update_ui_for_current_document()
        self._focus_current_canvas()
        if apply_to_project:
            if changed or sync_changed or template_added:
                self.statusBar().showMessage(f"已更新项目全局类别: {target_label}", 3000)
            else:
                self.statusBar().showMessage(f"项目全局类别已存在: {target_label}", 3000)
            return
        if changed:
            self.statusBar().showMessage("未分类已迁移到新类别", 3000)

    def delete_active_group(self) -> None:
        document = self.current_document()
        if document is None:
            return
        group = document.get_group(document.active_group_id)
        if group is not None:
            measurement_count = len(group.measurement_ids)
            message = f"确定删除类别“{group.display_name()}”吗？"
            if measurement_count:
                message += f"\n\n该类别下的 {measurement_count} 条测量会合并到未分类。"
            response = QMessageBox.question(
                self,
                "删除类别",
                message,
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if response != QMessageBox.StandardButton.Yes:
                return

            def mutate() -> None:
                target = document.get_group(group.id)
                if target is None:
                    return
                template_label = normalize_group_label(target.label)
                document.remove_group_to_uncategorized(target.id)
                if self._project_group_template_for_label(template_label) is not None:
                    document.suppress_project_group_label(template_label)

            changed = self._apply_document_change(document, "删除类别", mutate)
            if changed:
                self.statusBar().showMessage("类别已删除", 3000)
            return

        if document.uncategorized_measurement_count() > 0:
            QMessageBox.information(
                self,
                "删除未分类",
                "未分类中仍有测量记录，请先将这些记录改到其它类别后再删除。",
            )
            return
        if not document.fiber_groups:
            QMessageBox.information(
                self,
                "删除未分类",
                "当前没有其它类别，未分类会作为默认入口保留。",
            )
            return
        response = QMessageBox.question(
            self,
            "删除未分类",
            "确定删除未分类入口吗？后续若再次出现未分类测量，它会自动恢复。",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        if response != QMessageBox.StandardButton.Yes:
            return

        def mutate() -> None:
            document.hide_uncategorized_entry()

        self._apply_document_change(document, "删除未分类", mutate)
        self.statusBar().showMessage("未分类入口已隐藏", 3000)

    def _prompt_measurement_dependency_action(
        self,
        targets: dict[str, tuple[ImageDocument, tuple[str, ...]]],
    ) -> str | None:
        dependent_names: list[str] = []
        dependent_count = 0
        locked_dependent_names: list[str] = []
        for document, measurement_ids in targets.values():
            dependent_ids = transitive_dependents(
                document.construction_entities,
                measurement_ids,
                source_kind=SourceObjectKind.MEASUREMENT,
            )
            dependent_count += len(dependent_ids)
            dependent_names.extend(
                entity.name
                for entity in document.construction_entities
                if entity.id in dependent_ids
            )
            locked_dependent_names.extend(
                entity.name or entity.id
                for entity in document.construction_entities
                if entity.id in dependent_ids and entity.locked
            )
        if dependent_count == 0:
            return "direct"
        if locked_dependent_names:
            locked_summary = "、".join(locked_dependent_names[:8])
            if len(locked_dependent_names) > 8:
                locked_summary += f" 等 {len(locked_dependent_names)} 个"
            QMessageBox.warning(
                self,
                "测量来源存在锁定下游",
                "待删除测量影响到已锁定的辅助对象，不能级联删除或冻结来源："
                f"\n{locked_summary}\n\n请先解锁这些辅助对象后重试。",
            )
            return None
        summary = "、".join(dependent_names[:8])
        if len(dependent_names) > 8:
            summary += f" 等 {len(dependent_names)} 个"
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.Warning)
        box.setWindowTitle("测量对象被辅助几何引用")
        box.setText(
            f"待删除测量被 {dependent_count} 个辅助对象直接或间接引用：\n{summary}"
        )
        box.setInformativeText(
            "可级联删除这些辅助对象，或先冻结当前来源几何并保留下游。"
        )
        cancel_button = box.addButton("取消", QMessageBox.ButtonRole.RejectRole)
        freeze_button = box.addButton(
            "解除关联并保留下游",
            QMessageBox.ButtonRole.ActionRole,
        )
        cascade_button = box.addButton(
            "级联删除",
            QMessageBox.ButtonRole.DestructiveRole,
        )
        box.setDefaultButton(cancel_button)
        box.exec()
        clicked = box.clickedButton()
        if clicked is cascade_button:
            return "cascade"
        if clicked is freeze_button:
            return "freeze"
        return None

    @staticmethod
    def _remove_measurements_with_dependencies(
        document: ImageDocument,
        measurement_ids: tuple[str, ...],
        dependency_action: str,
    ) -> int:
        targets = tuple(dict.fromkeys(item for item in measurement_ids if item))
        if not targets:
            return 0
        dependent_ids = transitive_dependents(
            document.construction_entities,
            targets,
            source_kind=SourceObjectKind.MEASUREMENT,
        )
        locked_dependent_ids = tuple(
            entity.id
            for entity in document.construction_entities
            if entity.id in dependent_ids and entity.locked
        )
        if locked_dependent_ids:
            raise ConstructionValidationError(
                "locked_dependent_objects",
                "待删除测量影响到已锁定的辅助对象，请先解锁后重试",
                locked_dependent_ids,
            )
        if dependent_ids and dependency_action == "cascade":
            document.remove_construction_entities(
                dependent_ids,
                mark_dirty=False,
            )
        elif dependent_ids and dependency_action == "freeze":
            resolver = make_construction_resolver(document)
            replacements: dict[str, ConstructionEntity] = {}
            for entity in document.construction_entities:
                if entity.id not in dependent_ids:
                    continue
                detached = detach_live_sources(
                    entity,
                    resolver,
                    source_ids=targets,
                    source_kind=SourceObjectKind.MEASUREMENT,
                )
                if detached is not entity:
                    replacements[entity.id] = replace(
                        detached,
                        revision=entity.revision + 1,
                    )
            if replacements:
                document.construction_entities = [
                    replacements.get(entity.id, entity)
                    for entity in document.construction_entities
                ]
                document.mark_construction_geometry_changed()
        elif dependent_ids:
            raise ConstructionValidationError(
                "dependent_objects",
                "测量对象仍被辅助几何引用",
                dependent_ids,
            )
        return document.remove_measurements(list(targets))

    def delete_selected_measurement(self) -> None:
        document = self.current_document()
        if self._tool_mode == "calibration" or document is None:
            return
        if document.selected_construction_id is not None:
            self._on_construction_delete_requested(
                (document.selected_construction_id,)
            )
            self._focus_current_canvas()
            return
        selected_measurement_ids = self._selected_measurement_ids_from_table()
        if selected_measurement_ids:
            label = "删除测量" if len(selected_measurement_ids) == 1 else "批量删除测量"
            target_ids = tuple(selected_measurement_ids)
            action = self._prompt_measurement_dependency_action(
                {document.id: (document, target_ids)}
            )
            if action is None:
                return

            def mutate_rows() -> None:
                self._remove_measurements_with_dependencies(
                    document,
                    target_ids,
                    action,
                )

            self._apply_document_change(
                document,
                label,
                mutate_rows,
                impact=(
                    DocumentChangeImpact.SESSION
                    | DocumentChangeImpact.GEOMETRY
                    | DocumentChangeImpact.CONSTRUCTION
                ),
                geometry_measurement_ids=target_ids,
            )
            self._focus_current_canvas()
            return
        if document.selected_overlay_id is not None:
            overlay_id = document.selected_overlay_id
            overlay = document.get_overlay_annotation(overlay_id)

            def mutate_overlay() -> None:
                document.remove_overlay_annotation(overlay_id)

            label = "删除标注"
            if overlay is not None and overlay.normalized_kind() == OverlayAnnotationKind.TEXT:
                label = "删除文字"
            self._apply_document_change(document, label, mutate_overlay)
            self._focus_current_canvas()
            return
        if document.view_state.selected_measurement_id is None:
            return
        measurement_id = document.view_state.selected_measurement_id
        action = self._prompt_measurement_dependency_action(
            {document.id: (document, (measurement_id,))}
        )
        if action is None:
            return

        def mutate() -> None:
            self._remove_measurements_with_dependencies(
                document,
                (measurement_id,),
                action,
            )

        self._apply_document_change(
            document,
            "删除测量",
            mutate,
            impact=(
                DocumentChangeImpact.SESSION
                | DocumentChangeImpact.GEOMETRY
                | DocumentChangeImpact.CONSTRUCTION
            ),
            geometry_measurement_ids=(measurement_id,),
        )

    def delete_all_measurements(self) -> None:
        document = self.current_document()
        if document is None or self._tool_mode == "calibration":
            return
        if not any(item.measurements for item in self.project.documents):
            return
        selection = self._prompt_measurement_delete_options(
            title="删除全部测量",
            message="确认删除测量数据。你可以选择删除当前图片，或整个项目中的全部测量数据。",
        )
        if selection is None:
            return
        scope, _group_label = selection
        target_documents = [document] if scope == ExportScope.CURRENT else list(self.project.documents)
        target_map = {
            item.id: (
                item,
                tuple(measurement.id for measurement in item.measurements),
            )
            for item in target_documents
            if item.measurements
        }
        action = self._prompt_measurement_dependency_action(target_map)
        if action is None:
            return
        removed_count = self._apply_documents_change(
            target_documents,
            "删除全部测量",
            lambda item: self._remove_measurements_with_dependencies(
                item,
                target_map.get(item.id, (item, ()))[1],
                action,
            ),
            workspace_scope=scope == ExportScope.ALL_OPEN,
            impact=(
                DocumentChangeImpact.SESSION
                | DocumentChangeImpact.GEOMETRY
                | DocumentChangeImpact.CONSTRUCTION
            ),
        )
        if removed_count > 0:
            scope_label = "当前图片" if scope == ExportScope.CURRENT else "整个项目"
            self.statusBar().showMessage(f"已删除 {scope_label}中的 {removed_count} 条测量记录", 4000)
            self._focus_current_canvas()

    def delete_measurements_by_category(self) -> None:
        document = self.current_document()
        if document is None or self._tool_mode == "calibration":
            return
        group_labels = document.measurement_group_labels()
        if not group_labels:
            QMessageBox.information(self, "删除指定类别", "当前图片没有可删除的测量类别。")
            return
        selection = self._prompt_measurement_delete_options(
            title="删除指定类别",
            message="确认删除指定类别下的测量记录。类别定义、颜色模板和叠加标注不会被删除。",
            group_labels=group_labels,
        )
        if selection is None:
            return
        scope, group_label = selection
        if not group_label:
            return
        target_documents = [document] if scope == ExportScope.CURRENT else list(self.project.documents)
        target_map = {
            item.id: (
                item,
                self._measurement_ids_for_group_label(item, group_label),
            )
            for item in target_documents
        }
        target_map = {
            document_id: value
            for document_id, value in target_map.items()
            if value[1]
        }
        action = self._prompt_measurement_dependency_action(target_map)
        if action is None:
            return
        removed_count = self._apply_documents_change(
            target_documents,
            "删除指定类别测量",
            lambda item: self._remove_measurements_with_dependencies(
                item,
                target_map.get(item.id, (item, ()))[1],
                action,
            ),
            workspace_scope=scope == ExportScope.ALL_OPEN,
            impact=(
                DocumentChangeImpact.SESSION
                | DocumentChangeImpact.GEOMETRY
                | DocumentChangeImpact.CONSTRUCTION
            ),
        )
        if removed_count > 0:
            scope_label = "当前图片" if scope == ExportScope.CURRENT else "整个项目"
            self.statusBar().showMessage(f"已删除“{group_label}”在{scope_label}中的 {removed_count} 条测量记录", 4000)
            self._focus_current_canvas()

    @staticmethod
    def _measurement_ids_for_group_label(
        document: ImageDocument,
        group_label: str,
    ) -> tuple[str, ...]:
        token = normalize_group_label(group_label)
        group = document.find_group_by_label(token)
        if group is not None:
            return tuple(
                measurement.id
                for measurement in document.measurements
                if measurement.fiber_group_id == group.id
            )
        if token == normalize_group_label(UNCATEGORIZED_LABEL):
            return tuple(
                measurement.id
                for measurement in document.measurements
                if measurement.fiber_group_id is None
            )
        return ()

    def _selected_measurement_ids_from_table(self) -> list[str]:
        return self._records_controller.selected_measurement_ids()

    def _prompt_measurement_delete_options(
        self,
        *,
        title: str,
        message: str,
        group_labels: list[str] | None = None,
    ) -> tuple[str, str | None] | None:
        dialog = QDialog(self)
        dialog.setWindowTitle(title)
        layout = QVBoxLayout(dialog)
        layout.addWidget(QLabel(message, dialog))

        group_combo: QComboBox | None = None
        if group_labels:
            layout.addWidget(QLabel("删除类别：", dialog))
            group_combo = QComboBox(dialog)
            group_combo.addItems(group_labels)
            layout.addWidget(group_combo)

        layout.addWidget(QLabel("删除范围：", dialog))
        current_radio = QRadioButton("当前图片", dialog)
        current_radio.setChecked(True)
        project_radio = QRadioButton("整个项目", dialog)
        layout.addWidget(current_radio)
        layout.addWidget(project_radio)

        button_box = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel, dialog)
        ok_button = button_box.button(QDialogButtonBox.StandardButton.Ok)
        if ok_button is not None:
            ok_button.setText("删除")
        button_box.accepted.connect(dialog.accept)
        button_box.rejected.connect(dialog.reject)
        layout.addWidget(button_box)

        if dialog.exec() != dialog.DialogCode.Accepted:
            return None
        scope = ExportScope.CURRENT if current_radio.isChecked() else ExportScope.ALL_OPEN
        return scope, group_combo.currentText() if group_combo is not None else None

    def run_area_auto_recognition(self) -> None:
        if "area-inference" not in self._runtime_features:
            QMessageBox.information(self, "面积自动识别", "当前 core 发布配置未包含面积推理功能。")
            return
        if not self.project.documents:
            QMessageBox.information(self, "面积自动识别", "请先打开图片。")
            return
        mappings = self._app_settings.area_model_mappings
        if not mappings:
            QMessageBox.information(self, "面积自动识别", "请先在设置中配置面积模型名称与权重文件映射。")
            return
        dialog = AreaAutoRecognitionDialog(
            mappings,
            allow_all_scope=len(self.project.documents) > 1,
            parent=self,
        )
        if dialog.exec() != dialog.DialogCode.Accepted:
            return
        model_name, model_file, apply_all = dialog.values()
        if not model_name or not model_file:
            QMessageBox.warning(self, "面积自动识别", "请选择有效的模型配置。")
            return
        target_documents = self.project.documents if apply_all else ([self.current_document()] if self.current_document() else [])
        target_documents = [document for document in target_documents if document is not None]
        skipped_slides = [document for document in target_documents if document.is_digital_slide()]
        target_documents = [document for document in target_documents if not document.is_digital_slide()]
        if not target_documents:
            if skipped_slides:
                QMessageBox.information(self, "面积自动识别", "数字化切片文件会跳过面积自动识别。")
            return
        if skipped_slides:
            self.statusBar().showMessage(f"已跳过 {len(skipped_slides)} 个数字化切片文件。", 4000)
        requests = [
            AreaInferenceRequest(
                document_id=document.id,
                image_path=document.path,
                model_name=model_name,
                model_file=model_file,
            )
            for document in target_documents
        ]
        self._start_area_inference_batch(requests, model_name=model_name)

    def _apply_area_inference_result(
        self,
        document: ImageDocument,
        instances,
        *,
        global_group_labels: list[str] | None = None,
        model_name: str = "",
        update_project_group_templates: bool = True,
    ) -> None:
        if not instances:
            def clear_mutate() -> None:
                document.remove_auto_area_measurements()
                document.select_measurement(None)

            self._apply_document_change(document, "清除自动面积识别结果", clear_mutate)
            return

        if global_group_labels is None:
            resolved_global_group_labels = self._resolved_area_inference_group_labels(
                model_name,
                update_project_group_templates=update_project_group_templates,
            )
        elif global_group_labels:
            resolved_global_group_labels = list(global_group_labels)
        else:
            resolved_global_group_labels = self._resolved_area_inference_group_labels(
                model_name,
                update_project_group_templates=update_project_group_templates,
            )
            global_group_labels.extend(resolved_global_group_labels)
        inferred_label_order: list[str] = list(resolved_global_group_labels)
        for instance in instances:
            token = normalize_group_label(str(getattr(instance, "class_name", "")).strip() or UNCATEGORIZED_LABEL)
            if token and token not in inferred_label_order:
                inferred_label_order.append(token)
        resolved_colors = self._resolve_area_inference_group_colors(inferred_label_order)

        def mutate() -> None:
            document.remove_auto_area_measurements()
            recognized_labels = {
                normalize_group_label(str(getattr(instance, "class_name", "")).strip() or UNCATEGORIZED_LABEL)
                for instance in instances
            }
            self._normalize_document_groups_for_area_inference(
                document,
                global_group_labels=resolved_global_group_labels,
                recognized_labels=recognized_labels,
                resolved_colors=resolved_colors,
            )
            for instance in instances:
                class_name = str(instance.class_name).strip() or UNCATEGORIZED_LABEL
                group = document.ensure_group_for_label(
                    class_name,
                    color=resolved_colors.get(
                        normalize_group_label(class_name),
                        self._area_inference_group_color_for_label(class_name),
                    ),
                )
                measurement = Measurement(
                    id=new_id("meas"),
                    image_id=document.id,
                    fiber_group_id=group.id,
                    mode="auto_instance",
                    measurement_kind="area",
                    polygon_px=list(instance.polygon_px),
                    exact_area_px=float(instance.area_px),
                    confidence=float(instance.score),
                    status="auto_instance",
                )
                document.add_measurement(measurement)
            document.select_measurement(None)
            document.hide_uncategorized_entry()

        self._apply_document_change(document, "导入自动面积识别结果", mutate)

    def _on_canvas_magic_segment_requested(self, document_id: str, payload: object) -> None:
        canvas = self._canvases.get(document_id)
        document = self.project.get_document(document_id)
        if canvas is None or document is None or not isinstance(payload, dict):
            return
        image = self._images.get(document_id)
        request_id = int(payload.get("request_id", 0))
        tool_mode = str(payload.get("tool_mode", self._tool_mode) or self._tool_mode)
        if not is_magic_toolbar_tool_mode(tool_mode):
            tool_mode = MagicSegmentToolMode.STANDARD
        tool_label = self._magic_tool_label(tool_mode)
        if image is None or image.isNull():
            if is_reference_propagation_tool_mode(tool_mode):
                canvas.fail_reference_instance_result(request_id)
            elif is_fiber_quick_tool_mode(tool_mode):
                canvas.fail_fiber_quick_result(request_id)
            else:
                canvas.fail_magic_segment_result(request_id)
            self._update_magic_segment_controls()
            QMessageBox.warning(self, tool_label, "当前图片还未完成加载，暂时无法进行分割。")
            return
        cache_key = f"{document_id}:{int(image.cacheKey())}"
        requested_variant = self._app_settings.magic_segment_model_variant
        resolved_variant, _fallback_message = resolve_interactive_segmentation_backend(requested_variant)
        if not interactive_segmentation_models_ready(resolved_variant):
            if is_reference_propagation_tool_mode(tool_mode):
                canvas.fail_reference_instance_result(request_id)
            elif is_fiber_quick_tool_mode(tool_mode):
                canvas.fail_fiber_quick_result(request_id)
            else:
                canvas.fail_magic_segment_result(request_id)
            self._update_magic_segment_controls()
            model_paths = interactive_segmentation_model_paths(resolved_variant)
            runtime_root = interactive_segmentation_runtime_root(resolved_variant)
            if len(model_paths) == 1:
                missing_hint = f"请确认 {model_paths[0].as_posix()} 存在。"
            else:
                missing_hint = f"请确认 {runtime_root.as_posix()} 中存在所需模型文件。"
            QMessageBox.warning(
                self,
                tool_label,
                (
                    f"未找到 {interactive_segmentation_model_label(resolved_variant)} 模型文件，"
                    f"{missing_hint}"
                ),
            )
            return
        if is_reference_propagation_tool_mode(tool_mode):
            reference_box_payload = payload.get("reference_box")
            reference_box = None
            if isinstance(reference_box_payload, dict):
                start = reference_box_payload.get("start")
                end = reference_box_payload.get("end")
                if isinstance(start, Point) and isinstance(end, Point):
                    reference_box = (start, end)
            reference_measurement_id = str(payload.get("reference_measurement_id", "")).strip()
            reference_measurement = document.get_measurement(reference_measurement_id) if reference_measurement_id else None
            if reference_box is None and (
                reference_measurement is None
                or reference_measurement.measurement_kind != "area"
            ):
                canvas.fail_reference_instance_result(request_id)
                self._update_magic_segment_controls()
                self.statusBar().showMessage("同类扩选缺少有效参考实例", 4000)
                return
            self._ensure_reference_instance_worker()
            if self._reference_instance_worker is None:
                canvas.fail_reference_instance_result(request_id)
                self._update_magic_segment_controls()
                return
            self._reference_instance_worker.register_request(document_id, request_id)
            self._reference_instance_worker.requested.emit(
                ReferenceInstancePropagationRequest(
                    document_id=document_id,
                    image=image,
                    cache_key=cache_key,
                    request_id=request_id,
                    model_variant=requested_variant,
                    reference_box=reference_box,
                    reference_polygon_px=list(reference_measurement.polygon_px) if reference_measurement is not None else [],
                    reference_area_rings_px=[list(ring) for ring in reference_measurement.area_rings_px] if reference_measurement is not None else [],
                )
            )
            self._update_magic_segment_controls()
            return
        positive_points = list(payload.get("positive_points", []))
        negative_points = list(payload.get("negative_points", []))
        active_stage = str(payload.get("active_stage", MagicSegmentOperationMode.ADD) or MagicSegmentOperationMode.ADD)
        roi_enabled = self._current_magic_roi_enabled(tool_mode, operation_mode=active_stage)
        roi_constraint_box = None
        small_object_enhancement_enabled = False
        small_object_workspace_box = None
        if (
            is_magic_segment_tool_mode(tool_mode)
            and active_stage == MagicSegmentOperationMode.SUBTRACT
            and roi_enabled
            and self._app_settings.magic_segment_restrict_subtract_roi_to_primary_bounds
        ):
            roi_constraint_box = canvas.magic_segment_primary_bounds()
            if roi_constraint_box is not None and any(
                not canvas.point_in_box(point, roi_constraint_box)
                for point in positive_points
            ):
                canvas.reject_magic_segment_subtract_points_outside_primary_bounds(request_id)
                self._update_magic_segment_controls()
                self.statusBar().showMessage("剔除模式 ROI 已限制在主体范围内，请在主体内部添加正采样点。", 5000)
                return
            if roi_constraint_box is not None and self._app_settings.magic_segment_small_object_subtract_enhancement_enabled:
                small_object_enhancement_enabled = True
                workspace_payload = payload.get("small_object_workspace_box")
                if isinstance(workspace_payload, (tuple, list)) and len(workspace_payload) == 4:
                    try:
                        small_object_workspace_box = tuple(int(round(float(value))) for value in workspace_payload)
                    except (TypeError, ValueError):
                        small_object_workspace_box = None
                if small_object_workspace_box is None:
                    small_object_workspace_box = canvas.magic_segment_small_object_workspace_box()
        if not positive_points:
            if is_fiber_quick_tool_mode(tool_mode):
                canvas.fail_fiber_quick_result(request_id)
            else:
                canvas.apply_magic_segment_result(request_id, None)
            self._update_magic_segment_controls()
            return
        if is_fiber_quick_tool_mode(tool_mode) and roi_enabled:
            pending_crop_box = initial_interactive_segmentation_crop_box(
                image_size=(image.height(), image.width()),
                positive_points=positive_points,
                negative_points=negative_points,
                tool_mode=tool_mode,
                roi_enabled=roi_enabled,
            )
            canvas.set_fiber_quick_pending_roi(request_id, pending_crop_box)
        if is_fiber_quick_tool_mode(tool_mode) and self._fiber_quick_geometry_worker is not None:
            self._fiber_quick_geometry_worker.cancel_document(document_id)
        self._ensure_prompt_segmentation_worker()
        if self._prompt_seg_worker is None:
            if is_fiber_quick_tool_mode(tool_mode):
                canvas.fail_fiber_quick_result(request_id)
            else:
                canvas.fail_magic_segment_result(request_id)
            self._update_magic_segment_controls()
            return
        self._prompt_request_tool_modes[(document_id, request_id)] = tool_mode
        self._prompt_seg_worker.register_request(document_id, request_id)
        self._prompt_seg_worker.requested.emit(
            PromptSegmentationRequest(
                document_id=document_id,
                image=image,
                cache_key=cache_key,
                request_id=request_id,
                positive_points=positive_points,
                negative_points=negative_points,
                tool_mode=tool_mode,
                active_stage=active_stage,
                model_variant=requested_variant,
                roi_enabled=roi_enabled,
                roi_constraint_box=roi_constraint_box,
                small_object_enhancement_enabled=small_object_enhancement_enabled,
                small_object_roi_area_threshold_px=self._app_settings.magic_segment_small_object_roi_area_threshold_px,
                small_object_workspace_box=small_object_workspace_box,
            )
        )
        self._update_magic_segment_controls()

    def _on_canvas_magic_segment_session_changed(self, document_id: str) -> None:
        current_document = self.current_document()
        if current_document is not None and current_document.id == document_id:
            self._update_magic_segment_controls()

    def _on_canvas_path_session_changed(self, document_id: str) -> None:
        current_document = self.current_document()
        if current_document is not None and current_document.id == document_id:
            self._update_path_drawing_controls()

    def _on_canvas_area_edit_rejected(self, document_id: str, reason: str) -> None:
        current_document = self.current_document()
        if current_document is not None and current_document.id == document_id:
            self.statusBar().showMessage(reason, 4000)
            self._update_path_drawing_controls()

    def _dispatch_pending_magic_segment_request(self, document_id: str, completed_request_id: int) -> bool:
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return False
        payload = canvas.dequeue_pending_magic_segment_request(completed_request_id)
        if payload is None:
            return False
        self._on_canvas_magic_segment_requested(document_id, payload)
        return True

    def _dispatch_pending_fiber_quick_request(self, document_id: str, completed_request_id: int) -> bool:
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return False
        payload = canvas.dequeue_pending_fiber_quick_request(completed_request_id)
        if payload is None:
            return False
        self._on_canvas_magic_segment_requested(document_id, payload)
        return True

    def _on_prompt_segmentation_succeeded(self, document_id: str, request_id: int, result: object) -> None:
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return
        tool_mode = self._prompt_request_tool_modes.pop((document_id, request_id), None)
        if isinstance(result, PromptSegmentationResult):
            tool_mode = str(tool_mode or result.metadata.get("tool_mode", MagicSegmentToolMode.STANDARD) or MagicSegmentToolMode.STANDARD)
            if is_fiber_quick_tool_mode(tool_mode):
                debug_payload = {
                    "segmentation_roi_round": result.metadata.get("segmentation_roi_round"),
                    "segmentation_used_full_image": result.metadata.get("segmentation_used_full_image"),
                    "segmentation_crop_box": result.metadata.get("segmentation_crop_box"),
                    "component_area_px": result.metadata.get("component_area_px"),
                }
                if bool(debug_payload.get("segmentation_used_full_image")):
                    debug_payload.pop("segmentation_crop_box", None)
                apply_result = canvas.apply_fiber_quick_segmentation_result(
                    request_id,
                    mask=result.mask,
                    preview_polygon_points=result.polygon_px,
                    preview_area_rings_points=result.area_rings_px,
                    debug_payload=debug_payload,
                )
                if apply_result is None:
                    self._update_magic_segment_controls()
                    return
                if result.mask is None or len(result.polygon_px) < 3:
                    canvas.fail_fiber_quick_result(request_id, stage="segmentation")
                    self._dispatch_pending_fiber_quick_request(document_id, request_id)
                    self.statusBar().showMessage("快速测径失败: 未找到目标纤维区域。", 5000)
                    self._update_magic_segment_controls()
                    return
                if self._dispatch_pending_fiber_quick_request(document_id, request_id):
                    self.statusBar().showMessage("快速测径已更新分割结果，继续精修中。", 5000)
                    self._update_magic_segment_controls()
                    return
                self._ensure_fiber_quick_geometry_worker()
                if self._fiber_quick_geometry_worker is None:
                    canvas.fail_fiber_quick_result(request_id, stage="geometry")
                    self.statusBar().showMessage("快速测径失败: 几何线程初始化失败。", 5000)
                    self._update_magic_segment_controls()
                    return
                canvas.begin_fiber_quick_geometry(request_id)
                self._fiber_quick_geometry_request_ids.add((document_id, request_id))
                self._fiber_quick_geometry_worker.register_request(document_id, request_id)
                self._fiber_quick_geometry_worker.requested.emit(
                    FiberQuickGeometryRequest(
                        document_id=document_id,
                        request_id=request_id,
                        mask=result.mask,
                        preview_polygon_px=list(result.polygon_px),
                        preview_area_rings_px=[list(ring) for ring in result.area_rings_px],
                        positive_points=list(result.metadata.get("positive_points_px", []))
                        if isinstance(result.metadata.get("positive_points_px"), list)
                        else [],
                        negative_points=list(result.metadata.get("negative_points_px", []))
                        if isinstance(result.metadata.get("negative_points_px"), list)
                        else [],
                        edge_trim_enabled=bool(self._app_settings.fiber_quick_edge_trim_enabled),
                        line_extension_px=float(self._app_settings.fiber_quick_line_extension_px),
                        timeout_ms=DEFAULT_FIBER_QUICK_GEOMETRY_TIMEOUT_MS,
                    )
                )
                self.statusBar().showMessage("快速测径已完成分割，正在异步计算直径线。", 5000)
            else:
                small_object_used = bool(result.metadata.get("small_object_enhancement_used"))
                small_object_reject_reason = str(result.metadata.get("small_object_reject_reason", "") or "").strip()
                if small_object_used:
                    self._show_small_object_preview(canvas, result.metadata, result.polygon_px)
                else:
                    self._hide_small_object_preview()
                apply_result = canvas.apply_magic_segment_result(
                    request_id,
                    result.mask,
                    result.polygon_px,
                    result.area_rings_px,
                    {
                        "segmentation_roi_round": result.metadata.get("segmentation_roi_round"),
                        "segmentation_used_full_image": result.metadata.get("segmentation_used_full_image"),
                        "segmentation_crop_box": result.metadata.get("segmentation_crop_box"),
                        "component_area_px": result.metadata.get("component_area_px"),
                        "reason": result.metadata.get("reason"),
                        "small_object_enhancement_used": result.metadata.get("small_object_enhancement_used"),
                        "small_object_workspace_box": result.metadata.get("small_object_workspace_box"),
                        "small_object_scale": result.metadata.get("small_object_scale"),
                        "small_object_enhanced_size": result.metadata.get("small_object_enhanced_size"),
                        "small_object_reject_reason": result.metadata.get("small_object_reject_reason"),
                    },
                )
                if apply_result is None:
                    self._update_magic_segment_controls()
                    return
                if small_object_reject_reason:
                    self.statusBar().showMessage(
                        f"小目标增强未生成稳定剔除区域：{self._small_object_reject_label(small_object_reject_reason)}，请继续补点。",
                        5000,
                    )
                elif result.mask is None or not bool(apply_result.get("has_preview", False)):
                    self.statusBar().showMessage("魔棒分割失败: 未找到稳定目标区域。", 5000)
                self._dispatch_pending_magic_segment_request(document_id, request_id)
            if apply_result is None:
                self._update_magic_segment_controls()
                return
            fallback_message = str(result.metadata.get("model_fallback_message", "")).strip()
            if fallback_message:
                self.statusBar().showMessage(fallback_message, 5000)
        else:
            canvas.fail_magic_segment_result(request_id)
        self._update_magic_segment_controls()

    def _on_prompt_segmentation_failed(self, document_id: str, request_id: int, reason: str) -> None:
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return
        tool_mode = self._prompt_request_tool_modes.pop((document_id, request_id), self._tool_mode)
        if is_fiber_quick_tool_mode(tool_mode):
            canvas.fail_fiber_quick_result(request_id, stage="segmentation")
            self._dispatch_pending_fiber_quick_request(document_id, request_id)
            self.statusBar().showMessage(f"快速测径失败: {reason}", 5000)
        else:
            canvas.fail_magic_segment_result(request_id)
            self._dispatch_pending_magic_segment_request(document_id, request_id)
            self.statusBar().showMessage(f"魔棒分割失败: {reason}", 5000)
        self._update_magic_segment_controls()

    def _on_fiber_quick_geometry_succeeded(self, document_id: str, request_id: int, result: object) -> None:
        self._fiber_quick_geometry_request_ids.discard((document_id, request_id))
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return
        if hasattr(result, "line_px"):
            apply_result = canvas.apply_fiber_quick_geometry_result(
                request_id,
                preview_line=result.line_px if isinstance(result.line_px, Line) else None,
                confidence=float(getattr(result, "confidence", 0.0) or 0.0),
                debug_payload=dict(getattr(result, "debug_payload", {}))
                if isinstance(getattr(result, "debug_payload", {}), dict)
                else {},
            )
            if apply_result is None:
                self._update_magic_segment_controls()
                return
            if apply_result.get("has_preview"):
                if bool(canvas._fiber_quick.commit_pending):  # noqa: SLF001
                    commit_result = canvas.commit_fiber_quick_preview()
                    if bool(commit_result.get("committed", False)):
                        self.statusBar().showMessage("已创建快速测径线段", 4000)
                    else:
                        self.statusBar().showMessage("快速测径已生成代表线。按 Enter / F 确认。", 5000)
                else:
                    self.statusBar().showMessage("快速测径已生成代表线。按 Enter / F 确认。", 5000)
            else:
                self.statusBar().showMessage("快速测径失败: 未找到可靠直径线。", 5000)
        else:
            canvas.fail_fiber_quick_result(request_id, stage="geometry")
            self.statusBar().showMessage("快速测径失败: 未找到可靠直径线。", 5000)
        self._update_magic_segment_controls()

    def _on_fiber_quick_geometry_failed(self, document_id: str, request_id: int, reason: str) -> None:
        self._fiber_quick_geometry_request_ids.discard((document_id, request_id))
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return
        if request_id != canvas._fiber_quick.request_id:  # noqa: SLF001
            return
        canvas.fail_fiber_quick_result(request_id, stage="geometry")
        self.statusBar().showMessage(f"快速测径失败: {reason}", 5000)
        self._update_magic_segment_controls()

    def _on_reference_instance_succeeded(self, document_id: str, request_id: int, result: object) -> None:
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return
        if not isinstance(result, ReferenceInstancePropagationResult):
            canvas.fail_reference_instance_result(request_id)
            self._update_magic_segment_controls()
            return
        apply_result = canvas.apply_reference_instance_result(
            request_id,
            reference_polygon_points=result.reference_polygon_px,
            reference_area_rings_points=result.reference_area_rings_px,
            candidates=result.candidates,
        )
        if apply_result is None:
            self._update_magic_segment_controls()
            return
        fallback_message = str(result.metadata.get("model_fallback_message", "")).strip()
        if fallback_message:
            self.statusBar().showMessage(fallback_message, 5000)
        candidate_count = int(result.metadata.get("candidate_count", 0) or 0)
        if candidate_count > 0:
            self.statusBar().showMessage(f"已找到 {candidate_count} 个候选，按 Enter / F 加入当前类别。", 5000)
        else:
            self.statusBar().showMessage("未找到可用的同类候选。", 5000)
        self._update_magic_segment_controls()

    def _on_reference_instance_failed(self, document_id: str, request_id: int, reason: str) -> None:
        canvas = self._canvases.get(document_id)
        if canvas is None:
            return
        canvas.fail_reference_instance_result(request_id)
        self.statusBar().showMessage(f"同类扩选失败: {reason}", 5000)
        self._update_magic_segment_controls()

    def close_current_document(self) -> None:
        document = self.current_document()
        if document is None:
            return
        if not self._confirm_close_documents([document]):
            return
        self._remove_document(document.id)

    def close_all_documents(self) -> None:
        if not self.project.documents and not self.project_session_controller.unresolved_documents():
            return
        intent = TransitionIntent.RESET_WORKSPACE
        disposition = self._preflight_acquisition_disposition(intent)
        if disposition == AcquisitionDisposition.CANCEL:
            QMessageBox.information(self, "重置工作区", "操作已取消。")
            return
        if not self._confirm_close_documents(self.project.documents):
            return
        transition = self._prepare_transition(intent, disposition=disposition)
        if not transition.completed:
            QMessageBox.information(
                self,
                "重置工作区",
                transition.reason or "资源尚未安全退出，已取消重置工作区。",
            )
            return
        try:
            self._reset_workspace()
        except RuntimeError as exc:
            QMessageBox.information(
                self,
                "重置工作区",
                f"资源尚未安全退出，已取消重置工作区。\n\n{exc}",
            )
            return
        self._update_ui_for_current_document()

    def undo_current_document(self) -> None:
        document = self.current_document()
        if document is None:
            return
        self._prune_invalid_workspace_composites()
        if self._undo_workspace_composite_for(document):
            return
        if self._workspace_composite_waits_on_other_document(document, redo=False):
            self.statusBar().showMessage(
                "该项目级命令在另一张图片上还有较新的改动；请先撤销那些改动，以保持整批操作原子。",
                5000,
            )
            return
        if document.history is None:
            return
        previous_measurements = tuple(document.measurements)
        if not document.history.undo(document):
            return
        self._discard_detached_area_geometry(previous_measurements, document)
        if DirtyDomain.CALIBRATION in document.history.last_affected_domains:
            if document.calibration is not None and (document.calibration.mode == "project_default" or not document.uses_sidecar()):
                document.mark_calibration_saved()
            else:
                self._save_calibration_sidecar(document, context="撤销")
        self._refresh_document_analysis_validity(document)
        self._update_ui_for_current_document()

    def redo_current_document(self) -> None:
        document = self.current_document()
        if document is None:
            return
        self._prune_invalid_workspace_composites()
        if self._redo_workspace_composite_for(document):
            return
        if self._workspace_composite_waits_on_other_document(document, redo=True):
            self.statusBar().showMessage(
                "该项目级命令在另一张图片上还有较新的历史项；请先处理那些历史项，以保持整批操作原子。",
                5000,
            )
            return
        if document.history is None:
            return
        previous_measurements = tuple(document.measurements)
        if not document.history.redo(document):
            return
        self._discard_detached_area_geometry(previous_measurements, document)
        if DirtyDomain.CALIBRATION in document.history.last_affected_domains:
            if document.calibration is not None and (document.calibration.mode == "project_default" or not document.uses_sidecar()):
                document.mark_calibration_saved()
            else:
                self._save_calibration_sidecar(document, context="重做")
        self._refresh_document_analysis_validity(document)
        self._update_ui_for_current_document()

    def _workspace_composite_ready(
        self,
        entry: WorkspaceCompositeHistoryEntry,
        *,
        redo: bool,
    ) -> bool:
        for document_id, sequence in entry.document_sequences:
            document = self.project.get_document(document_id)
            history = document.history if document is not None else None
            if history is None:
                return False
            latest = (
                history.latest_redo_sequence
                if redo
                else history.latest_undo_sequence
            )
            if latest != sequence:
                return False
        return True

    def _workspace_composite_intact(
        self,
        entry: WorkspaceCompositeHistoryEntry,
        *,
        redo: bool,
    ) -> bool:
        for document_id, sequence in entry.document_sequences:
            document = self.project.get_document(document_id)
            history = document.history if document is not None else None
            if history is None:
                return False
            contains = (
                history.contains_redo_sequence(sequence)
                if redo
                else history.contains_undo_sequence(sequence)
            )
            if not contains:
                return False
        return True

    def _discard_workspace_composite_entry(
        self,
        entry: WorkspaceCompositeHistoryEntry,
    ) -> None:
        sequences_by_document: dict[str, set[int]] = {}
        for document_id, sequence in entry.document_sequences:
            sequences_by_document.setdefault(document_id, set()).add(sequence)
        for document_id, sequences in sequences_by_document.items():
            document = self.project.get_document(document_id)
            history = document.history if document is not None else None
            if history is not None:
                history.discard_sequences(sequences)

    def _discard_workspace_composite_redo(self) -> None:
        for entry in tuple(self._workspace_composite_redo):
            self._discard_workspace_composite_entry(entry)
        self._workspace_composite_redo.clear()

    def _prune_invalid_workspace_composites(self) -> None:
        """Remove coordinator entries that can no longer run atomically.

        Per-document limits and workspace-wide byte eviction operate below the
        coordinator.  Once any participant command is gone, retain neither the
        coordinator entry nor the other participants' now-orphaned commands.
        """

        for stack, redo in (
            (self._workspace_composite_undo, False),
            (self._workspace_composite_redo, True),
        ):
            invalid = [
                entry
                for entry in stack
                if not self._workspace_composite_intact(entry, redo=redo)
            ]
            if not invalid:
                continue
            invalid_ids = {id(entry) for entry in invalid}
            stack[:] = [entry for entry in stack if id(entry) not in invalid_ids]
            for entry in invalid:
                self._discard_workspace_composite_entry(entry)

    def _workspace_composite_precedes_current_history(
        self,
        entry: WorkspaceCompositeHistoryEntry,
        current: ImageDocument,
        *,
        redo: bool,
    ) -> bool:
        if current.id in dict(entry.document_sequences):
            return True
        history = current.history
        if history is None:
            latest = None
        elif redo:
            latest = history.latest_redo_sequence
        else:
            latest = history.latest_undo_sequence
        if latest is None:
            return True
        sequences = tuple(sequence for _document_id, sequence in entry.document_sequences)
        if not sequences:
            return False
        boundary = min(sequences) if redo else max(sequences)
        return boundary < latest if redo else boundary > latest

    def _workspace_composite_available_for(
        self,
        current: ImageDocument,
        *,
        redo: bool,
    ) -> bool:
        stack = (
            self._workspace_composite_redo
            if redo
            else self._workspace_composite_undo
        )
        if not stack:
            return False
        entry = stack[-1]
        return (
            self._workspace_composite_ready(entry, redo=redo)
            and self._workspace_composite_precedes_current_history(
                entry,
                current,
                redo=redo,
            )
        )

    def _workspace_composite_waits_on_other_document(
        self,
        current: ImageDocument,
        *,
        redo: bool,
    ) -> bool:
        stack = (
            self._workspace_composite_redo
            if redo
            else self._workspace_composite_undo
        )
        if not stack or current.history is None:
            return False
        entry = stack[-1]
        expected = dict(entry.document_sequences).get(current.id)
        if expected is None:
            return False
        latest = (
            current.history.latest_redo_sequence
            if redo
            else current.history.latest_undo_sequence
        )
        return latest == expected and not self._workspace_composite_ready(
            entry,
            redo=redo,
        )

    def _undo_workspace_composite_for(self, current: ImageDocument) -> bool:
        if not self._workspace_composite_available_for(current, redo=False):
            return False
        entry = self._workspace_composite_undo[-1]
        previous_measurements: dict[str, tuple[Measurement, ...]] = {}
        for document_id, _sequence in reversed(entry.document_sequences):
            document = self.project.get_document(document_id)
            if document is None or document.history is None:
                return False
            previous_measurements[document_id] = tuple(document.measurements)
            if not document.history.undo(document):
                return False
        self._workspace_composite_undo.pop()
        self._workspace_composite_redo.append(entry)
        for document_id, _sequence in entry.document_sequences:
            document = self.project.get_document(document_id)
            if document is None:
                continue
            self._discard_detached_area_geometry(
                previous_measurements.get(document_id, ()),
                document,
            )
            self._refresh_document_analysis_validity(document)
            canvas = self._canvases.get(document_id)
            if canvas is not None:
                canvas.notify_document_visual_changed()
        self._update_ui_for_current_document()
        self.statusBar().showMessage(f"已撤销：{entry.label}（整个项目）", 3000)
        return True

    def _redo_workspace_composite_for(self, current: ImageDocument) -> bool:
        if not self._workspace_composite_available_for(current, redo=True):
            return False
        entry = self._workspace_composite_redo[-1]
        previous_measurements: dict[str, tuple[Measurement, ...]] = {}
        for document_id, _sequence in entry.document_sequences:
            document = self.project.get_document(document_id)
            if document is None or document.history is None:
                return False
            previous_measurements[document_id] = tuple(document.measurements)
            if not document.history.redo(document):
                return False
        self._workspace_composite_redo.pop()
        self._workspace_composite_undo.append(entry)
        for document_id, _sequence in entry.document_sequences:
            document = self.project.get_document(document_id)
            if document is None:
                continue
            self._discard_detached_area_geometry(
                previous_measurements.get(document_id, ()),
                document,
            )
            self._refresh_document_analysis_validity(document)
            canvas = self._canvases.get(document_id)
            if canvas is not None:
                canvas.notify_document_visual_changed()
        self._update_ui_for_current_document()
        self.statusBar().showMessage(f"已重做：{entry.label}（整个项目）", 3000)
        return True

    def _save_calibration_sidecar(self, document: ImageDocument, *, context: str) -> bool:
        result = CalibrationSidecarIO.save_document(document)
        if result:
            return True
        QMessageBox.warning(
            self,
            "保存标尺",
            f"{context}后的标尺 sidecar 保存失败，文档仍保持未保存状态：\n{result.message}",
        )
        return False

    def _confirm_close_documents(self, documents: list[ImageDocument]) -> bool:
        dirty_documents = [document for document in documents if self._document_has_unsaved_project_changes(document)]
        has_project_dirty = self._project_dirty()
        if not dirty_documents and not has_project_dirty:
            return True
        message_parts: list[str] = []
        if dirty_documents:
            if len(dirty_documents) == 1 and len(documents) == 1:
                message_parts.append(f"{Path(dirty_documents[0].path).name} 有未保存的项目改动。")
            else:
                message_parts.append(f"共有 {len(dirty_documents)} 张图片存在未保存的项目改动。")
        if has_project_dirty:
            message_parts.append("当前项目的统一比例尺、项目内图片、全局类别或继承关系有未保存改动。")
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.Warning)
        box.setWindowTitle("未保存的改动")
        box.setText("\n".join(message_parts))
        save_button = box.addButton("保存", QMessageBox.ButtonRole.AcceptRole)
        discard_button = box.addButton("放弃", QMessageBox.ButtonRole.DestructiveRole)
        cancel_button = box.addButton("取消", QMessageBox.ButtonRole.RejectRole)
        box.exec()
        clicked = box.clickedButton()
        if clicked == cancel_button:
            return False
        if clicked == save_button:
            return self.save_project()
        return clicked == discard_button

    def _reset_workspace(self) -> None:
        if self._image_information_dialog is not None:
            self._image_information_dialog.close()
            self._image_information_dialog.deleteLater()
            self._image_information_dialog = None
        self._close_threshold_adjustment_dialog()
        self._close_display_adjustment_dialog()
        if not self._close_image_processing_workbench(wait=True):
            raise RuntimeError("图像处理任务尚未安全退出，工作区重置已阻止。")
        if not self._close_image_batch_dialog(wait=True):
            raise RuntimeError("图像批处理任务尚未安全退出，工作区重置已阻止。")
        if not self._close_analysis_batch_dialog(wait=True):
            raise RuntimeError("批量分析任务尚未安全退出，工作区重置已阻止。")
        if not self._stop_image_analysis_tasks(wait=True):
            raise RuntimeError("图像分析任务尚未安全退出，工作区重置已阻止。")
        if (
            self._fullscreen_controller is not None
            and self._fullscreen_controller.is_active
        ):
            self._fullscreen_controller.exit()
        self._navigator_center_timer.stop()
        self._pending_navigator_center = None
        self.stop_live_preview()
        if self._capture_manager.is_preview_active():
            raise RuntimeError("相机 backend 仍在运行，工作区重置已阻止。")
        self._close_document_slide_stores()
        self._hide_small_object_preview()
        self._clear_prompt_segmentation_cache()
        canvases = list(self._canvases.values())
        for document in self.project.documents:
            if document.history is not None:
                document.history.set_workspace_budget(None)
        clear_area_derived_geometry_cache()
        tab_widgets = [
            self.tab_widget.widget(index)
            for index in range(self.tab_widget.count())
        ]
        self.project = ProjectState.empty()
        self._workspace_composite_undo.clear()
        self._workspace_composite_redo.clear()
        self._project_path = None
        self._pending_project_load_snapshot = False
        self.project_session_controller.clear_unresolved_documents()
        self._document_order.clear()
        self._images.clear()
        self._rasters.clear()
        self._raster_metadata.clear()
        self._display_cache_transforms.clear()
        self._cleanup_session_processed_assets()
        self._cleanup_session_analysis_assets()
        if self._analysis_results_center is not None:
            self._analysis_results_center.close()
            self._analysis_results_center.set_artifacts(())
        self._canvases.clear()
        for navigator in self._canvas_navigators.values():
            navigator.clear()
        self._canvas_navigators.clear()
        self.image_list.clear()
        self.tab_widget.clear()
        for canvas in canvases:
            self._release_document_canvas(canvas)
            canvas.deleteLater()
        canvas_ids = {id(canvas) for canvas in canvases}
        for widget in tab_widgets:
            if widget is not None and id(widget) not in canvas_ids:
                widget.deleteLater()
        self._mark_project_saved()

    def _close_document_slide_stores(self) -> None:
        failures: list[str] = []
        for document_id, store in list(self._slide_stores.items()):
            try:
                store.close()
            except Exception as exc:  # noqa: BLE001 - keep the workspace mounted on any close/commit failure
                failures.append(f"{document_id}: {exc}")
        if failures:
            details = "; ".join(failures)
            raise RuntimeError(f"数字化切片存储未能安全关闭：{details}")
        self._slide_stores.clear()

    def _remove_document(self, document_id: str) -> None:
        if document_id not in self._document_order:
            return
        if self._display_adjustment_document_id == document_id:
            self._close_display_adjustment_dialog()
        if (
            self._image_processing_source_context is not None
            and self._image_processing_source_context.document_id == document_id
            and not self._close_image_processing_workbench(wait=True)
        ):
            return
        batch_context = self._image_batch_run_context
        if (
            batch_context is not None
            and batch_context.source_sha_for(document_id) is not None
            and not self._stop_image_batch_tasks(wait=True)
        ):
            self.statusBar().showMessage(
                "图像批处理任务尚未安全退出，已阻止关闭当前图片。",
                6000,
            )
            return
        analysis_batch_context = self._analysis_batch_run_context
        if (
            analysis_batch_context is not None
            and analysis_batch_context.item_for(document_id) is not None
            and not self._stop_analysis_batch_tasks(wait=True)
        ):
            self.statusBar().showMessage(
                "批量分析任务尚未安全退出，已阻止关闭当前图片。",
                6000,
            )
            return
        if any(
            context.source.document_id == document_id
            for context in self._analysis_run_contexts.values()
        ):
            if not self._stop_image_analysis_tasks(wait=True):
                self.statusBar().showMessage(
                    "图像分析任务尚未安全退出，已阻止关闭当前图片。",
                    6000,
                )
                return
        if (
            len(self._document_order) == 1
            and self._fullscreen_controller is not None
            and self._fullscreen_controller.is_active
        ):
            self._fullscreen_controller.exit()
        if (
            self._pending_navigator_center is not None
            and self._pending_navigator_center[0] == document_id
        ):
            self._navigator_center_timer.stop()
            self._pending_navigator_center = None
        document = self.project.get_document(document_id)
        unresolved = self.project_session_controller.unresolved_document(document_id)
        cached_document = document or (unresolved.document if unresolved is not None else None)
        if cached_document is not None:
            for measurement in cached_document.measurements:
                if measurement.measurement_kind == "area":
                    area_derived_geometry_service.discard_measurement(measurement)
        if document is not None and document.history is not None:
            document.history.set_workspace_budget(None)
        if any(
            artifact.source_document_id == document_id
            for artifact in self.project.analysis_artifacts
        ):
            changed = self.project.refresh_analysis_validity(
                document_id,
                source_document_exists=False,
            )
            if changed:
                self.project.mark_extension_changed()
                self._refresh_analysis_results_center()
        retained_rois = [
            roi
            for roi in self.project.project_rois
            if roi.document_id != document_id
        ]
        if len(retained_rois) != len(self.project.project_rois):
            self.project.project_rois = retained_rois
            self._selected_project_roi_ids = tuple(
                roi_id
                for roi_id in self._selected_project_roi_ids
                if self.project.get_project_roi(roi_id) is not None
            )
            self.project.mark_extension_changed()
        index = self._document_order.index(document_id)
        self._document_order.pop(index)
        # Composite entries cannot remain atomic once one participating
        # document leaves the workspace.
        self._workspace_composite_undo.clear()
        self._workspace_composite_redo.clear()
        self.project.documents = [document for document in self.project.documents if document.id != document_id]
        self.project_session_controller.remove_document(document_id)
        self._construction_resolution_cache.pop(document_id, None)
        self._images.pop(document_id, None)
        self._rasters.pop(document_id, None)
        self._raster_metadata.pop(document_id, None)
        self._display_cache_transforms.pop(document_id, None)
        session_asset = self._session_processed_assets.pop(document_id, None)
        if session_asset is not None:
            session_asset.unlink(missing_ok=True)
        navigator = self._canvas_navigators.pop(document_id, None)
        if navigator is not None:
            navigator.clear()
        store = self._slide_stores.pop(document_id, None)
        if store is not None:
            store.close()
        canvas = self._canvases.pop(document_id, None)
        tab_widget = self.tab_widget.widget(index)
        self.tab_widget.removeTab(index)
        if canvas is not None:
            self._release_document_canvas(canvas)
            canvas.deleteLater()
        elif tab_widget is not None:
            tab_widget.deleteLater()
        item = self.image_list.takeItem(index)
        del item
        self._clear_prompt_segmentation_cache()
        self._end_project_session_if_empty()
        self._update_ui_for_current_document()

    def _cleanup_session_processed_assets(self) -> None:
        self._session_processed_assets.clear()
        root = self._session_processed_root
        self._session_processed_root = None
        if root is not None:
            shutil.rmtree(root, ignore_errors=True)

    @staticmethod
    def _cleanup_abandoned_processed_sessions() -> None:
        """Best-effort cleanup for stale, application-owned session assets.

        Fresh directories are left alone so a concurrently running developer
        instance is never disturbed.  The production Windows build is
        single-instance, but the age guard keeps this cleanup safe in tests and
        source checkouts as well.
        """

        cutoff = datetime.now().timestamp() - timedelta(days=7).total_seconds()
        try:
            candidates = tuple(
                Path(tempfile.gettempdir()).glob("fdm-processed-*")
            )
        except OSError:
            return
        for candidate in candidates:
            try:
                if (
                    candidate.is_dir()
                    and candidate.stat().st_mtime < cutoff
                ):
                    shutil.rmtree(candidate, ignore_errors=True)
            except OSError:
                continue

    @staticmethod
    def _release_document_canvas(canvas: DocumentCanvas) -> None:
        """Detach every canvas-owned resource before scheduling Qt deletion.

        Digital-slide canvases additionally own navigation timers and a
        best-effort viewport buffer worker.  Stop those producers first, then
        use the common document detach path to cancel proxy warming and
        overlay-tile requests and release the document's bounded geometry
        caches.  Keeping this order in one place prevents a late worker result
        from repopulating a canvas after its tab has already been removed.
        """

        shutdown = getattr(canvas, "shutdown", None)
        if callable(shutdown):
            shutdown()
        canvas.clear_document()

    @staticmethod
    def _discard_detached_area_geometry(
        previous_measurements: tuple[Measurement, ...],
        document: ImageDocument,
    ) -> None:
        """Release cache owners replaced or removed by undo/redo.

        Geometry edits on an object retained in the document are invalidated by
        its own revision.  Membership changes can instead reconstruct a new
        Measurement with the same persisted ID, so explicitly release the old
        owner's bounded caches here.
        """

        current_by_id = {measurement.id: measurement for measurement in document.measurements}
        for measurement in previous_measurements:
            if measurement.measurement_kind != "area":
                continue
            if current_by_id.get(measurement.id) is not measurement:
                area_derived_geometry_service.discard_measurement(measurement)
                area_handle_display_cache.discard_measurement(measurement)

    def _end_project_session_if_empty(self) -> bool:
        """Detach an empty workspace from its previous project file.

        Closing documents one at a time must have the same project-boundary
        semantics as "close all" once the final mounted or unresolved document
        is gone.  Otherwise newly opened/captured images would silently retain
        the old ``_project_path`` and a later Save would overwrite that project.
        """

        if self.project.documents or self.project_session_controller.unresolved_documents():
            return False
        self._close_image_batch_dialog(wait=True)
        self._close_analysis_batch_dialog(wait=True)
        self.project = ProjectState.empty()
        self._construction_resolution_cache.clear()
        self._workspace_composite_undo.clear()
        self._workspace_composite_redo.clear()
        self._project_path = None
        self._pending_project_load_snapshot = False
        self.project_session_controller.clear_unresolved_documents()
        self._document_order.clear()
        self._cleanup_session_analysis_assets()
        if self._analysis_results_center is not None:
            self._analysis_results_center.close()
            self._analysis_results_center.set_artifacts(())
        self._mark_project_saved()
        return True

    def _apply_document_change(
        self,
        document: ImageDocument,
        label: str,
        mutator,
        *,
        sync_sidecar: bool = False,
        impact: DocumentChangeImpact = DocumentChangeImpact.SESSION,
        geometry_measurement_ids: tuple[str, ...] = (),
    ) -> bool:
        before_stamp = document.state_stamp
        before_construction_revision = document.construction_geometry_revision
        before_construction_metadata_revision = (
            document.construction_metadata_revision
        )
        before = DocumentHistoryState.capture(
            document,
            geometry_measurement_ids=geometry_measurement_ids,
        )
        mutator()
        document.rebuild_group_memberships()
        after = DocumentHistoryState.capture(
            document,
            geometry_measurement_ids=geometry_measurement_ids,
        )
        changed = before != after
        if changed:
            self._discard_workspace_composite_redo()
            self._discard_detached_area_geometry(before.measurement_objects, document)
            if impact & DocumentChangeImpact.GEOMETRY:
                document.mark_measurement_geometry_changed()
            if (
                impact & DocumentChangeImpact.CONSTRUCTION
                and document.construction_geometry_revision
                == before_construction_revision
                and document.construction_metadata_revision
                == before_construction_metadata_revision
            ):
                document.mark_construction_geometry_changed()
            after_stamp = document.advance_state(dirty_domains_for_impact(impact))
            if document.history is not None:
                document.history.push_delta(
                    label,
                    before=before,
                    after=after,
                    before_stamp=before_stamp,
                    after_stamp=after_stamp,
                    impact=impact,
                )
        else:
            # Model helpers may optimistically mark a domain.  Preserve the
            # exact no-op semantics formerly provided by snapshot comparison.
            document.restore_state_stamp(before_stamp)
        if changed and sync_sidecar and document.uses_sidecar():
            self._save_calibration_sidecar(document, context=label)
        elif changed and sync_sidecar:
            document.mark_calibration_saved()
        if changed:
            self._refresh_document_analysis_validity(document)
        self._update_ui_for_current_document()
        return changed

    def _refresh_document_analysis_validity(
        self,
        document: ImageDocument,
    ) -> None:
        if not any(
            artifact.source_document_id == document.id
            for artifact in self.project.analysis_artifacts
        ):
            return
        plane = self._rasters.get(document.id)
        if plane is None:
            changed = self.project.refresh_analysis_validity(
                document.id,
                current_pixel_revision=0,
            )
        else:
            changed = self.project.refresh_analysis_validity(
                document.id,
                current_pixel_revision=0,
                current_source_descriptor=AnalysisSourceDescriptor(
                    kind="raster",
                    pixel_sha256=plane.sha256(),
                ),
            )
        if changed:
            self.project.mark_extension_changed()
            self._refresh_analysis_results_center()

    def _refresh_loaded_analysis_validity(self) -> int:
        artifact_document_ids = tuple(
            dict.fromkeys(
                artifact.source_document_id
                for artifact in self.project.analysis_artifacts
            )
        )
        if not artifact_document_ids:
            return 0
        descriptor_cache: dict[AnalysisSourceDescriptor, bool] = {}
        total_changed = 0
        for document_id in artifact_document_ids:
            document = self.project.get_document(document_id)
            descriptor_map: dict[
                str,
                AnalysisSourceDescriptor | None,
            ] = {}
            for artifact in self.project.analysis_artifacts:
                if (
                    artifact.source_document_id != document_id
                    or artifact.source_descriptor is None
                ):
                    continue
                descriptor = artifact.source_descriptor
                is_current = descriptor_cache.get(descriptor)
                if is_current is None:
                    is_current = self._analysis_source_descriptor_is_current(
                        document_id,
                        descriptor,
                    )
                    descriptor_cache[descriptor] = is_current
                descriptor_map[artifact.id] = (
                    descriptor if is_current else None
                )
            total_changed += self.project.refresh_analysis_validity(
                document_id,
                source_document_exists=document is not None,
                current_pixel_revision=(0 if document is not None else None),
                current_source_descriptors=descriptor_map,
            )
        if total_changed:
            self.project.mark_extension_changed()
            self._refresh_analysis_results_center()
            self.statusBar().showMessage(
                f"项目加载后发现 {total_changed} 个分析结果的来源或依赖"
                "已变化，已标记为失效。",
                7000,
            )
        return total_changed

    def _append_new_measurement(self, document: ImageDocument, measurement: Measurement, *, label: str) -> None:
        self._discard_workspace_composite_redo()
        before_stamp = document.state_stamp
        before = DocumentHistoryState.capture(document)
        document.insert_measurement_incremental(measurement)
        after = DocumentHistoryState.capture(document)
        after_stamp = document.advance_state({DirtyDomain.SESSION})
        if document.history is not None:
            document.history.push_delta(
                label,
                before=before,
                after=after,
                before_stamp=before_stamp,
                after_stamp=after_stamp,
                impact=DocumentChangeImpact.SESSION,
            )
        self._refresh_document_analysis_validity(document)
        self._refresh_measurement_append_ui(document, measurement)

    def _refresh_measurement_append_ui(self, document: ImageDocument, measurement: Measurement) -> None:
        if document is not self.current_document():
            self._update_action_states()
            self._show_pending_history_budget_notice()
            return
        self._refresh_group_list_counts(document)
        self._append_measurement_table_row(document, measurement)
        canvas = self.current_canvas()
        if canvas is not None:
            canvas.notify_document_visual_changed()
        self._update_action_states()
        self._schedule_statistics_refresh()
        self._refresh_object_inspector()
        self._show_pending_history_budget_notice()

    def _apply_documents_change(
        self,
        documents: list[ImageDocument],
        label: str,
        mutator,
        *,
        workspace_scope: bool,
        impact: DocumentChangeImpact = DocumentChangeImpact.SESSION,
    ) -> int:
        before_revisions = {
            document.id: (
                document.measurement_geometry_revision,
                document.construction_geometry_revision,
                document.construction_metadata_revision,
            )
            for document in documents
        }
        captures = [
            (document, document.state_stamp, DocumentHistoryState.capture(document))
            for document in documents
        ]
        total_removed = 0
        applied: list[
            tuple[ImageDocument, object, DocumentHistoryState, DocumentHistoryState]
        ] = []
        try:
            for document, before_stamp, before in captures:
                removed_count = mutator(document)
                total_removed += int(removed_count or 0)
                document.rebuild_group_memberships()
                after = DocumentHistoryState.capture(document)
                applied.append((document, before_stamp, before, after))
        except Exception:
            for document, before_stamp, before, _after in reversed(applied):
                before.restore(document)
                document.restore_state_stamp(before_stamp)
            # The failing document may have been changed before raising.
            applied_ids = {document.id for document, *_rest in applied}
            for document, before_stamp, before in reversed(captures):
                if document.id not in applied_ids:
                    before.restore(document)
                    document.restore_state_stamp(before_stamp)
            raise

        changed_any = False
        changed_documents: list[ImageDocument] = []
        composite_sequences: list[tuple[str, int]] = []
        if any(before != after for _document, _stamp, before, after in applied):
            self._discard_workspace_composite_redo()
        for document, before_stamp, before, after in applied:
            changed = before != after
            if changed:
                self._discard_detached_area_geometry(before.measurement_objects, document)
                (
                    measurement_revision,
                    construction_revision,
                    construction_metadata_revision,
                ) = before_revisions[document.id]
                if (
                    impact & DocumentChangeImpact.GEOMETRY
                    and document.measurement_geometry_revision
                    == measurement_revision
                ):
                    document.mark_measurement_geometry_changed()
                if (
                    impact & DocumentChangeImpact.CONSTRUCTION
                    and document.construction_geometry_revision
                    == construction_revision
                    and document.construction_metadata_revision
                    == construction_metadata_revision
                ):
                    document.mark_construction_geometry_changed()
                after_stamp = document.advance_state(
                    dirty_domains_for_impact(impact)
                )
                if document.history is not None:
                    pushed = document.history.push_delta(
                        label,
                        before=before,
                        after=after,
                        before_stamp=before_stamp,
                        after_stamp=after_stamp,
                        impact=impact,
                    )
                    sequence = document.history.latest_undo_sequence
                    if pushed and sequence is not None:
                        composite_sequences.append((document.id, sequence))
                changed_documents.append(document)
            else:
                document.restore_state_stamp(before_stamp)
            changed_any = changed_any or changed
        for document in changed_documents:
            self._refresh_document_analysis_validity(document)
        if workspace_scope and composite_sequences:
            self._workspace_composite_undo.append(
                WorkspaceCompositeHistoryEntry(
                    label=label,
                    document_sequences=tuple(composite_sequences),
                )
            )
            self._prune_invalid_workspace_composites()
        if changed_any:
            self._update_ui_for_current_document()
        return total_removed

    def _on_tab_changed(self, index: int) -> None:
        if index < 0:
            return
        self.image_list.setCurrentRow(index)
        current_document = self.current_document()
        active_analysis = self.image_analysis_task_controller.active_request
        if (
            active_analysis is not None
            and (
                current_document is None
                or active_analysis.document_id != current_document.id
            )
        ):
            self.image_analysis_task_controller.cancel()
        if (
            self._display_adjustment_dialog is not None
            and self._display_adjustment_document_id
            != (current_document.id if current_document is not None else None)
        ):
            self._close_display_adjustment_dialog()
        self._clear_magic_segment_sessions(except_document_id=current_document.id if current_document is not None else None)
        canvas = self.current_canvas()
        if canvas is not None:
            canvas.set_tool_mode(self._tool_mode, overlay_kind=self._overlay_tool_kind)
            if is_magic_segment_tool_mode(self._tool_mode):
                self._sync_canvas_magic_subtract_input_mode(canvas)
        self._update_ui_for_current_document()

    def _on_image_list_changed(self, row: int) -> None:
        if row >= 0 and row != self.tab_widget.currentIndex():
            self.tab_widget.setCurrentIndex(row)

    def _set_current_document(self, document_id: str) -> None:
        if document_id in self._document_order:
            index = self._document_order.index(document_id)
            self.tab_widget.setCurrentIndex(index)
            self.image_list.setCurrentRow(index)

    def _on_canvas_line_committed(self, document_id: str, mode: str, payload: object) -> None:
        document = self.project.get_document(document_id)
        if document is None:
            return
        if mode == "calibration":
            if isinstance(payload, Line):
                self._apply_calibration_line(document, payload)
            self._focus_current_canvas()
            return

        group = document.get_group(document.active_group_id)
        snap_result: SnapResult | None = None
        if mode == "snap":
            if not isinstance(payload, Line):
                self._focus_current_canvas()
                return
            snap_line = payload
            snap_offset = Point(0.0, 0.0)
            if document.is_digital_slide():
                snap_context = self._digital_slide_snap_context(document, payload)
                if snap_context is None:
                    self.statusBar().showMessage("当前数字化切片视场无法用于边缘吸附。", 4000)
                    self._focus_current_canvas()
                    return
                image, snap_line, snap_offset = snap_context
            else:
                image = self._images.get(document.id)
            if image is None or image.isNull():
                self.statusBar().showMessage("当前图片还未完成加载，暂时无法进行边缘吸附。", 4000)
                self._focus_current_canvas()
                return
            try:
                local_result = self.snap_service.snap_measurement(image, snap_line)
                if document.is_digital_slide():
                    snap_result = self._translate_digital_slide_snap_result(local_result, payload, snap_offset)
                else:
                    snap_result = local_result
            except Exception as exc:  # noqa: BLE001
                self.statusBar().showMessage(f"边缘吸附失败: {exc}", 5000)
                self._focus_current_canvas()
                return

        if isinstance(payload, dict) and payload.get("measurement_kind") == "area":
            measurement = Measurement(
                id=new_id("meas"),
                image_id=document.id,
                fiber_group_id=group.id if group else None,
                mode=mode,
                measurement_kind="area",
                polygon_px=list(payload.get("polygon_px", [])),
                area_rings_px=[list(ring) for ring in payload.get("area_rings_px", [])],
                exact_area_px=float(payload["exact_area_px"]) if payload.get("exact_area_px") is not None else None,
                confidence=1.0,
                status="manual" if mode != "auto_instance" else "auto_instance",
            )
            if mode == "magic_segment":
                ensure_measurement_display_geometry(measurement)
        elif mode == "continuous_manual" and isinstance(payload, dict):
            measurement = Measurement(
                id=new_id("meas"),
                image_id=document.id,
                fiber_group_id=group.id if group else None,
                mode="continuous_manual",
                measurement_kind="polyline",
                polyline_px=list(payload.get("polyline_px", [])),
                confidence=1.0,
                status="continuous_manual",
            )
        elif mode == "count" and isinstance(payload, dict):
            measurement = Measurement(
                id=new_id("meas"),
                image_id=document.id,
                fiber_group_id=group.id if group else None,
                mode="count",
                measurement_kind="count",
                point_px=payload.get("point_px"),
                confidence=1.0,
                status="count",
            )
        elif mode == "manual" and isinstance(payload, Line):
            measurement = Measurement(
                id=new_id("meas"),
                image_id=document.id,
                fiber_group_id=group.id if group else None,
                mode="manual",
                line_px=payload,
                confidence=1.0,
                status="manual",
            )
        elif mode == "snap" and isinstance(payload, Line) and snap_result is not None:
            measurement = Measurement(
                id=new_id("meas"),
                image_id=document.id,
                fiber_group_id=group.id if group else None,
                mode="snap",
                line_px=snap_result.original_line,
                snapped_line_px=snap_result.snapped_line,
                confidence=snap_result.confidence,
                status=snap_result.status,
                debug_payload=dict(snap_result.debug_payload),
            )
        elif mode == "fiber_quick" and isinstance(payload, dict) and isinstance(payload.get("line_px"), Line):
            measurement = Measurement(
                id=new_id("meas"),
                image_id=document.id,
                fiber_group_id=group.id if group else None,
                mode="fiber_quick",
                line_px=payload["line_px"],
                confidence=float(payload.get("confidence", 0.0)),
                status=str(payload.get("status", "fiber_quick") or "fiber_quick"),
                debug_payload=dict(payload.get("debug_payload", {})),
            )
        else:
            self._focus_current_canvas()
            return

        self._append_new_measurement(document, measurement, label="新增测量")
        if snap_result is not None:
            self.statusBar().showMessage(self._edge_snap_status_message(snap_result), 4000)
        else:
            self.statusBar().showMessage("已新增测量", 2500)
        self._focus_current_canvas()

    def _digital_slide_snap_context(self, document: ImageDocument, line: Line) -> tuple[QImage, Line, Point] | None:
        canvas = self._canvases.get(document.id)
        store = self._slide_stores.get(document.id)
        if not isinstance(canvas, DigitalSlideCanvas) or store is None:
            return None
        width, height = document.image_size
        margin = max(12, int(getattr(self.snap_service, "profile_half_width_px", 2)) + 8)
        min_x = int(math.floor(min(line.start.x, line.end.x))) - margin
        min_y = int(math.floor(min(line.start.y, line.end.y))) - margin
        max_x = int(math.ceil(max(line.start.x, line.end.x))) + margin + 1
        max_y = int(math.ceil(max(line.start.y, line.end.y))) + margin + 1
        x = max(0, min(min_x, max(0, width - 1)))
        y = max(0, min(min_y, max(0, height - 1)))
        roi_width = max(1, min(width - x, max_x - x))
        roi_height = max(1, min(height - y, max_y - y))
        try:
            manifest = store.read_manifest()
            metadata = manifest.metadata if isinstance(manifest.metadata, dict) else {}
            blend_width = int(metadata.get("blend_width", 0) or 0)
            image = store.render_viewport(
                x=x,
                y=y,
                width=roi_width,
                height=roi_height,
                z_index=canvas.focus_index(),
                blend_width=blend_width,
            )
        except Exception:
            return None
        if image.isNull():
            return None
        offset = Point(float(x), float(y))
        local_line = Line(
            start=Point(line.start.x - offset.x, line.start.y - offset.y),
            end=Point(line.end.x - offset.x, line.end.y - offset.y),
        )
        return image, local_line, offset

    def _translate_digital_slide_snap_result(self, result: SnapResult, original_line: Line, offset: Point) -> SnapResult:
        def translate_line(line: Line | None) -> Line | None:
            if line is None:
                return None
            return Line(
                start=Point(line.start.x + offset.x, line.start.y + offset.y),
                end=Point(line.end.x + offset.x, line.end.y + offset.y),
            )

        debug_payload = dict(result.debug_payload)
        debug_payload["digital_slide_roi_offset"] = (offset.x, offset.y)
        return SnapResult(
            status=result.status,
            original_line=original_line,
            snapped_line=translate_line(result.snapped_line),
            diameter_px=result.diameter_px,
            confidence=result.confidence,
            debug_payload=debug_payload,
        )

    @staticmethod
    def _document_selection_ref(document: ImageDocument) -> CanvasSelectionRef:
        construction = document.get_construction_entity(
            document.selected_construction_id
        )
        if construction is not None:
            return CanvasSelectionRef.construction(construction.id)
        annotation = document.get_overlay_annotation(document.selected_overlay_id)
        if annotation is not None:
            return CanvasSelectionRef.overlay(annotation.id, annotation.normalized_kind())
        measurement = document.get_measurement(document.view_state.selected_measurement_id)
        if measurement is not None:
            return CanvasSelectionRef.measurement(measurement.id)
        return CanvasSelectionRef.none()

    def _on_canvas_object_selection_changed(
        self,
        document_id: str,
        selection: object,
    ) -> None:
        document = self.project.get_document(document_id)
        if document is None:
            return
        if not isinstance(selection, CanvasSelectionRef):
            selection = CanvasSelectionRef.none()
        if selection.kind == "measurement" and selection.object_id:
            measurement = document.get_measurement(selection.object_id)
            if measurement is not None:
                document.select_measurement(measurement.id)
            else:
                document.select_measurement(None)
                document.select_overlay_annotation(None)
                document.select_construction(None)
        elif selection.kind == "overlay" and selection.object_id:
            annotation = document.get_overlay_annotation(selection.object_id)
            if annotation is not None:
                document.select_overlay_annotation(annotation.id)
            else:
                document.select_measurement(None)
                document.select_overlay_annotation(None)
                document.select_construction(None)
        elif selection.kind == "construction" and selection.object_id:
            construction = document.get_construction_entity(
                selection.object_id
            )
            if construction is not None:
                document.select_construction(construction.id)
            else:
                document.select_measurement(None)
                document.select_overlay_annotation(None)
                document.select_construction(None)
        else:
            document.select_measurement(None)
            document.select_overlay_annotation(None)
            document.select_construction(None)
        self._sync_measurement_table_selection(document, scroll=True)
        if self._construction_manager is not None:
            self._construction_manager.selectEntity(
                document.selected_construction_id
            )
        self._refresh_project_roi_ui()
        self._update_action_states()
        self._schedule_statistics_refresh()
        self._refresh_object_inspector()
        self._focus_current_canvas()

    def _on_canvas_measurement_selected(self, document_id: str, measurement_id: str | None) -> None:
        """Compatibility adapter for integrations using the legacy signal."""

        document = self.project.get_document(document_id)
        if document is None:
            return
        document.select_measurement(measurement_id or None)
        self._on_canvas_object_selection_changed(document_id, self._document_selection_ref(document))

    def _on_canvas_measurement_edited(self, document_id: str, measurement_id: str, payload: object) -> None:
        document = self.project.get_document(document_id)
        if document is None:
            return

        def mutate() -> None:
            measurement = document.get_measurement(measurement_id)
            if measurement is None:
                return
            if isinstance(payload, dict) and payload.get("measurement_kind") == "area":
                measurement.replace_area_geometry(
                    polygon_px=list(payload.get("polygon_px", [])),
                    area_rings_px=[list(ring) for ring in payload.get("area_rings_px", [])],
                    exact_area_px=(
                        float(payload["exact_area_px"])
                        if payload.get("exact_area_px") is not None
                        else None
                    ),
                    calibration=document.calibration,
                )
                payload_mode = payload.get("mode")
                if isinstance(payload_mode, str) and payload_mode:
                    measurement.mode = payload_mode
            elif isinstance(payload, Line):
                if measurement.line_px is None:
                    return
                measurement.replace_line_geometry(
                    line_px=measurement.line_px,
                    snapped_line_px=payload,
                    calibration=document.calibration,
                )
            else:
                return
            measurement.status = "edited"
            document.select_measurement(measurement.id)

        self._apply_document_change(
            document,
            "编辑测量线",
            mutate,
            impact=DocumentChangeImpact.SESSION | DocumentChangeImpact.GEOMETRY,
            geometry_measurement_ids=(measurement_id,),
        )
        self._focus_current_canvas()

    def _on_canvas_construction_create_requested(
        self,
        document_id: str,
        payload: object,
    ) -> None:
        document = self.project.get_document(document_id)
        if document is None or not isinstance(payload, ConstructionEntity):
            return

        def mutate() -> None:
            document.add_construction_entity(
                payload,
                select=True,
                mark_dirty=False,
            )

        if self._apply_document_change(
            document,
            "新增辅助对象",
            mutate,
            impact=DocumentChangeImpact.CONSTRUCTION,
        ):
            self.statusBar().showMessage(
                f"已新增{construction_kind_label(payload)}",
                2200,
            )
        self._focus_current_canvas()

    def _on_canvas_construction_edited(
        self,
        document_id: str,
        construction_id: str,
        payload: object,
    ) -> None:
        document = self.project.get_document(document_id)
        if document is None or not isinstance(payload, ConstructionEntity):
            return

        def mutate() -> None:
            document.replace_construction_entity(
                construction_id,
                payload,
                select=True,
                mark_dirty=False,
            )

        self._apply_document_change(
            document,
            "编辑辅助对象",
            mutate,
            impact=DocumentChangeImpact.CONSTRUCTION,
        )
        self._focus_current_canvas()

    def _on_construction_definition_change_requested(
        self,
        construction_id: str,
        definition: object,
    ) -> None:
        document = self.current_document()
        if document is None:
            return
        entity = document.get_construction_entity(construction_id)
        if entity is None or entity.locked or not hasattr(definition, "kind"):
            self._refresh_object_inspector()
            return
        candidate = replace(entity, definition=definition)
        candidate_entities = [
            candidate if item.id == construction_id else item
            for item in document.construction_entities
        ]
        base_resolver = make_construction_resolver(document)
        resolved = ConstructionResolver(
            document.id,
            candidate_entities,
            external_feature_resolver=base_resolver.external_feature_resolver,
        ).resolve(candidate)
        if not resolved.valid:
            reason = str(getattr(getattr(resolved, "error", None), "message", ""))
            QMessageBox.warning(
                self,
                "修改辅助对象参数",
                reason or "当前参数无法构造有效几何。",
            )
            self._refresh_object_inspector()
            return

        def mutate() -> None:
            document.replace_construction_entity(
                construction_id,
                candidate,
                select=True,
                mark_dirty=False,
            )

        self._apply_document_change(
            document,
            "修改辅助对象参数",
            mutate,
            impact=DocumentChangeImpact.CONSTRUCTION,
        )
        self._focus_current_canvas()

    def _on_canvas_construction_command_changed(
        self,
        document_id: str,
        payload: object,
    ) -> None:
        if document_id != (self.current_document().id if self.current_document() else None):
            return
        if self._construction_context_widget is None or not isinstance(payload, dict):
            return
        tool = str(payload.get("tool", self._construction_tool_kind))
        point_count = int(payload.get("point_count", 0) or 0)
        source_count = int(payload.get("source_count", 0) or 0)
        invalid_reason = str(payload.get("invalid_reason", "") or "")
        self._construction_context_widget.setCommandState(
            distance_px=payload.get("spacing"),
            count=payload.get("count"),
            both_sides=payload.get("both_sides"),
            extend=payload.get("extend"),
        )
        prompts = {
            "point": "单击放点",
            "midpoint": "选择有限线段",
            "intersection": "选两对象；再选交点",
            "segment": "两端点 · Shift 正交 · Ctrl 像素中心",
            "ray": "起点和方向 · Shift 正交 · Ctrl 像素中心",
            "infinite_line": "直线两点 · Shift 正交 · Ctrl 像素中心",
            "horizontal_line": "通过点 · Ctrl 像素中心",
            "vertical_line": "通过点 · Ctrl 像素中心",
            "circle_center_radius": "指定圆心和圆周点",
            "circle_center_diameter": "指定圆心和圆周点",
            "circle_diameter_2p": "指定直径两端点",
            "circle_3p": "指定圆上三点",
            "parallel_through": "选择源线和通过点",
            "parallel_offset": "选择源线和偏移侧",
            "parallel_array": "选择源线和阵列侧",
            "perpendicular": "选择源线和通过点",
            "perpendicular_bisector": "选择有限线段",
            "concentric_circle": "选择源圆和新圆周点",
            "offset_circle": "选择源圆和偏移侧",
            "tangent_point_circle": "选择点和圆；再选切线",
            "common_tangent_external": "选择两圆；再选外公切线",
            "common_tangent_internal": "选择两圆；再选内公切线",
            "tangent_circle_ttr": "选择两对象；再选定半径解",
            "tangent_circle_3": "选择三对象；再选相切圆",
        }
        progress_parts: list[str] = []
        if source_count:
            progress_parts.append(f"{source_count}源")
        if point_count:
            progress_parts.append(f"{point_count}点")
        progress = f" · {'/'.join(progress_parts)}" if progress_parts else ""
        prompt = invalid_reason or prompts.get(tool, "按提示创建辅助对象")
        prompt_changed = self._construction_context_widget.setPrompt(prompt + progress)
        strip = getattr(self, "_measurement_tool_strip", None)
        if prompt_changed and strip is not None:
            strip.refreshContextLayout()

    def _on_canvas_snap_candidate_changed(
        self,
        document_id: str,
        candidate: object,
    ) -> None:
        current = self.current_document()
        if current is None or current.id != document_id:
            return
        if self._object_snap_status_button is None:
            return
        kind = getattr(candidate, "kind", None)
        self._object_snap_status_button.showActiveKind(
            getattr(kind, "value", None) if kind is not None else None
        )

    def _on_canvas_overlay_create_requested(self, document_id: str, payload: object) -> None:
        document = self.project.get_document(document_id)
        if document is None or not isinstance(payload, dict):
            return
        kind = str(payload.get("kind", OverlayAnnotationKind.TEXT))
        if kind == OverlayAnnotationKind.TEXT:
            anchor = payload.get("anchor_px")
            if not isinstance(anchor, Point):
                self._focus_current_canvas()
                return
            content, ok = QInputDialog.getMultiLineText(self, "新增文字", "文字内容")
            if not ok:
                self._focus_current_canvas()
                return
            content = content.strip()
            if not content:
                self._focus_current_canvas()
                return
            canvas = self._canvases.get(document.id)
            persisted_zoom = float(document.view_state.zoom or 1.0)
            if not math.isfinite(persisted_zoom) or persisted_zoom <= 0:
                persisted_zoom = 1.0
            view_zoom = (
                canvas.view_zoom()
                if canvas is not None
                else max(MIN_VIEW_ZOOM, persisted_zoom)
            )
            text_size_space = OverlayTextSizeSpace.normalize(
                self._app_settings.text_size_space
            )
            stored_font_size = float(self._app_settings.text_font_size)
            if text_size_space == OverlayTextSizeSpace.IMAGE_PX:
                stored_font_size /= max(MIN_VIEW_ZOOM, view_zoom)
            text_layout = OverlayTextLayoutSpec(
                anchor_alignment=OverlayTextAnchorAlignment.normalize(
                    self._app_settings.text_anchor_alignment
                ),
                size_space=text_size_space,
                image_font_size_px=stored_font_size,
            )

            annotation = OverlayAnnotation(
                id=new_id("overlay"),
                image_id=document.id,
                kind=OverlayAnnotationKind.TEXT,
                content=content,
                anchor_px=anchor,
                text_layout=text_layout,
            )
            if canvas is not None:
                annotation = canvas.constrain_overlay_annotation(annotation)

            def mutate_text() -> None:
                document.add_overlay_annotation(
                    annotation
                )

            self._apply_document_change(document, "新增文字", mutate_text)
            self.statusBar().showMessage("已新增文字", 2500)
            self._focus_current_canvas()
            return
        start_point = payload.get("start_px")
        end_point = payload.get("end_px")
        if not isinstance(start_point, Point) or not isinstance(end_point, Point):
            self._focus_current_canvas()
            return

        def mutate_shape() -> None:
            document.add_overlay_annotation(
                OverlayAnnotation(
                    id=new_id("overlay"),
                    image_id=document.id,
                    kind=kind,
                    start_px=start_point,
                    end_px=end_point,
                )
            )

        self._apply_document_change(document, "新增标注", mutate_shape)
        self.statusBar().showMessage(f"已新增{self._overlay_tool_label(kind)}标注", 2500)
        self._focus_current_canvas()

    def _on_canvas_overlay_selected(self, document_id: str, overlay_id: str | None) -> None:
        """Compatibility adapter for integrations using the legacy signal."""

        document = self.project.get_document(document_id)
        if document is None:
            return
        document.select_overlay_annotation(overlay_id or None)
        if overlay_id:
            document.select_measurement(None)
        self._on_canvas_object_selection_changed(document_id, self._document_selection_ref(document))

    def _on_canvas_overlay_edited(self, document_id: str, overlay_id: str, payload: object) -> None:
        document = self.project.get_document(document_id)
        if document is None or not isinstance(payload, OverlayAnnotation):
            return

        def mutate() -> None:
            current = document.get_overlay_annotation(overlay_id)
            if current is None:
                return
            document.replace_overlay_annotation(
                overlay_id,
                payload.clone(id=current.id, image_id=current.image_id, created_at=current.created_at),
            )

        label = "编辑标注"
        current = document.get_overlay_annotation(overlay_id)
        if current is not None and current.normalized_kind() == OverlayAnnotationKind.TEXT:
            label = "移动文字"
        self._apply_document_change(document, label, mutate)
        self._focus_current_canvas()

    def _on_object_appearance_change_requested(
        self,
        object_type: str,
        object_id: str,
        appearance: object,
    ) -> None:
        document = self.current_document()
        if document is None:
            return
        normalized = appearance if isinstance(appearance, ObjectAppearanceOverride) else None
        if appearance is not None and normalized is None:
            return

        if object_type == "measurement":
            measurement = document.get_measurement(object_id)
            if measurement is None:
                return

            def mutate_measurement() -> None:
                current = document.get_measurement(object_id)
                if current is not None:
                    current.appearance = normalized
                    document.select_measurement(current.id)

            label = "恢复测量对象继承样式" if normalized is None else "更新测量对象样式"
            self._apply_document_change(document, label, mutate_measurement)
        elif object_type == "overlay":
            overlay = document.get_overlay_annotation(object_id)
            if overlay is None:
                return
            canvas = self.current_canvas()

            def mutate_overlay() -> None:
                current = document.get_overlay_annotation(object_id)
                if current is not None:
                    updated = current.clone(appearance=normalized)
                    if current.is_text() and canvas is not None:
                        updated = canvas.constrain_overlay_annotation(updated)
                    document.replace_overlay_annotation(
                        object_id,
                        updated,
                    )
                    document.select_overlay_annotation(object_id)

            label = "恢复叠加对象继承样式" if normalized is None else "更新叠加对象样式"
            self._apply_document_change(document, label, mutate_overlay)
        self._refresh_object_inspector()
        self._focus_current_canvas()

    def _on_overlay_content_change_requested(self, overlay_id: str, content: str) -> None:
        document = self.current_document()
        overlay = document.get_overlay_annotation(overlay_id) if document is not None else None
        normalized_content = str(content or "").strip()
        if document is None or overlay is None or not overlay.is_text():
            return
        if not normalized_content:
            self.statusBar().showMessage("文字内容不能为空；如需移除请删除该对象。", 3500)
            return
        canvas = self.current_canvas()

        def mutate() -> None:
            current = document.get_overlay_annotation(overlay_id)
            if current is not None:
                updated = current.clone(content=normalized_content)
                if canvas is not None:
                    updated = canvas.constrain_overlay_annotation(updated)
                document.replace_overlay_annotation(
                    overlay_id,
                    updated,
                )
                document.select_overlay_annotation(overlay_id)

        self._apply_document_change(document, "编辑叠加文字", mutate)
        self._refresh_object_inspector()
        self._focus_current_canvas()

    def _on_overlay_text_layout_change_requested(
        self,
        overlay_id: str,
        layout_spec: object,
    ) -> None:
        document = self.current_document()
        overlay = (
            document.get_overlay_annotation(overlay_id)
            if document is not None
            else None
        )
        if (
            document is None
            or overlay is None
            or not overlay.is_text()
            or not isinstance(layout_spec, OverlayTextLayoutSpec)
        ):
            return
        normalized_spec = OverlayTextLayoutSpec(
            anchor_alignment=layout_spec.anchor_alignment,
            size_space=layout_spec.size_space,
            image_font_size_px=layout_spec.image_font_size_px,
        )
        canvas = self.current_canvas()
        updated_overlay = overlay.clone(text_layout=normalized_spec)
        old_alignment = (
            overlay.text_layout.anchor_alignment
            if overlay.text_layout is not None
            else OverlayTextAnchorAlignment.TOP_LEFT
        )
        if canvas is not None and old_alignment != normalized_spec.anchor_alignment:
            previous_layout = resolve_overlay_text_layout(
                overlay,
                self._app_settings,
                canvas.image_to_widget,
                render_mode="screen_scale_full_image",
            )
            candidate_layout = resolve_overlay_text_layout(
                updated_overlay,
                self._app_settings,
                canvas.image_to_widget,
                render_mode="screen_scale_full_image",
            )
            offset = previous_layout.text_rect.topLeft() - candidate_layout.text_rect.topLeft()
            updated_anchor = canvas.widget_to_image(candidate_layout.anchor + offset)
            updated_overlay = updated_overlay.clone(anchor_px=updated_anchor)
        if canvas is not None:
            updated_overlay = canvas.constrain_overlay_annotation(updated_overlay)

        def mutate() -> None:
            current = document.get_overlay_annotation(overlay_id)
            if current is None or not current.is_text():
                return
            document.replace_overlay_annotation(
                overlay_id,
                updated_overlay.clone(
                    id=current.id,
                    image_id=current.image_id,
                    created_at=current.created_at,
                ),
            )
            document.select_overlay_annotation(overlay_id)

        self._apply_document_change(document, "更新叠加文字布局", mutate)
        self._refresh_object_inspector()
        self._focus_current_canvas()

    def _on_overlay_text_layout_conversion_requested(self, overlay_id: str) -> None:
        document = self.current_document()
        canvas = self.current_canvas()
        overlay = (
            document.get_overlay_annotation(overlay_id)
            if document is not None
            else None
        )
        if (
            document is None
            or canvas is None
            or overlay is None
            or not overlay.is_text()
        ):
            return
        if (
            overlay.text_layout is not None
            and overlay.text_layout.size_space == OverlayTextSizeSpace.IMAGE_PX
        ):
            return
        previous_layout = resolve_overlay_text_layout(
            overlay,
            self._app_settings,
            canvas.image_to_widget,
            render_mode="screen_scale_full_image",
        )
        output_font_size = max(1.0, float(previous_layout.font.pixelSize()))
        image_font_size = output_font_size / max(
            MIN_VIEW_ZOOM,
            canvas.view_zoom(),
        )
        new_spec = OverlayTextLayoutSpec(
            anchor_alignment=OverlayTextAnchorAlignment.CENTER,
            size_space=OverlayTextSizeSpace.IMAGE_PX,
            image_font_size_px=image_font_size,
        )
        appearance = overlay.appearance
        if appearance is not None and appearance.font_size is not None:
            appearance = appearance.clone(font_size=None)
            if appearance.is_empty():
                appearance = None
        converted = overlay.clone(
            anchor_px=canvas.widget_to_image(previous_layout.text_rect.center()),
            appearance=appearance,
            text_layout=new_spec,
        )

        def mutate() -> None:
            current = document.get_overlay_annotation(overlay_id)
            if current is None or not current.is_text():
                return
            document.replace_overlay_annotation(
                overlay_id,
                converted.clone(
                    id=current.id,
                    image_id=current.image_id,
                    created_at=current.created_at,
                ),
            )
            document.select_overlay_annotation(overlay_id)

        self._apply_document_change(document, "转换叠加文字布局", mutate)
        self.statusBar().showMessage(
            "已按当前画布外观转换为原图像素字号；可撤销此操作。",
            4500,
        )
        self._refresh_object_inspector()
        self._focus_current_canvas()

    def _on_overlay_text_actual_size_preview_requested(self, overlay_id: str) -> None:
        document = self.current_document()
        canvas = self.current_canvas()
        overlay = (
            document.get_overlay_annotation(overlay_id)
            if document is not None
            else None
        )
        if (
            document is None
            or canvas is None
            or overlay is None
            or not overlay.is_text()
        ):
            return
        canvas.actual_size()
        canvas.center_on_image_point(overlay.anchor_px)
        self._refresh_object_inspector()
        self.statusBar().showMessage(
            "当前画布已切换为原始像素 1:1，可直接检查完整分辨率导出字号。",
            4500,
        )
        self._focus_current_canvas()

    def _refresh_object_inspector(self) -> None:
        inspector = self._object_inspector
        if inspector is None:
            return
        document = self.current_document()
        canvas = self.current_canvas()
        selected_ids = self._records_controller.selected_measurement_ids()
        if document is not None and not selected_ids and document.view_state.selected_measurement_id:
            selected_ids = [document.view_state.selected_measurement_id]
        overlay_id = document.selected_overlay_id if document is not None else None
        construction_id = (
            getattr(document, "selected_construction_id", None)
            if document is not None
            else None
        )
        inspector.set_context(
            document,
            settings=self._app_settings,
            measurement_ids=selected_ids,
            overlay_id=overlay_id,
            construction_id=construction_id,
            view_zoom=canvas.view_zoom() if canvas is not None else 1.0,
        )
        section = self._object_properties_section
        if section is None:
            return
        if construction_id and document is not None:
            getter = getattr(document, "get_construction_entity", None)
            entity = getter(construction_id) if callable(getter) else None
            section.setSummary(
                self._construction_tool_label(
                    str(getattr(getattr(entity, "definition", None), "kind", ""))
                )
                if entity is not None
                else "辅助几何"
            )
        elif overlay_id and document is not None:
            overlay = document.get_overlay_annotation(overlay_id)
            section.setSummary(
                "文字" if overlay is not None and overlay.is_text() else "叠加图形"
            )
        elif len(selected_ids) > 1:
            section.setSummary(f"已选择 {len(selected_ids)} 个")
        elif selected_ids and document is not None:
            measurement = document.get_measurement(selected_ids[0])
            section.setSummary(
                self._format_measurement_kind(measurement) if measurement is not None else "未选择对象"
            )
        else:
            section.setSummary("未选择对象")

    def _on_canvas_view_zoom_changed(self, document_id: str) -> None:
        document = self.current_document()
        if (
            document is None
            or document.id != document_id
            or not document.selected_overlay_id
        ):
            return
        overlay = document.get_overlay_annotation(document.selected_overlay_id)
        if overlay is not None and overlay.is_text():
            self._refresh_object_inspector()

    def _on_canvas_view_transform_changed(
        self,
        document_id: str,
        snapshot: CanvasViewportSnapshot,
    ) -> None:
        navigator = self._canvas_navigators.get(document_id)
        if navigator is not None:
            navigator.set_viewport_snapshot(snapshot)
        document = self.current_document()
        if document is None or document.id != document_id:
            return
        if self._zoom_status_button is not None:
            self._zoom_status_button.set_viewport_snapshot(
                snapshot,
                digital_slide=document.is_digital_slide(),
            )

    def _on_canvas_scale_anchor_picked(self, document_id: str, anchor: Point) -> None:
        document = self.project.get_document(document_id)
        canvas = self._canvases.get(document_id)
        if document is None or canvas is None:
            return
        canvas.end_scale_anchor_pick()

        def mutate() -> None:
            document.scale_overlay_anchor = anchor

        self._apply_document_change(document, "设置比例尺位置", mutate)
        self.statusBar().showMessage("已更新当前图片的比例尺位置", 3000)
        self._focus_current_canvas()

    def _apply_calibration_line(self, document: ImageDocument, line: Line) -> None:
        dialog = CalibrationInputDialog(self)
        if dialog.exec() != dialog.DialogCode.Accepted:
            return
        actual_length, unit, apply_to_project = dialog.values()
        pixels_per_unit = line_length(line) / actual_length
        calibration = Calibration(
            mode="image_scale",
            pixels_per_unit=pixels_per_unit,
            unit=unit,
            source_label=f"图内标定 {actual_length:g}{unit}",
        )

        if apply_to_project:
            self._apply_project_default_calibration(calibration, label="设置项目统一标尺")
            self.statusBar().showMessage("项目统一比例尺已更新", 4000)
            return

        def mutate() -> None:
            document.calibration = calibration
            document.metadata["calibration_line"] = line.to_dict()
            document.recalculate_measurements()

        self._apply_document_change(
            document,
            "图内标定",
            mutate,
            sync_sidecar=True,
            impact=DocumentChangeImpact.CALIBRATION,
        )
        self.statusBar().showMessage("图内标尺标定已更新", 4000)

    def _refresh_preset_combo(self, *, selected_name: str | None = None) -> None:
        current_name = selected_name
        selected = self._selected_preset()
        if current_name is None and selected is not None:
            current_name = selected[1].name
        self.preset_combo.clear()
        target_index = -1
        for index, preset in enumerate(self._calibration_presets()):
            self.preset_combo.addItem(f"{preset.name} ({preset.resolved_pixels_per_unit():g} px/{preset.unit})")
            if current_name is not None and preset.name == current_name and target_index < 0:
                target_index = index
        if target_index >= 0:
            self.preset_combo.setCurrentIndex(target_index)
        elif self.preset_combo.count() > 0:
            self.preset_combo.setCurrentIndex(0)
        self._update_preset_combo_tooltip(self.preset_combo.currentText())
        has_preset = self.preset_combo.count() > 0
        if self._edit_preset_button is not None:
            self._edit_preset_button.setEnabled(has_preset)
        if self._delete_preset_button is not None:
            self._delete_preset_button.setEnabled(has_preset)
        if self._apply_preset_button is not None:
            self._apply_preset_button.setEnabled(has_preset and self.current_document() is not None)

    def _populate_group_list(self, document: ImageDocument | None) -> None:
        self._group_list_rebuilding = True
        self.group_list.clear()
        for row in self._group_manager().group_rows(
            document,
            default_uncategorized_color=self._app_settings.default_measurement_color,
        ):
            self._add_group_list_item(
                label=row.label,
                color=row.color,
                current_count=row.current_count,
                project_count=row.project_count,
                group_id=row.group_id,
                selected=row.selected,
            )
        self._group_list_rebuilding = False

    def _add_group_list_item(
        self,
        *,
        label: str,
        color: str,
        current_count: int,
        project_count: int,
        group_id: str | None,
        selected: bool,
    ) -> None:
        item = QListWidgetItem()
        item.setData(Qt.ItemDataRole.UserRole, group_id)
        item.setData(Qt.ItemDataRole.UserRole + 1, current_count)
        item.setData(Qt.ItemDataRole.UserRole + 3, project_count)
        item.setData(Qt.ItemDataRole.UserRole + 2, label)
        item.setSizeHint(QSize(0, FiberGroupListItemWidget.HEIGHT))
        self.group_list.addItem(item)
        widget = FiberGroupListItemWidget(
            label,
            current_count,
            project_count,
            color,
            selected=selected,
            parent=self.group_list,
        )
        self.group_list.setItemWidget(item, widget)
        if selected:
            item.setSelected(True)

    def _sync_group_list_item_widgets(self) -> None:
        for index in range(self.group_list.count()):
            item = self.group_list.item(index)
            widget = self.group_list.itemWidget(item)
            if isinstance(widget, FiberGroupListItemWidget):
                widget.setSelected(item.isSelected())

    def _refresh_group_list_counts(self, document: ImageDocument) -> None:
        rows = self._group_manager().group_rows(
            document,
            default_uncategorized_color=self._app_settings.default_measurement_color,
        )
        expected_group_ids = [row.group_id for row in rows]
        current_group_ids = [
            self.group_list.item(index).data(Qt.ItemDataRole.UserRole)
            for index in range(self.group_list.count())
        ]
        if current_group_ids != expected_group_ids:
            self._populate_group_list(document)
            return
        self._group_list_rebuilding = True
        try:
            for index, row in enumerate(rows):
                item = self.group_list.item(index)
                item.setData(Qt.ItemDataRole.UserRole + 1, row.current_count)
                item.setData(Qt.ItemDataRole.UserRole + 3, row.project_count)
                item.setSelected(row.selected)
                widget = self.group_list.itemWidget(item)
                if isinstance(widget, FiberGroupListItemWidget):
                    widget.setCounts(row.current_count, row.project_count)
                    widget.setSelected(row.selected)
        finally:
            self._group_list_rebuilding = False

    def _scroll_active_group_item_into_view(self) -> None:
        target_item = None
        selected_items = self.group_list.selectedItems()
        if selected_items:
            target_item = selected_items[0]
        elif self.group_list.count() > 0:
            document = self.current_document()
            active_group_id = document.active_group_id if document is not None else None
            for index in range(self.group_list.count()):
                item = self.group_list.item(index)
                if item.data(Qt.ItemDataRole.UserRole) == active_group_id:
                    target_item = item
                    break
        if target_item is not None:
            self.group_list.scrollToItem(target_item, QAbstractItemView.ScrollHint.PositionAtCenter)

    def _documents_for_group_counts(self, current_document: ImageDocument | None) -> list[ImageDocument]:
        return self._group_manager().documents_for_group_counts(current_document)

    def _project_measurement_count_for_group_label(self, label: str, current_document: ImageDocument | None = None) -> int:
        return self._group_manager().project_measurement_count_for_group_label(label, current_document)

    def _project_uncategorized_measurement_count(self, current_document: ImageDocument | None = None) -> int:
        return self._group_manager().project_uncategorized_measurement_count(current_document)

    def _construction_resolutions(
        self,
        document: ImageDocument,
    ) -> Mapping[str, object]:
        """Resolve a document construction graph once per analytical revision."""

        cached = self._construction_resolution_cache.get(document.id)
        document_token = id(document)
        geometry_revision = document.construction_geometry_revision
        if (
            cached is not None
            and cached[0] == document_token
            and cached[1] == geometry_revision
        ):
            measurement_revision = (
                document.measurement_geometry_revision if cached[2] else -1
            )
            if cached[3] == measurement_revision:
                return cached[4]
        depends_on_measurements = any(
            reference.object_kind is SourceObjectKind.MEASUREMENT
            for entity in document.construction_entities
            for reference in iter_live_refs(entity)
        )
        measurement_revision = (
            document.measurement_geometry_revision
            if depends_on_measurements
            else -1
        )
        resolved = make_construction_resolver(document).resolve_all()
        self._construction_resolution_cache[document.id] = (
            document_token,
            geometry_revision,
            depends_on_measurements,
            measurement_revision,
            resolved,
        )
        return resolved

    def _update_ui_for_current_document(self) -> None:
        document = self.current_document()
        self._ensure_document_display_cache(document)
        self._populate_group_list(document)
        self._refresh_project_roi_ui()
        if self._construction_manager is not None:
            self._construction_manager.setEntities(
                getattr(document, "construction_entities", ()) if document is not None else (),
                selected_id=(
                    getattr(document, "selected_construction_id", None)
                    if document is not None
                    else None
                ),
                resolution_by_id=(
                    self._construction_resolutions(document)
                    if document is not None
                    else None
                ),
                content_revision=(
                    document.construction_geometry_revision,
                    document.construction_metadata_revision,
                )
                if document is not None
                else None,
            )
        self._update_calibration_panel(document)
        if self._construction_context_widget is not None:
            if document is not None and document.calibration is not None:
                self._construction_context_widget.setDistanceUnit(
                    document.calibration.unit,
                    document.calibration.pixels_per_unit,
                )
            else:
                self._construction_context_widget.setDistanceUnit("px", 1.0)
        self._populate_measurement_table(document)
        self._update_image_resolution_label(document)
        self._update_statusbar_aux_labels()
        canvas = self.current_canvas()
        if canvas is not None:
            canvas.set_settings(self._app_settings)
            canvas.set_tool_mode(
                "select"
                if self._preview_active and canvas is self._preview_canvas
                else self._tool_mode,
                construction_kind=self._construction_tool_kind,
            )
            canvas.set_show_area_fill(False if self._preview_active and canvas is self._preview_canvas else self._show_area_fill)
            canvas.notify_document_visual_changed()
            canvas.publish_construction_command_state()
        self._sync_current_view_transform()
        self._update_action_states()
        self._schedule_statistics_refresh()
        self._refresh_analysis_results_center()
        self._show_pending_history_budget_notice()

    def _show_pending_history_budget_notice(self) -> None:
        history_budget_notice = False
        for item in self.project.documents:
            if item.history is not None:
                history_budget_notice = (
                    item.history.consume_budget_notice() or history_budget_notice
                )
        if history_budget_notice:
            self.statusBar().showMessage(
                "撤销历史已达到内存预算；较早记录可能已清理，最新操作仍保留一次撤销。",
                7000,
            )

    def _update_project_navigation_summary(self) -> None:
        label = self._project_summary_label
        if label is None:
            return
        mounted = len(self.project.documents)
        unresolved = len(self.project_session_controller.unresolved_documents())
        if self._project_path is None:
            save_state = "尚未保存"
        else:
            dirty = self._project_dirty() or any(
                self._document_has_unsaved_project_changes(document)
                for document in self.project.documents
            )
            save_state = "有未保存更改" if dirty else "已保存"
        missing_text = f"缺失 {unresolved}" if unresolved else "无缺失"
        label.setText(f"{mounted} 张图片 · {missing_text} · {save_state}")

    def _update_calibration_panel(self, document: ImageDocument | None) -> None:
        if self._preview_active:
            self._set_calibration_status_card(
                title="实时预览中",
                summary="图片编辑与标定已暂停",
                status="preview",
                details="实时预览中，图片编辑、测量记录编辑与标定操作暂时不可用。",
                show_start_button=False,
            )
            return
        if document is None or document.calibration is None:
            self._set_calibration_status_card(
                title="未标定",
                summary="测量仅显示 px，无法输出真实尺寸",
                status="uncalibrated",
                details="请使用图内标定或应用标定预设后再进行真实尺寸测量。",
                show_start_button=True,
            )
            return
        calibration = document.calibration
        source_label = calibration.source_label or self._format_calibration_mode(calibration.mode)
        unit_per_px = 1.0 / calibration.pixels_per_unit if calibration.pixels_per_unit > 0 else 0.0
        details = [
            f"标定来源: {source_label}",
            f"标定模式: {self._format_calibration_mode(calibration.mode)}",
            f"换算关系: {calibration.pixels_per_unit:.4f} px/{calibration.unit}",
            f"像素尺寸: {unit_per_px:.6g} {calibration.unit}/px",
        ]
        if calibration.mode == "project_default" or not document.uses_sidecar():
            details.append("保存位置: 当前项目")
        else:
            details.append(f"侧车: {Path(document.sidecar_path or document.default_sidecar_path()).name}")
        self._set_calibration_status_card(
            title=f"已标定 · {source_label}",
            summary=f"{unit_per_px:.6g} {calibration.unit}/px",
            status="calibrated",
            details="\n".join(details),
            show_start_button=False,
        )

    def _populate_measurement_table(self, document: ImageDocument | None) -> None:
        self._table_rebuilding = True
        try:
            self._records_controller.set_document(document)
        finally:
            self._table_rebuilding = False
        if document is not None:
            self._sync_measurement_table_selection(document)
        self._refresh_object_inspector()

    def _refresh_results_group_filter(self, document: ImageDocument | None) -> None:
        for pane in (self._bottom_records_pane, self._inspector_records_pane):
            if pane is not None:
                pane._refresh_group_filter(document)  # noqa: SLF001

    def _filter_measurement_rows(self, *_args) -> None:
        query = str(self._results_search_edit.text() if self._results_search_edit is not None else "").strip().casefold()
        kind_filter = str(self._results_kind_filter.currentData() if self._results_kind_filter is not None else "")
        group_filter = str(self._results_group_filter.currentData() if self._results_group_filter is not None else "")
        status_filter = str(self._results_status_filter.currentData() if self._results_status_filter is not None else "")
        self._records_controller.set_filters(
            query=query,
            kind=kind_filter,
            group=group_filter,
            status=status_filter,
        )

    def _append_measurement_table_row(self, document: ImageDocument, measurement: Measurement) -> None:
        model = self._records_controller.source_model
        expected_existing_rows = max(0, len(document.measurements) - 1)
        if model.rowCount() != expected_existing_rows:
            self._populate_measurement_table(document)
            return
        self._table_rebuilding = True
        try:
            if not self._records_controller.append_measurement(document, measurement):
                self._populate_measurement_table(document)
                return
            self._records_controller.selection_model.clearSelection()
        finally:
            self._table_rebuilding = False
        self._select_measurement_table_id(measurement.id, scroll=True)

    # Compatibility adapters for older integrations which used the formatting
    # helpers on MainWindow before the result table moved to a data model.
    @staticmethod
    def _format_measurement_kind(measurement: Measurement) -> str:
        return _format_measurement_kind_label(measurement)

    @staticmethod
    def _format_measurement_mode(mode: str) -> str:
        return _format_measurement_mode_label(mode)

    @staticmethod
    def _format_measurement_status(status: str) -> str:
        return _format_measurement_status_label(status)

    def _edge_snap_status_message(self, result: SnapResult) -> str:
        return {
            "snapped": "边缘吸附成功",
            "manual_review": "边缘吸附完成，建议人工复核",
            "line_too_short": "测量线过短，已保留原线供人工修正",
            "profile_too_flat": "灰度变化不足，已保留原线供人工修正",
            "edge_pair_not_found": "未找到有效边缘，已保留原线供人工修正",
        }.get(result.status, "边缘吸附已完成")

    def _sync_measurement_table_selection(
        self,
        document: ImageDocument,
        *,
        scroll: bool = False,
    ) -> None:
        self._select_measurement_table_id(
            document.view_state.selected_measurement_id,
            scroll=scroll,
        )

    def _on_measurement_selection_changed(self, *_args) -> None:
        if self._table_rebuilding or self._syncing_measurement_table_selection:
            return
        document = self.current_document()
        canvas = self.current_canvas()
        if document is None or canvas is None:
            return
        selected_ids = self._records_controller.selected_measurement_ids()
        if not selected_ids:
            document.select_measurement(None)
            canvas.set_selected_measurement(None)
            self._update_action_states()
            self._schedule_statistics_refresh()
            self._refresh_object_inspector()
            return
        measurement_id = selected_ids[0]
        if not measurement_id:
            return
        document.select_measurement(measurement_id)
        document.select_overlay_annotation(None)
        canvas.set_selected_measurement(measurement_id)
        canvas.set_selected_overlay_annotation(None)
        self._update_action_states()
        self._schedule_statistics_refresh()
        self._refresh_object_inspector()

    def _measurement_id_for_proxy_index(self, proxy_index: QModelIndex) -> str | None:
        return self._records_controller.measurement_id_for_index(proxy_index)

    def _select_measurement_table_id(self, measurement_id: str | None, *, scroll: bool = False) -> None:
        previous_syncing = self._syncing_measurement_table_selection
        self._syncing_measurement_table_selection = True
        try:
            self._records_controller.select_measurement_id(measurement_id)
        finally:
            self._syncing_measurement_table_selection = previous_syncing
        if scroll:
            for pane in (self._bottom_records_pane, self._inspector_records_pane):
                if pane is not None:
                    pane.scroll_to_measurement(measurement_id)

    def _on_measurement_table_double_clicked(self, proxy_index: QModelIndex) -> None:
        # The category column reserves double-click for its editing delegate.
        if not proxy_index.isValid() or proxy_index.column() == self.TABLE_COL_GROUP:
            return
        measurement_id = self._measurement_id_for_proxy_index(proxy_index)
        document = self.current_document()
        canvas = self.current_canvas()
        measurement = document.get_measurement(measurement_id) if document is not None else None
        if document is None or canvas is None or measurement is None:
            return
        document.select_measurement(measurement.id)
        canvas.set_selected_measurement(measurement.id)
        canvas.center_on_image_point(measurement.geometry_center())
        self._sync_measurement_table_selection(document)
        self._update_action_states()
        self._schedule_statistics_refresh()
        canvas.focus_canvas()

    def _on_construction_selection_changed(self, payload: object) -> None:
        document = self.current_document()
        canvas = self.current_canvas()
        if document is None:
            return
        selected = tuple(str(item) for item in payload) if isinstance(payload, (list, tuple, set)) else ()
        construction_id = selected[0] if selected else None
        selector = getattr(document, "select_construction", None)
        if callable(selector):
            selector(construction_id)
        if canvas is not None and hasattr(canvas, "set_selected_construction"):
            canvas.set_selected_construction(construction_id)
        if construction_id:
            self._records_controller.selection_model.clearSelection()
        self._refresh_object_inspector()
        self._update_action_states()

    def _on_construction_metadata_change_requested(
        self,
        construction_id: str,
        field_name: str,
        value: object,
    ) -> None:
        document = self.current_document()
        getter = getattr(document, "get_construction_entity", None) if document is not None else None
        entity = getter(construction_id) if callable(getter) else None
        if document is None or entity is None:
            return
        target_field = str(field_name)
        if target_field == "stroke_color":
            if entity.locked:
                self.statusBar().showMessage("锁定的辅助对象不能修改颜色。", 2500)
                return
            def mutate_color() -> None:
                current = document.get_construction_entity(construction_id)
                if current is None:
                    return
                document.replace_construction_entity(
                    construction_id,
                    replace(
                        current,
                        style=replace(
                            current.style,
                            stroke_color=str(value),
                        ),
                    ),
                    mark_dirty=False,
                )

            self._apply_document_change(
                document,
                "更新辅助对象颜色",
                mutate_color,
                impact=DocumentChangeImpact.CONSTRUCTION,
            )
            return
        available_fields = {item.name for item in fields(type(entity))}
        if target_field == "snap_enabled" and target_field not in available_fields:
            target_field = "snappable"
        if target_field not in {"visible", "locked", "snap_enabled", "snappable"}:
            return
        if target_field not in available_fields:
            return

        def mutate() -> None:
            current = document.get_construction_entity(construction_id)
            if current is None:
                return
            replacer = getattr(document, "replace_construction_entity", None)
            if callable(replacer):
                replacement = replace(current, **{target_field: bool(value)})
                replacer(
                    construction_id,
                    replacement,
                    mark_dirty=False,
                )
            else:
                replacement = replace(
                    current,
                    **{
                        target_field: bool(value),
                        "revision": int(getattr(current, "revision", 0)) + 1,
                    },
                )
                document.construction_entities = [
                    replacement if item.id == construction_id else item
                    for item in document.construction_entities
                ]
                document.select_construction(construction_id)

        self._apply_document_change(
            document,
            "更新辅助对象属性",
            mutate,
            impact=DocumentChangeImpact.CONSTRUCTION,
        )

    def _on_construction_batch_color_change_requested(
        self,
        payload: object,
        color: str,
    ) -> None:
        document = self.current_document()
        selected = (
            tuple(dict.fromkeys(str(item) for item in payload))
            if isinstance(payload, (list, tuple, set))
            else ()
        )
        entities = (
            [document.get_construction_entity(entity_id) for entity_id in selected]
            if document is not None
            else []
        )
        if document is None or not selected or any(entity is None for entity in entities):
            return
        if any(bool(entity.locked) for entity in entities if entity is not None):
            self.statusBar().showMessage("所选对象包含锁定项，请先解锁后再修改颜色。", 3500)
            return
        selected_ids = set(selected)

        def mutate() -> None:
            document.construction_entities = [
                (
                    replace(
                        entity,
                        style=replace(entity.style, stroke_color=str(color)),
                        revision=entity.revision + 1,
                    )
                    if entity.id in selected_ids
                    else entity
                )
                for entity in document.construction_entities
            ]
            document.mark_construction_metadata_changed()

        self._apply_document_change(
            document,
            "批量更新辅助对象颜色",
            mutate,
            impact=DocumentChangeImpact.CONSTRUCTION,
        )

    def _on_construction_locate_requested(self, construction_id: str) -> None:
        canvas = self.current_canvas()
        if canvas is None:
            return
        if hasattr(canvas, "center_on_construction"):
            canvas.center_on_construction(construction_id)
        canvas.focus_canvas()

    def _on_construction_locate_sources_requested(self, construction_id: str) -> None:
        document = self.current_document()
        canvas = self.current_canvas()
        entity = (
            document.get_construction_entity(construction_id)
            if document is not None
            else None
        )
        if document is None or entity is None:
            return
        references = tuple(iter_live_refs(entity))
        if not references:
            self.statusBar().showMessage("该辅助对象没有实时来源。", 2500)
            return
        first = references[0]
        if first.object_kind is SourceObjectKind.CONSTRUCTION:
            source_entity = document.get_construction_entity(first.object_id)
            if source_entity is not None and canvas is not None:
                document.select_construction(source_entity.id)
                canvas.set_selected_construction(source_entity.id)
                canvas.center_on_construction(source_entity.id)
        elif first.object_kind is SourceObjectKind.MEASUREMENT:
            measurement = document.get_measurement(first.object_id)
            if measurement is not None:
                self._activate_measurement_id(measurement.id)
        summary = "、".join(reference.object_id for reference in references[:4])
        if len(references) > 4:
            summary += f" 等 {len(references)} 个"
        self.statusBar().showMessage(f"来源：{summary}", 3500)
        self._refresh_object_inspector()

    def _on_construction_detach_requested(self, construction_id: str) -> None:
        document = self.current_document()
        entity = (
            document.get_construction_entity(construction_id)
            if document is not None
            else None
        )
        if document is None or entity is None:
            return
        if entity.locked:
            self.statusBar().showMessage("该辅助对象已锁定，不能解除关联。", 2500)
            self._refresh_object_inspector()
            return
        if not tuple(iter_live_refs(entity)):
            self.statusBar().showMessage("该辅助对象已经是冻结几何。", 2500)
            return
        try:
            frozen = detach_live_sources(
                entity,
                make_construction_resolver(document),
            )
        except (ConstructionValidationError, ValueError) as exc:
            QMessageBox.warning(self, "解除辅助对象关联", str(exc))
            return

        def mutate() -> None:
            document.replace_construction_entity(
                construction_id,
                frozen,
                select=True,
                mark_dirty=False,
            )

        if self._apply_document_change(
            document,
            "解除辅助对象关联",
            mutate,
            impact=DocumentChangeImpact.CONSTRUCTION,
        ):
            self.statusBar().showMessage("已冻结当前几何并解除关联。", 3000)

    def _on_construction_copy_requested(self, payload: object) -> None:
        selected = tuple(str(item) for item in payload) if isinstance(payload, (list, tuple, set)) else ()
        if not selected:
            return
        self._copy_constructions_to_document(selected)

    def _on_construction_delete_requested(self, payload: object) -> None:
        document = self.current_document()
        selected = tuple(str(item) for item in payload) if isinstance(payload, (list, tuple, set)) else ()
        if document is None or not selected:
            return
        try:
            plan = plan_cascade_deletion(
                document.construction_entities,
                selected,
            )
        except (KeyError, ValueError) as exc:
            QMessageBox.warning(self, "删除辅助对象", str(exc))
            return
        affected_ids = set(plan.requested_ids) | set(plan.dependent_ids)
        locked_names = [
            entity.name or entity.id
            for entity in document.construction_entities
            if entity.id in affected_ids and entity.locked
        ]
        if locked_names:
            summary = "、".join(locked_names[:5])
            if len(locked_names) > 5:
                summary += f" 等 {len(locked_names)} 个"
            self.statusBar().showMessage(
                f"不能删除或改写锁定的辅助对象：{summary}；请先解锁。",
                4500,
            )
            return
        mode = "direct"
        if plan.dependent_ids:
            names = [
                entity.name
                for entity in document.construction_entities
                if entity.id in plan.dependent_ids
            ]
            summary = "、".join(names[:6])
            if len(names) > 6:
                summary += f" 等 {len(names)} 个"
            box = QMessageBox(self)
            box.setIcon(QMessageBox.Icon.Warning)
            box.setWindowTitle("辅助对象存在依赖")
            box.setText(
                f"所选对象被 {len(plan.dependent_ids)} 个下游对象引用：\n{summary}"
            )
            box.setInformativeText(
                "可级联删除全部下游对象，或冻结当前几何并保留下游对象。"
            )
            cancel_button = box.addButton(
                "取消",
                QMessageBox.ButtonRole.RejectRole,
            )
            freeze_button = box.addButton(
                "解除关联并保留下游",
                QMessageBox.ButtonRole.ActionRole,
            )
            cascade_button = box.addButton(
                "级联删除",
                QMessageBox.ButtonRole.DestructiveRole,
            )
            box.setDefaultButton(cancel_button)
            box.exec()
            clicked = box.clickedButton()
            if clicked is cancel_button or clicked is None:
                return
            mode = "cascade" if clicked is cascade_button else "freeze"

        if mode == "freeze":
            resolver = make_construction_resolver(document)
            replacements: dict[str, ConstructionEntity] = {}
            try:
                for entity in document.construction_entities:
                    if entity.id not in plan.dependent_ids:
                        continue
                    detached = detach_live_sources(
                        entity,
                        resolver,
                        source_ids=plan.requested_ids,
                        source_kind=SourceObjectKind.CONSTRUCTION,
                    )
                    if detached is not entity:
                        replacements[entity.id] = replace(
                            detached,
                            revision=entity.revision + 1,
                        )
            except (ConstructionValidationError, ValueError) as exc:
                QMessageBox.warning(
                    self,
                    "删除辅助对象",
                    f"无法冻结下游几何：{exc}",
                )
                return

            def mutate_freeze() -> None:
                document.construction_entities = [
                    replacements.get(entity.id, entity)
                    for entity in document.construction_entities
                    if entity.id not in plan.requested_ids
                ]
                document.select_construction(None)
                document.mark_construction_geometry_changed()

            label = "删除辅助对象并冻结下游"
            mutator = mutate_freeze
        else:
            removed_ids = (
                plan.removed_ids if mode == "cascade" else plan.requested_ids
            )

            def mutate_remove() -> None:
                document.remove_construction_entities(
                    removed_ids,
                    mark_dirty=False,
                )

            label = "级联删除辅助对象" if mode == "cascade" else "删除辅助对象"
            mutator = mutate_remove

        self._apply_document_change(
            document,
            label,
            mutator,
            impact=DocumentChangeImpact.CONSTRUCTION,
        )

    def _copy_constructions_to_document(self, construction_ids: tuple[str, ...]) -> None:
        source = self.current_document()
        if source is None:
            return
        targets = [
            document
            for document in self.project.documents
            if document.id != source.id
        ]
        if not targets:
            QMessageBox.information(
                self,
                "复制辅助对象",
                "请先打开至少另一张目标图片。",
            )
            return
        labels = [
            f"{self._document_display_name(document)}  ({document.image_size[0]}×{document.image_size[1]})"
            for document in targets
        ]
        selected_label, ok = QInputDialog.getItem(
            self,
            "复制辅助对象",
            "目标图片",
            labels,
            0,
            False,
        )
        if not ok:
            return
        try:
            target = targets[labels.index(selected_label)]
            result = copy_constructions(source, target, construction_ids)
        except (ValueError, KeyError, ConstructionValidationError) as exc:
            QMessageBox.warning(self, "复制辅助对象", str(exc))
            return
        summary = result.bounds_summary
        details = [
            f"源尺寸：{summary.source_image_size[0]}×{summary.source_image_size[1]}",
            f"目标尺寸：{summary.target_image_size[0]}×{summary.target_image_size[1]}",
            f"将复制 {len(result.entities)} 个对象（含依赖闭包）",
        ]
        if summary.calibration_differs:
            details.append("标定不同；仍将保持原始像素坐标，不做缩放。")
        if summary.partially_outside_ids:
            details.append(
                f"部分越界：{len(summary.partially_outside_ids)} 个"
            )
        if summary.fully_outside_ids:
            details.append(
                f"完全越界：{len(summary.fully_outside_ids)} 个"
            )
        if summary.unresolved_ids:
            details.append(f"不可解：{len(summary.unresolved_ids)} 个")
        response = QMessageBox.question(
            self,
            "确认复制辅助对象",
            "\n".join(details),
            QMessageBox.StandardButton.Ok
            | QMessageBox.StandardButton.Cancel,
            QMessageBox.StandardButton.Cancel,
        )
        if response != QMessageBox.StandardButton.Ok:
            return

        def mutate_copy() -> None:
            target.construction_entities.extend(result.entities)
            if result.entities:
                target.select_construction(result.entities[-1].id)
                target.mark_construction_geometry_changed()

        self._apply_document_change(
            target,
            "跨图复制辅助对象",
            mutate_copy,
            impact=DocumentChangeImpact.CONSTRUCTION,
        )
        target_canvas = self._canvases.get(target.id)
        if target_canvas is not None:
            target_canvas.notify_document_visual_changed()
        # The history entry belongs to the target document.  Make the result
        # visible and ensure the next Ctrl+Z reverses the copy the user just
        # completed, instead of an unrelated older command on the source.
        self._set_current_document(target.id)
        self.statusBar().showMessage(
            f"已复制 {len(result.entities)} 个辅助对象到 {self._document_display_name(target)}。",
            4000,
        )

    def _activate_measurement_id(self, measurement_id: str) -> None:
        document = self.current_document()
        canvas = self.current_canvas()
        measurement = document.get_measurement(measurement_id) if document is not None else None
        if document is None or canvas is None or measurement is None:
            return
        document.select_overlay_annotation(None)
        document.select_measurement(measurement.id)
        canvas.set_selected_overlay_annotation(None)
        canvas.set_selected_measurement(measurement.id)
        canvas.center_on_image_point(measurement.geometry_center())
        self._sync_measurement_table_selection(document)
        self._update_action_states()
        self._schedule_statistics_refresh()
        self._refresh_object_inspector()
        canvas.focus_canvas()

    def _on_measurement_group_change_requested(self, measurement_id: str, target_group_id: object) -> None:
        if self._table_rebuilding:
            return
        document = self.current_document()
        if document is None:
            return
        normalized_group_id = None if target_group_id in {None, ""} else str(target_group_id)
        measurement = document.get_measurement(measurement_id)
        if measurement is None or measurement.fiber_group_id == normalized_group_id:
            return
        document.select_measurement(measurement_id)

        def mutate() -> None:
            document.set_measurement_group(measurement_id, normalized_group_id)

        self._apply_document_change(document, "修改测量分类", mutate)

    def _on_group_selection_changed(self) -> None:
        if self._group_list_rebuilding:
            return
        document = self.current_document()
        if document is None:
            return
        selected_items = self.group_list.selectedItems()
        if not selected_items:
            document.set_active_group(None)
            self._sync_group_list_item_widgets()
            self._update_action_states()
            self._schedule_statistics_refresh()
            return
        document.set_active_group(selected_items[0].data(Qt.ItemDataRole.UserRole))
        self._populate_group_list(document)
        self._update_action_states()
        self._schedule_statistics_refresh()

    def _focus_current_canvas(self) -> None:
        canvas = self.current_canvas()
        if canvas is not None:
            canvas.focus_canvas()

    def _should_handle_group_hotkeys(self) -> bool:
        if QApplication.activeModalWidget() is not None:
            return False
        focus_widget = QApplication.focusWidget()
        if focus_widget is None:
            return True
        if isinstance(focus_widget, (QLineEdit, QTextEdit, QPlainTextEdit)):
            return False
        if isinstance(focus_widget, QComboBox) and focus_widget.isEditable():
            return False
        return True

    def _should_handle_digital_slide_jog_hotkeys(self) -> bool:
        return bool(self._digital_slide_mode and self._preview_active and self._should_handle_group_hotkeys())

    def _switch_active_group_by_number(self, number: int) -> bool:
        document = self.current_document()
        if document is None:
            return False
        group = document.get_group_by_number(number)
        if group is None:
            return False
        document.set_active_group(group.id)
        self._populate_group_list(document)
        self._scroll_active_group_item_into_view()
        self._update_action_states()
        self._focus_current_canvas()
        return True

    def _create_progress_dialog(self, *, title: str, label_text: str, maximum: int) -> QProgressDialog:
        progress = QProgressDialog(label_text, "取消", 0, maximum, self)
        progress.setWindowTitle(title)
        progress.setWindowModality(Qt.WindowModality.ApplicationModal)
        progress.setMinimumDuration(0)
        progress.setAutoClose(False)
        progress.setAutoReset(False)
        progress.setValue(0)
        progress.setMinimumWidth(420)
        return progress

    def _create_blocking_progress_dialog(self, *, title: str, label_text: str, maximum: int) -> QProgressDialog:
        progress = self._create_progress_dialog(title=title, label_text=label_text, maximum=maximum)
        progress.setCancelButton(None)
        progress.setWindowFlag(Qt.WindowType.WindowStaysOnTopHint, True)
        progress.setWindowFlag(Qt.WindowType.WindowCloseButtonHint, False)
        return progress

    def _update_blocking_progress_dialog(
        self,
        progress: QProgressDialog,
        *,
        completed_steps: int,
        total_steps: int,
        label: str,
        path: Path | None,
    ) -> None:
        total = max(1, total_steps)
        progress.setMaximum(total)
        progress.setValue(max(0, min(completed_steps, total)))
        if path is not None:
            current_index = min(completed_steps + 1, total)
            progress.setLabelText(f"正在导出 ({current_index}/{total})\n{path.name}")
        elif label:
            progress.setLabelText(label)
        self._pump_modal_progress_events()

    def _pump_modal_progress_events(self) -> None:
        QApplication.processEvents(QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents)

    def _close_progress_dialog(self, progress: QProgressDialog | None) -> None:
        if progress is None:
            return
        progress.close()
        progress.deleteLater()
        self._pump_modal_progress_events()

    def _is_export_file_busy_error(self, exc: Exception) -> bool:
        if isinstance(exc, PermissionError):
            return True
        if isinstance(exc, OSError) and getattr(exc, "errno", None) in {13, 16, 32}:
            return True
        lowered = str(exc).lower()
        return "permission denied" in lowered or "being used by another process" in lowered

    def _format_export_failure_message(self, exc: Exception, *, export_path: Path | None) -> str:
        failed_path = getattr(exc, "filename", None)
        resolved_path = Path(failed_path) if isinstance(failed_path, str) and failed_path else export_path
        if self._is_export_file_busy_error(exc):
            if resolved_path is not None:
                return (
                    "无法覆盖导出文件，文件可能正在被其他程序占用：\n"
                    f"{resolved_path}\n\n"
                    "请关闭占用该文件的程序后重试。"
                )
            return "无法覆盖导出文件，文件可能正在被其他程序占用。\n请关闭占用该文件的程序后重试。"
        if resolved_path is not None:
            return f"导出过程中写入文件失败：\n{resolved_path}\n\n{exc}"
        return f"导出过程中发生错误：\n{exc}"

    def _update_action_states(self) -> None:
        self._prune_invalid_workspace_composites()
        document = self.current_document()
        history = document.history if document is not None else None
        has_document = document is not None
        preview_active = self._preview_active
        selection_model = self.measurement_table.selectionModel() if hasattr(self, "measurement_table") else None
        has_selected_rows = bool(selection_model and selection_model.selectedRows())
        has_selected_object = bool(
            has_document
            and self._tool_mode != "calibration"
            and (
                has_selected_rows
                or
                document.view_state.selected_measurement_id is not None
                or document.selected_overlay_id is not None
                or document.selected_construction_id is not None
            )
        )
        has_measurements = bool(document and document.measurements)
        has_measurement_groups = bool(document and document.measurement_group_labels())
        has_deletable_group_target = bool(
            document and (
                document.get_group(document.active_group_id) is not None
                or document.should_show_uncategorized_entry()
            )
        )
        has_named_active_group = bool(document and document.get_group(document.active_group_id) is not None)
        has_editable_active_group = bool(
            has_named_active_group
            or (
                document
                and document.active_group_id is None
                and document.should_show_uncategorized_entry()
            )
        )
        self.close_current_action.setEnabled(has_document)
        self.close_all_action.setEnabled(bool(self.project.documents))
        self.export_current_image_action.setEnabled(has_document and not preview_active)
        can_process_image = has_document and not preview_active
        self.image_processing_workbench_action.setEnabled(can_process_image)
        self.image_batch_processing_action.setEnabled(
            any(
                document_id in self._rasters
                and (
                    self.project.get_document(document_id) is not None
                    and not self.project.get_document(document_id).is_digital_slide()
                )
                for document_id in self._document_order
            )
            and not preview_active
            and not self.image_batch_task_controller.is_busy()
        )
        for action in self._image_operation_actions.values():
            action.setEnabled(can_process_image)
        for action in self._direct_type_actions.values():
            action.setEnabled(can_process_image)
        self.image_information_action.setEnabled(can_process_image)
        self.duplicate_raster_action.setEnabled(can_process_image)
        current_plane = (
            None if document is None else self._rasters.get(document.id)
        )
        self.split_rgb_channels_action.setEnabled(
            can_process_image
            and (
                bool(document and document.is_digital_slide())
                or (
                    current_plane is not None
                    and current_plane.pixel_type
                    in {RasterPixelType.RGB8, RasterPixelType.RGBA8}
                )
            )
        )
        gray_compatibility_counts: dict[tuple[int, int, str], int] = {}
        for candidate_id in self._document_order:
            candidate = self.project.get_document(candidate_id)
            candidate_plane = self._rasters.get(candidate_id)
            if (
                candidate is None
                or candidate.is_digital_slide()
                or candidate_plane is None
                or candidate_plane.pixel_type is not RasterPixelType.GRAY8
            ):
                continue
            key = (
                candidate_plane.width,
                candidate_plane.height,
                self._document_calibration_signature(candidate),
            )
            gray_compatibility_counts[key] = (
                gray_compatibility_counts.get(key, 0) + 1
            )
        self.merge_rgb_channels_action.setEnabled(
            not preview_active
            and any(count >= 3 for count in gray_compatibility_counts.values())
        )
        analysis_busy = self.image_analysis_task_controller.is_busy()
        analysis_batch_busy = self.analysis_batch_controller.busy
        for action in self._analysis_actions.values():
            action.setEnabled(
                can_process_image
                and not analysis_busy
                and not analysis_batch_busy
            )
        has_batch_source_entry = any(
            self.project.get_document(document_id) is not None
            for document_id in self._document_order
        )
        has_batch_raster = any(
            (
                candidate := self.project.get_document(document_id)
            ) is not None
            and not candidate.is_digital_slide()
            and document_id in self._rasters
            for document_id in self._document_order
        )
        self.analysis_batch_action.setEnabled(
            not preview_active
            and not analysis_busy
            and not analysis_batch_busy
            and has_batch_source_entry
        )
        self.analysis_batch_action.setToolTip(
            (
                "对矩阵中勾选的普通图片或显式冻结的切片视窗"
                "执行同一分析配方"
                if has_batch_raster
                else (
                    "当前只有数字化切片或像素不可用的来源；"
                    "可在批量窗口逐个冻结当前切片视窗"
                )
            )
        )
        self.analysis_results_center_action.setEnabled(
            bool(self.project.analysis_artifacts)
        )
        self.fit_action.setEnabled(has_document and not preview_active)
        self.actual_size_action.setEnabled(has_document and not preview_active)
        fullscreen_active = bool(
            self._fullscreen_controller is not None
            and self._fullscreen_controller.is_active
        )
        self.fullscreen_measurement_action.setEnabled(
            fullscreen_active
            or (
                has_document
                and not preview_active
                and self._workspace_mode is WorkspaceMode.MEASURE
            )
        )
        self.toggle_canvas_navigator_action.setEnabled(
            has_document and not preview_active
        )
        self.delete_measurement_action.setEnabled(has_selected_object and not preview_active)
        self.delete_measurement_button.setEnabled(has_selected_object and not preview_active)
        if self._delete_group_measurements_button is not None:
            self._delete_group_measurements_button.setEnabled(has_measurement_groups and not preview_active)
        if self._delete_all_measurements_button is not None:
            self._delete_all_measurements_button.setEnabled(has_measurements and not preview_active)
        self.add_group_action.setEnabled(has_document and not preview_active)
        self.rename_group_action.setEnabled(has_editable_active_group and not preview_active)
        self.delete_group_action.setEnabled(has_deletable_group_target and not preview_active)
        if self._add_group_button is not None:
            self._add_group_button.setEnabled(has_document and not preview_active)
        if self._rename_group_button is not None:
            self._rename_group_button.setEnabled(has_editable_active_group and not preview_active)
        if self.delete_group_button is not None:
            self.delete_group_button.setEnabled(has_deletable_group_target and not preview_active)
        has_preset = bool(self._calibration_presets())
        if self._add_preset_button is not None:
            self._add_preset_button.setEnabled(True)
        if self._edit_preset_button is not None:
            self._edit_preset_button.setEnabled(has_preset)
        if self._delete_preset_button is not None:
            self._delete_preset_button.setEnabled(has_preset)
        if self._import_cu_preset_button is not None:
            self._import_cu_preset_button.setEnabled(_CU_SCALE_IMPORT_ERROR is None)
        if self._apply_preset_button is not None:
            self._apply_preset_button.setEnabled(has_document and has_preset and not preview_active)
        if self._area_auto_button is not None:
            area_inference_available = "area-inference" in self._runtime_features
            self._area_auto_button.setVisible(area_inference_available)
            self._area_auto_button.setEnabled(
                area_inference_available
                and has_document
                and bool(self._app_settings.area_model_mappings)
                and not preview_active
                and not (document is not None and document.is_digital_slide())
            )
        workspace_undo_available = bool(
            document
            and self._workspace_composite_available_for(document, redo=False)
        )
        workspace_redo_available = bool(
            document
            and self._workspace_composite_available_for(document, redo=True)
        )
        undo_waiting = bool(
            document
            and self._workspace_composite_waits_on_other_document(
                document,
                redo=False,
            )
        )
        redo_waiting = bool(
            document
            and self._workspace_composite_waits_on_other_document(
                document,
                redo=True,
            )
        )
        self.undo_action.setEnabled(
            (
                workspace_undo_available
                or bool(history and history.can_undo() and not undo_waiting)
            )
            and not preview_active
        )
        self.redo_action.setEnabled(
            (
                workspace_redo_available
                or bool(history and history.can_redo() and not redo_waiting)
            )
            and not preview_active
        )
        capture_feature_available = _CAPTURE_IMPORT_ERROR is None
        self.switch_capture_device_action.setEnabled(capture_feature_available)
        self.live_preview_action.setEnabled(capture_feature_available)
        if self.digital_slide_action is not None:
            self.digital_slide_action.setEnabled(capture_feature_available and not self._preview_analysis_finalizing)
            self.digital_slide_action.setToolTip("进入数字化切片采集工作台")
        can_optimize_signal = capture_feature_available and self._capture_manager.can_optimize_signal()
        analysis_active = self._preview_analysis_mode != "none"
        self.capture_frame_action.setEnabled(preview_active and self._capture_manager.can_capture_still() and not analysis_active and not self._digital_slide_mode)
        self.optimize_capture_signal_action.setVisible(can_optimize_signal)
        self.optimize_capture_signal_action.setEnabled(can_optimize_signal and not analysis_active and not self._digital_slide_mode)
        for mode, action in self._mode_actions.items():
            action.setEnabled(not preview_active or mode == "select")
        if self._manual_tool_button is not None:
            self._manual_tool_button.setEnabled(not preview_active)
        if self._area_tool_button is not None:
            self._area_tool_button.setEnabled(not preview_active)
        if self._magic_tool_button is not None:
            magic_available = "magic-segmentation" in self._runtime_features
            self._magic_tool_button.setVisible(magic_available)
            self._magic_tool_button.setEnabled(magic_available and not preview_active)
            for mode in (
                MagicSegmentToolMode.STANDARD,
                MagicSegmentToolMode.REFERENCE,
                MagicSegmentToolMode.FIBER_QUICK,
            ):
                action = self._mode_actions.get(mode)
                if action is not None:
                    action.setVisible(magic_available)
        if self._construction_tool_button is not None:
            self._construction_tool_button.setEnabled(not preview_active)
        if self._overlay_tool_button is not None:
            self._overlay_tool_button.setEnabled(not preview_active)
        self._update_path_drawing_controls()
        self._update_magic_segment_controls()
        self._update_count_numbers_button()
        self._update_preview_analysis_controls()
        if self._measurement_tool_strip is not None:
            self._measurement_tool_strip.setConstructionContextVisible(
                self._tool_mode == "construction" and not preview_active
            )
        self._sync_manual_tool_button()
        self._sync_area_tool_button()
        self._sync_magic_tool_button()
        self._sync_construction_tool_button()
        self._sync_overlay_tool_button()
        self._sync_digital_slide_navigation_action()
        self._update_project_navigation_summary()

    def _magic_prompt_label_text(self, prompt_type: str) -> str:
        return "当前提示：负采样点" if prompt_type == "negative" else "当前提示：正采样点"

    def _magic_operation_label_text(self, operation_mode: str) -> str:
        if operation_mode == MagicSegmentOperationMode.SUBTRACT:
            return "当前编辑：剔除形状"
        return "当前编辑：主体"

    def _magic_operation_button_text(self, operation_mode: str) -> str:
        if operation_mode == MagicSegmentOperationMode.SUBTRACT:
            return "剔除(T)"
        return "添加(T)"

    def _magic_subtract_input_label(self, mode: str) -> str:
        return {
            MagicSegmentSubtractInputMode.POLYGON: "多边形剔除",
            MagicSegmentSubtractInputMode.FREEHAND: "自由圈选剔除",
        }.get(MagicSegmentSubtractInputMode.normalize(mode), "智能剔除")

    def _magic_subtract_input_tooltip(self, mode: str) -> str:
        return {
            MagicSegmentSubtractInputMode.POLYGON: "点击添加顶点，双击、靠近起点点击或 Enter 闭合剔除区域",
            MagicSegmentSubtractInputMode.FREEHAND: "按住拖拽圈出要剔除的区域，松手后生成剔除草稿",
        }.get(MagicSegmentSubtractInputMode.normalize(mode), "点选目标并由魔棒生成剔除草稿")

    def _remember_magic_subtract_input_mode(self, mode: str) -> str:
        normalized = MagicSegmentSubtractInputMode.normalize(mode)
        self._magic_standard_subtract_input_mode = normalized
        if getattr(self._app_settings, "magic_segment_standard_subtract_input_mode", None) != normalized:
            self._app_settings.magic_segment_standard_subtract_input_mode = normalized
            self._save_app_settings(context="剔除方式")
        return normalized

    def _sync_canvas_magic_subtract_input_mode(self, canvas: DocumentCanvas | None) -> None:
        if canvas is None or canvas.has_magic_manual_subtract_draft():
            return
        canvas.set_magic_subtract_input_mode(self._magic_standard_subtract_input_mode)

    def _confirm_discard_magic_manual_subtract_draft(self, title: str, text: str) -> bool:
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.Warning)
        box.setWindowTitle(title)
        box.setText(text)
        discard_button = box.addButton("丢弃草稿并切换", QMessageBox.ButtonRole.DestructiveRole)
        cancel_button = box.addButton("取消切换", QMessageBox.ButtonRole.RejectRole)
        box.setDefaultButton(cancel_button)
        box.exec()
        return box.clickedButton() == discard_button

    def _set_magic_subtract_input_mode(self, mode: str) -> None:
        canvas = self.current_canvas()
        if canvas is None or not is_magic_segment_tool_mode(self._tool_mode):
            return
        normalized = MagicSegmentSubtractInputMode.normalize(mode)
        if canvas.current_magic_subtract_input_mode() == normalized:
            self._remember_magic_subtract_input_mode(normalized)
            self._update_magic_segment_controls()
            return
        if canvas.has_magic_manual_subtract_draft():
            if not self._confirm_discard_magic_manual_subtract_draft(
                "切换剔除方式",
                "当前剔除区域尚未闭合。要丢弃草稿并切换剔除方式吗？",
            ):
                self._update_magic_segment_controls()
                return
        normalized = self._remember_magic_subtract_input_mode(normalized)
        canvas.set_magic_subtract_input_mode(normalized)
        self.statusBar().showMessage(f"已切换为{self._magic_subtract_input_label(normalized)}", 2500)
        self._update_magic_segment_controls()

    def _current_magic_roi_enabled(self, tool_mode: str | None = None, *, operation_mode: str | None = None) -> bool:
        active_mode = str(tool_mode or self._tool_mode or "").strip()
        if is_fiber_quick_tool_mode(active_mode):
            return bool(self._fiber_quick_roi_enabled)
        if is_magic_segment_tool_mode(active_mode):
            active_operation = operation_mode
            if active_operation is None:
                canvas = self.current_canvas()
                active_operation = (
                    canvas.current_magic_segment_operation_mode()
                    if canvas is not None
                    else MagicSegmentOperationMode.ADD
                )
            if active_operation == MagicSegmentOperationMode.SUBTRACT:
                return bool(self._magic_standard_subtract_roi_enabled)
            return bool(self._magic_standard_add_roi_enabled)
        return False

    def _set_magic_roi_enabled(self, tool_mode: str, enabled: bool, *, operation_mode: str | None = None) -> None:
        enabled = bool(enabled)
        settings_changed = False
        if is_fiber_quick_tool_mode(tool_mode):
            self._fiber_quick_roi_enabled = enabled
            if self._app_settings.fiber_quick_roi_enabled != enabled:
                self._app_settings.fiber_quick_roi_enabled = enabled
                settings_changed = True
        elif is_magic_segment_tool_mode(tool_mode):
            if operation_mode == MagicSegmentOperationMode.SUBTRACT:
                self._magic_standard_subtract_roi_enabled = enabled
                if self._app_settings.magic_segment_standard_subtract_roi_enabled != enabled:
                    self._app_settings.magic_segment_standard_subtract_roi_enabled = enabled
                    settings_changed = True
            else:
                self._magic_standard_add_roi_enabled = enabled
                if self._app_settings.magic_segment_standard_add_roi_enabled != enabled:
                    self._app_settings.magic_segment_standard_add_roi_enabled = enabled
                    settings_changed = True
                if self._app_settings.magic_segment_standard_roi_enabled != enabled:
                    self._app_settings.magic_segment_standard_roi_enabled = enabled
                    settings_changed = True
        if settings_changed:
            self._save_app_settings(context="魔杖选项")

    def _set_active_magic_roi_checked(self, checked: bool) -> None:
        if not (is_magic_segment_tool_mode(self._tool_mode) or is_fiber_quick_tool_mode(self._tool_mode)):
            return
        operation_mode = None
        if is_magic_segment_tool_mode(self._tool_mode):
            canvas = self.current_canvas()
            operation_mode = (
                canvas.current_magic_segment_operation_mode()
                if canvas is not None
                else MagicSegmentOperationMode.ADD
            )
        checked = bool(checked)
        if self._current_magic_roi_enabled(operation_mode=operation_mode) == checked:
            self._update_magic_segment_controls()
            return
        self._set_magic_roi_enabled(self._tool_mode, checked, operation_mode=operation_mode)
        state_text = "启用" if checked else "关闭"
        self.statusBar().showMessage(f"已{state_text}ROI局部分割", 2500)
        self._update_magic_segment_controls()

    def _toggle_active_magic_roi(self) -> None:
        if not (is_magic_segment_tool_mode(self._tool_mode) or is_fiber_quick_tool_mode(self._tool_mode)):
            return
        operation_mode = None
        if is_magic_segment_tool_mode(self._tool_mode):
            canvas = self.current_canvas()
            operation_mode = (
                canvas.current_magic_segment_operation_mode()
                if canvas is not None
                else MagicSegmentOperationMode.ADD
            )
        self._set_magic_roi_enabled(
            self._tool_mode,
            not self._current_magic_roi_enabled(operation_mode=operation_mode),
            operation_mode=operation_mode,
        )
        state_text = "启用" if self._current_magic_roi_enabled(operation_mode=operation_mode) else "关闭"
        self.statusBar().showMessage(f"已{state_text}ROI局部分割", 2500)
        self._update_magic_segment_controls()

    def _magic_small_object_enhancement_context_active(
        self,
        *,
        tool_mode: str | None = None,
        operation_mode: str | None = None,
        roi_enabled: bool | None = None,
    ) -> bool:
        active_tool = str(tool_mode or self._tool_mode or "").strip()
        if not is_magic_segment_tool_mode(active_tool):
            return False
        active_operation = operation_mode
        if active_operation is None:
            canvas = self.current_canvas()
            active_operation = (
                canvas.current_magic_segment_operation_mode()
                if canvas is not None
                else MagicSegmentOperationMode.ADD
            )
        if active_operation != MagicSegmentOperationMode.SUBTRACT:
            return False
        canvas = self.current_canvas()
        if (
            canvas is not None
            and is_magic_segment_tool_mode(active_tool)
            and canvas.current_magic_subtract_input_mode() != MagicSegmentSubtractInputMode.SMART
        ):
            return False
        active_roi = self._current_magic_roi_enabled(active_tool, operation_mode=active_operation) if roi_enabled is None else bool(roi_enabled)
        return bool(active_roi and self._app_settings.magic_segment_restrict_subtract_roi_to_primary_bounds)

    def _toggle_magic_small_object_enhancement(self, checked: bool) -> None:
        self._app_settings.magic_segment_small_object_subtract_enhancement_enabled = bool(checked)
        if not checked:
            self._hide_small_object_preview()
        self._save_app_settings(context="小洞")
        self._update_magic_segment_controls()
        self.statusBar().showMessage("小洞已开启" if checked else "小洞已关闭", 2500)

    def _update_magic_segment_controls(self) -> None:
        if self._magic_controls_widget is None or self._measurement_tool_strip is None:
            return
        is_visible = is_magic_toolbar_tool_mode(self._tool_mode) and not self._preview_active
        self._measurement_tool_strip.setMagicContextVisible(is_visible)
        if not is_visible:
            self._hide_small_object_preview()
            return
        canvas = self.current_canvas()
        has_document = canvas is not None and canvas.document_id is not None
        standard_mode = is_magic_segment_tool_mode(self._tool_mode)
        fiber_quick_mode = is_fiber_quick_tool_mode(self._tool_mode)
        if standard_mode:
            prompt_type = canvas.current_magic_segment_prompt_type() if canvas is not None else "positive"
            operation_mode = (
                canvas.current_magic_segment_operation_mode()
                if canvas is not None
                else MagicSegmentOperationMode.ADD
            )
            subtract_input_mode = (
                canvas.current_magic_subtract_input_mode()
                if canvas is not None
                else MagicSegmentSubtractInputMode.SMART
            )
            busy = bool(canvas and canvas.is_magic_segment_busy())
        elif fiber_quick_mode:
            prompt_type = canvas.current_fiber_quick_prompt_type() if canvas is not None else "positive"
            operation_mode = MagicSegmentOperationMode.ADD
            subtract_input_mode = MagicSegmentSubtractInputMode.SMART
            busy = bool(canvas and canvas.is_fiber_quick_busy())
        else:
            prompt_type = "positive"
            operation_mode = MagicSegmentOperationMode.ADD
            subtract_input_mode = MagicSegmentSubtractInputMode.SMART
            busy = bool(canvas and canvas.is_reference_instance_busy())
        if self._magic_prompt_label is not None:
            self._magic_prompt_label.setVisible(False)
            show_reference_prompt = self._measurement_tool_strip.isContextInline()
            if not standard_mode and not fiber_quick_mode and canvas is not None and canvas.has_reference_instance_preview():
                self._magic_prompt_label.setText("候选预览")
                self._magic_prompt_label.setVisible(show_reference_prompt)
            elif not standard_mode and not fiber_quick_mode:
                self._magic_prompt_label.setText("拖框或点已确认面积作为参考")
                self._magic_prompt_label.setVisible(show_reference_prompt)
        if self._magic_toggle_button is not None:
            show_prompt_toggle = (
                fiber_quick_mode
                or (
                    standard_mode
                    and (
                        operation_mode != MagicSegmentOperationMode.SUBTRACT
                        or subtract_input_mode == MagicSegmentSubtractInputMode.SMART
                    )
                )
            )
            self._magic_toggle_button.setVisible(show_prompt_toggle)
            if standard_mode:
                visual = magic_prompt_visual(prompt_type)
                self._magic_toggle_button.setText(f"{visual.button_label}(R)")
                self._magic_toggle_button.setProperty("magicPrompt", visual.prompt_type)
            else:
                self._magic_toggle_button.setText("正负(R)")
                self._magic_toggle_button.setProperty("magicPrompt", "")
            self._measurement_tool_strip._apply_button_palette(self._magic_toggle_button)
            refresh_widget_theme(self._magic_toggle_button)
            self._magic_toggle_button.setEnabled(
                has_document
                and show_prompt_toggle
                and (fiber_quick_mode or not busy)
            )
        roi_enabled = self._current_magic_roi_enabled(operation_mode=operation_mode)
        small_object_context = self._magic_small_object_enhancement_context_active(
            tool_mode=self._tool_mode,
            operation_mode=operation_mode,
            roi_enabled=roi_enabled,
        )
        small_object_enabled = bool(self._app_settings.magic_segment_small_object_subtract_enhancement_enabled)
        if not small_object_context or not small_object_enabled:
            self._hide_small_object_preview()
        if self._magic_operation_button is not None:
            self._magic_operation_button.setVisible(standard_mode)
            self._magic_operation_button.setText(self._magic_operation_button_text(operation_mode))
            self._magic_operation_button.setProperty(
                "magicPrompt",
                "negative" if operation_mode == MagicSegmentOperationMode.SUBTRACT else "",
            )
            self._measurement_tool_strip._apply_button_palette(self._magic_operation_button)
            refresh_widget_theme(self._magic_operation_button)
            self._magic_operation_button.setEnabled(has_document and standard_mode and not busy)
        if self._magic_subtract_mode_button is not None:
            self._magic_subtract_mode_button.setVisible(standard_mode and operation_mode == MagicSegmentOperationMode.SUBTRACT)
            self._magic_subtract_mode_button.setText(f"剔除方式：{self._magic_subtract_input_label(subtract_input_mode)}")
            self._magic_subtract_mode_button.setToolTip(self._magic_subtract_input_tooltip(subtract_input_mode))
            self._magic_subtract_mode_button.setEnabled(has_document and standard_mode and not busy)
        for mode, action in self._magic_subtract_mode_actions.items():
            action.setChecked(mode == subtract_input_mode)
            action.setEnabled(has_document and standard_mode and operation_mode == MagicSegmentOperationMode.SUBTRACT and not busy)
        if self._magic_options_button is not None:
            self._magic_options_button.setVisible(standard_mode or fiber_quick_mode)
            self._magic_options_button.setText("选项")
            self._magic_options_button.setToolTip(
                f"工具选项：ROI {'开启' if roi_enabled else '关闭'}；"
                f"小洞增强 {'开启' if small_object_enabled else '关闭'}"
            )
            self._magic_options_button.setEnabled(has_document and (standard_mode or fiber_quick_mode))
        if self._magic_roi_option_checkbox is not None:
            self._magic_roi_option_checkbox.blockSignals(True)
            self._magic_roi_option_checkbox.setChecked(roi_enabled)
            self._magic_roi_option_checkbox.setEnabled(has_document and (standard_mode or fiber_quick_mode))
            self._magic_roi_option_checkbox.blockSignals(False)
        if self._magic_small_object_option_checkbox is not None:
            self._magic_small_object_option_checkbox.blockSignals(True)
            self._magic_small_object_option_checkbox.setChecked(small_object_enabled)
            self._magic_small_object_option_checkbox.setEnabled(has_document and small_object_context and not busy)
            self._magic_small_object_option_checkbox.blockSignals(False)
        if self._magic_small_object_option_hint is not None:
            if small_object_context:
                self._magic_small_object_option_hint.setText("小洞增强已可用于当前智能剔除")
            else:
                self._magic_small_object_option_hint.setText("仅在标准魔棒的智能剔除、ROI 开启时可用")
        if self._magic_confirm_subtract_button is not None:
            self._magic_confirm_subtract_button.setVisible(standard_mode and operation_mode == MagicSegmentOperationMode.SUBTRACT)
            self._magic_confirm_subtract_button.setText("加洞(S)")
            self._magic_confirm_subtract_button.setEnabled(
                bool(canvas and canvas.can_confirm_current_magic_subtract_shape())
            )
        if self._magic_complete_button is not None:
            self._magic_complete_button.setText(
                "完成"
                if standard_mode
                else ("完成" if fiber_quick_mode else "加入")
            )
            self._magic_complete_button.setToolTip(
                "提交当前魔棒结果（Enter / F）"
                if standard_mode
                else ("确认快速测径结果（Enter / F）" if fiber_quick_mode else "加入参考实例结果（Enter / F）")
            )
            self._magic_complete_button.setEnabled(
                bool(
                    canvas
                    and (
                        (
                            canvas.has_magic_segment_preview()
                            if standard_mode
                            else (
                                canvas.has_fiber_quick_shape_preview()
                                if fiber_quick_mode
                                else canvas.has_reference_instance_preview()
                            )
                        )
                    )
                    and (
                        not busy
                        if not fiber_quick_mode
                        else not bool(canvas and canvas._fiber_quick.segmentation_busy)  # noqa: SLF001
                    )
                )
            )
        if self._magic_cancel_button is not None:
            self._magic_cancel_button.setText("取消")
            self._magic_cancel_button.setToolTip("取消当前魔棒会话或草稿（Esc）")
            self._magic_cancel_button.setEnabled(
                bool(
                    canvas
                    and (
                        canvas.has_magic_segment_session()
                        if standard_mode
                        else (
                            canvas.has_fiber_quick_session()
                            if fiber_quick_mode
                            else canvas.has_reference_instance_session()
                        )
                    )
                )
            )
        self._measurement_tool_strip._refresh_context_visibility()  # noqa: SLF001
        layout = self._magic_controls_widget.layout()
        if layout is not None:
            layout.invalidate()
            layout.activate()
        self._magic_controls_widget.updateGeometry()
        self._magic_controls_widget.adjustSize()
        self._measurement_tool_strip.updateGeometry()

    def _ensure_small_object_preview_window(self) -> SmallObjectEnhancementPreviewWindow:
        if self._small_object_preview_window is None:
            self._small_object_preview_window = SmallObjectEnhancementPreviewWindow(self)
        return self._small_object_preview_window

    def _hide_small_object_preview(self) -> None:
        if self._small_object_preview_window is not None:
            self._small_object_preview_window.hide()

    def _small_object_reject_label(self, reason: str) -> str:
        return {
            "empty_mask": "未找到目标",
            "mask_too_large": "结果过大",
            "touches_workspace_edges": "结果触及工作区边缘",
            "positive_outside_workspace": "正采样点超出工作区",
        }.get(reason, "置信度不足")

    def _show_small_object_preview(
        self,
        canvas: DocumentCanvas,
        metadata: dict[str, object],
        polygon_px: list[Point],
    ) -> None:
        if not self._magic_small_object_enhancement_context_active():
            self._hide_small_object_preview()
            return
        preview = self._ensure_small_object_preview_window()
        if not preview.set_preview(metadata, polygon_px):
            return
        box = metadata.get("small_object_workspace_box")
        if isinstance(box, (tuple, list)) and len(box) == 4:
            self._position_small_object_preview(preview, canvas, box)
        preview.show()
        preview.raise_()

    def _position_small_object_preview(
        self,
        preview: SmallObjectEnhancementPreviewWindow,
        canvas: DocumentCanvas,
        box: object,
    ) -> None:
        try:
            x0, y0, x1, y1 = [float(value) for value in box]  # type: ignore[arg-type]
        except (TypeError, ValueError):
            return
        top_left = canvas.image_to_widget(Point(x0, y0))
        bottom_right = canvas.image_to_widget(Point(x1, y1))
        roi_rect = QRectF(top_left, bottom_right).normalized()
        roi_global_top_left = canvas.mapToGlobal(QPoint(int(roi_rect.left()), int(roi_rect.top())))
        roi_global = QRect(
            roi_global_top_left.x(),
            roi_global_top_left.y(),
            max(1, int(round(roi_rect.width()))),
            max(1, int(round(roi_rect.height()))),
        )
        margin = 12
        size = preview.size()
        screen = QGuiApplication.screenAt(roi_global.center()) or canvas.screen() or QGuiApplication.primaryScreen()
        available = screen.availableGeometry() if screen is not None else QRect(0, 0, 1280, 720)
        candidates = [
            QRect(roi_global.right() + margin, roi_global.top(), size.width(), size.height()),
            QRect(roi_global.left() - size.width() - margin, roi_global.top(), size.width(), size.height()),
            QRect(roi_global.left(), roi_global.bottom() + margin, size.width(), size.height()),
            QRect(roi_global.left(), roi_global.top() - size.height() - margin, size.width(), size.height()),
        ]
        for candidate in candidates:
            if available.contains(candidate) and not candidate.intersects(roi_global):
                preview.move(candidate.topLeft())
                return
        x = min(max(available.left(), roi_global.right() + margin), max(available.left(), available.right() - size.width()))
        y = min(max(available.top(), roi_global.top()), max(available.top(), available.bottom() - size.height()))
        fallback = QRect(int(x), int(y), size.width(), size.height())
        if fallback.intersects(roi_global):
            x = max(available.left(), available.right() - size.width())
            y = available.top()
        preview.move(QPoint(int(x), int(y)))

    def _commit_active_path_drawing(self) -> bool:
        canvas = self.current_canvas()
        if canvas is None:
            return False
        committed = canvas.commit_pending_path()
        self._update_path_drawing_controls()
        return committed

    def _cycle_area_edit_operation_mode(self) -> bool:
        canvas = self.current_canvas()
        if canvas is None or not canvas.has_selected_area_measurement():
            return False
        if canvas.has_area_edit_draft():
            self.statusBar().showMessage("请先完成或取消当前绘制后再切换添加/剔除。", 3000)
            return False
        current_mode = canvas.current_area_edit_operation_mode()
        next_mode = (
            AreaEditOperationMode.SUBTRACT
            if current_mode == AreaEditOperationMode.ADD
            else AreaEditOperationMode.ADD
        )
        canvas.set_area_edit_operation_mode(next_mode)
        status_message = (
            "面积工具已切换为剔除"
            if next_mode == AreaEditOperationMode.SUBTRACT
            else "面积工具已切换为添加"
        )
        self.statusBar().showMessage(status_message, 2500)
        self._update_path_drawing_controls()
        return True

    def _cancel_active_path_drawing(self) -> bool:
        canvas = self.current_canvas()
        if canvas is None:
            return False
        cancelled = canvas.cancel_pending_path()
        self._update_path_drawing_controls()
        return cancelled

    def _update_path_drawing_controls(self) -> None:
        if self._path_controls_widget is None or self._measurement_tool_strip is None:
            return
        is_visible = (
            self._tool_mode
            in {"manual", "continuous_manual", "snap", "polygon_area", "freehand_area"}
            and not self._preview_active
        )
        self._measurement_tool_strip.setPathContextVisible(is_visible)
        if not is_visible:
            if self._area_operation_button is not None:
                self._area_operation_button.setVisible(False)
            return
        canvas = self.current_canvas()
        show_area_operation = bool(
            canvas
            and self._tool_mode in {"polygon_area", "freehand_area"}
            and canvas.has_selected_area_measurement()
        )
        if self._area_operation_button is not None:
            self._area_operation_button.setVisible(show_area_operation)
            area_operation_mode = (
                canvas.current_area_edit_operation_mode()
                if canvas is not None
                else AreaEditOperationMode.ADD
            )
            subtract_active = area_operation_mode == AreaEditOperationMode.SUBTRACT
            self._area_operation_button.setText("剔除(T)" if subtract_active else "添加(T)")
            self._area_operation_button.setToolTip(
                "当前会从选中面积中剔除绘制区域（T）"
                if subtract_active
                else "当前会绘制新的面积测量（T）"
            )
            self._area_operation_button.setProperty("magicPrompt", "negative" if subtract_active else "")
            self._area_operation_button.setEnabled(show_area_operation)
            self._measurement_tool_strip._apply_button_palette(self._area_operation_button)
            refresh_widget_theme(self._area_operation_button)
        if self._path_complete_button is not None:
            self._path_complete_button.setEnabled(bool(canvas and canvas.can_commit_pending_path()))
        if self._path_cancel_button is not None:
            self._path_cancel_button.setEnabled(bool(canvas and canvas.has_pending_path_drawing()))
        self._measurement_tool_strip._refresh_context_visibility()  # noqa: SLF001
        layout = self._path_controls_widget.layout()
        if layout is not None:
            layout.invalidate()
            layout.activate()
        self._path_controls_widget.updateGeometry()
        self._path_controls_widget.adjustSize()
        self._measurement_tool_strip.updateGeometry()

    def _preview_analysis_supported(self, mode: str | None = None) -> bool:
        selected = self._selected_capture_device()
        if not bool(
            self._preview_active
            and selected is not None
            and self._capture_manager.can_request_analysis_frame()
        ):
            return False
        if mode == "map_build":
            return self.MAP_BUILD_AVAILABLE
        return True

    def _sync_preview_analysis_buttons(self) -> None:
        if self._focus_stack_button is not None:
            self._focus_stack_button.blockSignals(True)
            self._focus_stack_button.setChecked(self._preview_analysis_mode == "focus_stack")
            self._focus_stack_button.blockSignals(False)
        if self._map_build_button is not None:
            self._map_build_button.blockSignals(True)
            self._map_build_button.setChecked(self._preview_analysis_mode == "map_build")
            self._map_build_button.blockSignals(False)
        if self._acquisition_focus_stack_button is not None:
            self._acquisition_focus_stack_button.blockSignals(True)
            self._acquisition_focus_stack_button.setChecked(self._preview_analysis_mode == "focus_stack")
            self._acquisition_focus_stack_button.blockSignals(False)
        if self._acquisition_map_button is not None:
            self._acquisition_map_button.blockSignals(True)
            self._acquisition_map_button.setChecked(self._preview_analysis_mode == "map_build")
            self._acquisition_map_button.blockSignals(False)

    def _update_preview_analysis_controls(self) -> None:
        if self._preview_analysis_widget is None or self._measurement_tool_strip is None:
            return
        is_visible = self._preview_active
        self._measurement_tool_strip.setPreviewContextVisible(is_visible)
        selected = self._selected_capture_device()
        focus_supported = self._preview_analysis_supported("focus_stack")
        map_supported = self._preview_analysis_supported("map_build")
        focus_tooltip = "实时预览分析：景深合成"
        map_tooltip = "实时预览分析：地图构建"
        if not self.MAP_BUILD_AVAILABLE:
            map_tooltip = "当前版本未启用地图构建。"
        focus_enabled = is_visible and focus_supported and not self._preview_analysis_finalizing and not self._digital_slide_mode
        map_enabled = is_visible and not self._preview_analysis_finalizing and not self._digital_slide_mode and (
            map_supported or not self.MAP_BUILD_AVAILABLE
        )
        if self._focus_stack_button is not None:
            self._focus_stack_button.setEnabled(focus_enabled)
            self._focus_stack_button.setToolTip(focus_tooltip)
        if self._map_build_button is not None:
            self._map_build_button.setEnabled(map_enabled)
            self._map_build_button.setToolTip(map_tooltip)
        if self._acquisition_focus_stack_button is not None:
            self._acquisition_focus_stack_button.setEnabled(focus_enabled)
            self._acquisition_focus_stack_button.setToolTip(focus_tooltip)
        if self._acquisition_map_button is not None:
            self._acquisition_map_button.setEnabled(map_enabled)
            self._acquisition_map_button.setToolTip(map_tooltip)
        self._sync_digital_slide_mode_ui()
        self._sync_preview_analysis_buttons()

    def _preview_analysis_intro_text(self, mode: str) -> str:
        if mode == "map_build":
            return "移动样品台到相邻视野，保持 20%-40% 重叠并等待静止；系统会先合成每个 tile，再拼接可靠地图。按 Enter 或 F 结束，Esc 取消。"
        return "尽量均匀地从一个焦距移动到另一个焦距，系统会持续采样并合成清晰图像。按 Enter 或 F 结束，Esc 取消。"

    def _analysis_mode_label(self, mode: str) -> str:
        return {
            "focus_stack": "景深合成",
            "map_build": "地图构建",
        }.get(mode, mode)

    def _preview_analysis_finalize_message(self, mode: str) -> str:
        if mode == "map_build":
            return "正在完成地图构建，请稍候…"
        return "正在完成景深合成，请稍候…"

    def _preview_analysis_interval_ms(self, mode: str) -> int:
        if mode == "map_build":
            return MAP_BUILD_ANALYSIS_INTERVAL_MS
        return self.PREVIEW_ANALYSIS_INTERVAL_MS

    def _map_build_state_banner(self, report: MapBuildReport) -> tuple[str, str, str]:
        state_map = {
            "moving": ("正在移动", "moving"),
            "settling": ("等待静止", "settling"),
            "sampling": ("正在采样", "sampling"),
            "tile_committed": ("已创建新 tile", "success"),
            "candidate_rejected": ("候选位置未通过", "warning"),
        }
        title, tone = state_map.get(report.motion_state, (report.motion_state, "neutral"))
        stable_count = min(report.stable_streak, MAP_BUILD_STABLE_REQUIRED_FRAMES)
        if report.motion_state == "moving":
            detail = f"请移动到相邻视野后停稳 | 位移 {report.translation_px:.1f}px | tile {report.tile_count}"
        elif report.motion_state == "settling":
            detail = f"保持不动，正在确认稳定 {stable_count}/{MAP_BUILD_STABLE_REQUIRED_FRAMES} | 位移 {report.translation_px:.1f}px"
        elif report.motion_state == "sampling":
            detail = f"当前视野已稳定，正在积累 tile | tile {report.tile_count} | 接受 {report.accepted_frames} 帧"
        elif report.motion_state == "tile_committed":
            detail = f"新 tile 已加入地图 | tile {report.tile_count} | 响应 {report.correlation_response:.2f}"
        elif report.motion_state == "candidate_rejected":
            detail = "当前位置匹配不可靠，请增加纹理或调整到 20%-40% 重叠后再停稳。"
        else:
            detail = report.message
        return title, detail, tone

    def _current_focus_stack_render_config(self) -> FocusStackRenderConfig:
        return FocusStackRenderConfig(
            profile=self._app_settings.focus_stack_profile or FocusStackProfile.BALANCED,
            sharpen_strength=self._app_settings.focus_stack_sharpen_strength,
        ).normalized_copy()

    def _toggle_preview_analysis_mode(self, mode: str, checked: bool) -> None:
        if not checked:
            if self._preview_analysis_mode == mode:
                self._cancel_preview_analysis_session(message=f"已取消{self._analysis_mode_label(mode)}")
            else:
                self._sync_preview_analysis_buttons()
            return
        if not self._preview_analysis_supported(mode):
            message = "该功能需要实时预览已提供可用分析帧。"
            if mode == "map_build":
                message = "地图构建需要实时预览已提供可用分析帧。"
            self._sync_preview_analysis_buttons()
            QMessageBox.information(self, self._analysis_mode_label(mode), message)
            return
        if self._preview_analysis_mode != "none":
            self._cancel_preview_analysis_session()
        self._start_preview_analysis_session(mode)

    def _create_preview_analysis_dialog(self, mode: str) -> PreviewAnalysisDialog:
        dialog = PreviewAnalysisDialog(
            self._analysis_mode_label(mode),
            intro_text=self._preview_analysis_intro_text(mode),
            compact=mode == "map_build",
            show_state_banner=mode == "map_build",
            parent=self,
        )
        dialog.finishRequested.connect(self._finalize_preview_analysis_session)
        dialog.cancelRequested.connect(lambda: self._cancel_preview_analysis_session())
        return dialog

    def _start_preview_analysis_session(self, mode: str) -> None:
        self.preview_analysis_task_controller.start_session(mode)

    def _teardown_preview_analysis_session(self, *, cancel_worker: bool, status_message: str | None = None):
        return self.preview_analysis_task_controller.teardown(
            cancel_worker=cancel_worker,
            status_message=status_message,
        )

    def _cancel_preview_analysis_session(self, *, message: str | None = None) -> None:
        self.preview_analysis_task_controller.cancel(message=message)

    def _finalize_preview_analysis_session(self) -> None:
        self.preview_analysis_task_controller.finalize()

    def _request_preview_analysis_frame(self) -> None:
        self.preview_analysis_task_controller.request_frame()

    def _on_preview_analysis_frame_ready(self, request_id: int, image: object) -> None:
        self.preview_analysis_task_controller.on_frame_ready(request_id, image)

    def _on_preview_analysis_frame_failed(self, request_id: int, message: str) -> None:
        self.preview_analysis_task_controller.on_frame_failed(request_id, message)

    def _on_preview_analysis_worker_preview(self, payload: object) -> None:
        if self._preview_analysis_dialog is None:
            return
        if isinstance(payload, FocusStackReport):
            self._preview_analysis_dialog.set_result_image(payload.preview_image)
            self._preview_analysis_dialog.set_status(payload.message)
            self.statusBar().showMessage(payload.message, 2500)
            return
        if isinstance(payload, MapBuildReport):
            self._preview_analysis_dialog.set_result_image(payload.preview_image)
            title, detail, tone = self._map_build_state_banner(payload)
            self._preview_analysis_dialog.set_state_banner(title, detail, tone)
            self._preview_analysis_dialog.set_status(payload.message)
            self.statusBar().showMessage(payload.message, 2500)

    def _add_project_asset_image(self, image: QImage, *, metadata: dict[str, object] | None = None, status_message: str) -> None:
        document = ImageDocument(
            id=new_id("image"),
            path=self._next_project_capture_relative_path(),
            image_size=(image.width(), image.height()),
            source_type="project_asset",
            metadata=dict(metadata or {}),
        )
        document.initialize_runtime_state()
        if self.project.project_default_calibration is not None:
            self._set_document_project_default_calibration(document)
        document.mark_session_saved()
        document.mark_calibration_saved()
        self._mount_document(
            document,
            image,
            tooltip=self._document_tooltip(document),
        )
        self._clear_prompt_segmentation_cache()
        self.statusBar().showMessage(status_message, 4000)

    def _on_preview_analysis_worker_finished(self, payload: object) -> None:
        mode = self._preview_analysis_mode
        if mode == "none":
            return
        if isinstance(payload, FocusStackFinalResult):
            image = payload.image
            metadata = dict(payload.metadata)
            message = f"景深合成完成，已导入项目（采样 {payload.sampled_frames} / 接受 {payload.accepted_frames}）"
        elif isinstance(payload, MapBuildFinalResult):
            image = payload.image
            metadata = dict(payload.metadata)
            message = f"地图构建完成，已导入项目（tile {payload.tile_count}）"
        else:
            return
        self._teardown_preview_analysis_session(cancel_worker=False)
        if self._capture_manager.is_preview_active():
            self.stop_live_preview()
        self._add_project_asset_image(image, metadata=metadata, status_message=message)
        if mode != "none":
            self.statusBar().showMessage(message, 5000)

    def _on_preview_analysis_worker_failed(self, message: str) -> None:
        if self._preview_analysis_mode == "none":
            return
        title = self._analysis_mode_label(self._preview_analysis_mode)
        self._teardown_preview_analysis_session(cancel_worker=True)
        QMessageBox.warning(self, title, message)

    def _cycle_magic_segment_prompt_type(self) -> None:
        canvas = self.current_canvas()
        if canvas is None or not is_magic_segment_tool_mode(self._tool_mode) or canvas.is_magic_segment_busy():
            return
        if (
            canvas.current_magic_segment_operation_mode() == MagicSegmentOperationMode.SUBTRACT
            and canvas.current_magic_subtract_input_mode() != MagicSegmentSubtractInputMode.SMART
        ):
            return
        prompt_type = canvas.cycle_magic_segment_prompt_type()
        self.statusBar().showMessage(self._magic_prompt_label_text(prompt_type), 2500)
        self._update_magic_segment_controls()
        self._focus_current_canvas()

    def _cycle_active_magic_prompt_type(self) -> None:
        if is_magic_segment_tool_mode(self._tool_mode):
            self._cycle_magic_segment_prompt_type()
            return
        if is_fiber_quick_tool_mode(self._tool_mode):
            self._cycle_fiber_quick_prompt_type()

    def _cycle_fiber_quick_prompt_type(self) -> None:
        canvas = self.current_canvas()
        if canvas is None or not is_fiber_quick_tool_mode(self._tool_mode):
            return
        prompt_type = canvas.cycle_fiber_quick_prompt_type()
        self.statusBar().showMessage(self._magic_prompt_label_text(prompt_type), 2500)
        self._update_magic_segment_controls()
        self._focus_current_canvas()

    def _cycle_magic_segment_operation_mode(self) -> None:
        canvas = self.current_canvas()
        if canvas is None or not is_magic_segment_tool_mode(self._tool_mode) or canvas.is_magic_segment_busy():
            return
        if canvas.has_magic_manual_subtract_draft():
            if not self._confirm_discard_magic_manual_subtract_draft(
                "切换编辑状态",
                "当前剔除区域尚未闭合。要丢弃草稿并切换编辑状态吗？",
            ):
                self._update_magic_segment_controls()
                return
            canvas.cancel_magic_subtract_draft()
        before_mode = canvas.current_magic_segment_operation_mode()
        operation_mode = canvas.cycle_magic_segment_operation_mode()
        if operation_mode == MagicSegmentOperationMode.SUBTRACT:
            canvas.set_magic_subtract_input_mode(self._magic_standard_subtract_input_mode)
        if before_mode == MagicSegmentOperationMode.ADD and operation_mode == MagicSegmentOperationMode.ADD:
            self.statusBar().showMessage("请先完成第一个形状草稿", 2500)
        else:
            self.statusBar().showMessage(self._magic_operation_label_text(operation_mode), 2500)
        self._update_magic_segment_controls()
        self._focus_current_canvas()

    def _confirm_current_magic_subtract_shape(self) -> bool:
        canvas = self.current_canvas()
        if (
            canvas is None
            or not is_magic_segment_tool_mode(self._tool_mode)
            or canvas.is_magic_segment_busy()
            or canvas.current_magic_segment_operation_mode() != MagicSegmentOperationMode.SUBTRACT
        ):
            return False
        confirm_result = canvas.confirm_current_magic_subtract_shape()
        if not bool(confirm_result.get("confirmed", False)):
            return False
        self._hide_small_object_preview()
        count = int(confirm_result.get("count", 0) or 0)
        self.statusBar().showMessage(f"已确认剔除形状 {count} 块，可继续添加下一块。", 3000)
        self._update_magic_segment_controls()
        self._focus_current_canvas()
        return True

    def _commit_magic_segment_preview(self) -> bool:
        canvas = self.current_canvas()
        if canvas is None or not is_magic_segment_tool_mode(self._tool_mode) or canvas.is_magic_segment_busy():
            return False
        commit_result = canvas.commit_magic_segment_preview()
        committed = bool(commit_result.get("committed", False))
        messages: list[str] = []
        if committed:
            messages.append("已创建魔棒分割面积")
        elif bool(commit_result.get("result_empty", False)):
            messages.append("剔除后无剩余区域")
        elif str(commit_result.get("reason", "")) == "missing_primary":
            messages.append("请先完成第一个形状草稿")
        if bool(commit_result.get("discarded_fragments", False)):
            messages.append("结果裂成多个独立块，已按规则仅保留最大连通区域。")
        if messages:
            self.statusBar().showMessage(" ".join(messages), 4000)
        if committed:
            self._hide_small_object_preview()
        self._update_magic_segment_controls()
        self._focus_current_canvas()
        return committed

    def _commit_active_magic_preview(self) -> bool:
        if is_magic_segment_tool_mode(self._tool_mode):
            return self._commit_magic_segment_preview()
        if is_fiber_quick_tool_mode(self._tool_mode):
            return self._commit_fiber_quick_preview()
        if is_reference_propagation_tool_mode(self._tool_mode):
            return self._commit_reference_instance_preview()
        return False

    def _commit_reference_instance_preview(self) -> bool:
        canvas = self.current_canvas()
        document = self.current_document()
        if canvas is None or document is None or not is_reference_propagation_tool_mode(self._tool_mode) or canvas.is_reference_instance_busy():
            return False
        commit_result = canvas.commit_reference_instance_preview()
        candidates = list(commit_result.get("candidates", []))
        if not candidates:
            self.statusBar().showMessage("没有可加入当前类别的候选实例。", 4000)
            self._update_magic_segment_controls()
            self._focus_current_canvas()
            return False
        target_group = document.get_group(document.active_group_id) or document.ensure_default_group()
        added_count = 0
        skipped_count = 0

        def mutate() -> None:
            nonlocal target_group, added_count, skipped_count
            target_group = document.get_group(target_group.id) or document.ensure_default_group()
            existing_areas = [
                measurement
                for measurement in document.measurements
                if measurement.measurement_kind == "area" and measurement.fiber_group_id == target_group.id
            ]
            for candidate in candidates:
                polygon_px = list(candidate.get("polygon_px", []))
                area_rings_px = [list(ring) for ring in candidate.get("area_rings_px", [])]
                if len(polygon_px) < 3 and not area_rings_px:
                    continue
                overlaps_existing = any(
                    area_geometry_iou(
                        polygon_px,
                        area_rings_px,
                        measurement.polygon_px,
                        measurement.area_rings_px,
                    ) >= 0.7
                    for measurement in existing_areas
                )
                if overlaps_existing:
                    skipped_count += 1
                    continue
                measurement = Measurement(
                    id=new_id("meas"),
                    image_id=document.id,
                    fiber_group_id=target_group.id,
                    mode="reference_instance",
                    measurement_kind="area",
                    polygon_px=polygon_px,
                    area_rings_px=area_rings_px,
                    confidence=float(candidate.get("confidence", 0.0)),
                    status="reference_instance",
                )
                document.add_measurement(measurement)
                existing_areas.append(measurement)
                added_count += 1
            document.select_overlay_annotation(None)

        self._apply_document_change(document, "导入同类扩选结果", mutate)
        if added_count > 0:
            message = f"已加入 {added_count} 个同类实例"
            if skipped_count > 0:
                message += f"，跳过 {skipped_count} 个重复候选"
            self.statusBar().showMessage(message, 5000)
        else:
            self.statusBar().showMessage("候选与当前类别结果重复，未新增实例。", 5000)
        self._update_magic_segment_controls()
        self._focus_current_canvas()
        return added_count > 0

    def _commit_fiber_quick_preview(self) -> bool:
        canvas = self.current_canvas()
        if canvas is None or not is_fiber_quick_tool_mode(self._tool_mode):
            return False
        if canvas._fiber_quick.segmentation_busy:  # noqa: SLF001
            self.statusBar().showMessage("分割尚未完成，请稍候。", 2500)
            self._update_magic_segment_controls()
            self._focus_current_canvas()
            return False
        commit_result = canvas.commit_fiber_quick_preview()
        committed = bool(commit_result.get("committed", False))
        pending = bool(commit_result.get("pending", False))
        if committed:
            self.statusBar().showMessage("已创建快速测径线段", 4000)
        elif pending:
            snapshot = commit_result.get("snapshot")
            if isinstance(snapshot, dict):
                self._enqueue_fiber_quick_background_job(canvas.document_id, snapshot)
            self.statusBar().showMessage("已确认当前分割，直径线计算完成后将自动写入。", 3000)
        else:
            self.statusBar().showMessage("当前没有可确认的快速测径结果。", 3000)
        self._update_magic_segment_controls()
        self._focus_current_canvas()
        return committed or pending

    def _enqueue_fiber_quick_background_job(self, document_id: str | None, snapshot: dict[str, object]) -> None:
        if not document_id:
            return
        document = self.project.get_document(document_id)
        if document is None:
            return
        if self._fiber_quick_geometry_worker is not None:
            self._fiber_quick_geometry_worker.cancel_document(document_id)
        self._ensure_fiber_quick_commit_geometry_worker()
        if self._fiber_quick_commit_geometry_worker is None:
            return
        self._fiber_quick_background_job_serial += 1
        job_id = self._fiber_quick_background_job_serial
        self._fiber_quick_background_jobs[(document_id, job_id)] = {
            "fiber_group_id": document.active_group_id,
            "debug_payload": dict(snapshot.get("debug_payload", {})),
        }
        self._fiber_quick_commit_geometry_worker.register_request(document_id, job_id)
        self._fiber_quick_commit_geometry_worker.requested.emit(
            FiberQuickGeometryRequest(
                document_id=document_id,
                request_id=job_id,
                mask=snapshot.get("mask"),
                preview_polygon_px=list(snapshot.get("polygon_px", [])) if isinstance(snapshot.get("polygon_px"), list) else [],
                preview_area_rings_px=[list(ring) for ring in snapshot.get("area_rings_px", [])] if isinstance(snapshot.get("area_rings_px"), list) else [],
                positive_points=list(snapshot.get("positive_points", [])) if isinstance(snapshot.get("positive_points"), list) else [],
                negative_points=list(snapshot.get("negative_points", [])) if isinstance(snapshot.get("negative_points"), list) else [],
                edge_trim_enabled=bool(self._app_settings.fiber_quick_edge_trim_enabled),
                line_extension_px=float(self._app_settings.fiber_quick_line_extension_px),
                timeout_ms=DEFAULT_FIBER_QUICK_GEOMETRY_TIMEOUT_MS,
            )
        )

    def _on_fiber_quick_commit_geometry_succeeded(self, document_id: str, request_id: int, result: object) -> None:
        job_meta = self._fiber_quick_background_jobs.pop((document_id, request_id), None)
        if job_meta is None or not hasattr(result, "line_px") or not isinstance(getattr(result, "line_px", None), Line):
            return
        document = self.project.get_document(document_id)
        if document is None:
            return
        merged_debug_payload = dict(job_meta.get("debug_payload", {}))
        if isinstance(getattr(result, "debug_payload", None), dict):
            merged_debug_payload.update(getattr(result, "debug_payload", {}))

        def mutate() -> None:
            measurement = Measurement(
                id=new_id("meas"),
                image_id=document.id,
                fiber_group_id=job_meta.get("fiber_group_id"),
                mode="fiber_quick",
                line_px=result.line_px,
                confidence=float(getattr(result, "confidence", 0.0) or 0.0),
                status=str(getattr(result, "status", "fiber_quick") or "fiber_quick"),
                debug_payload=merged_debug_payload,
            )
            document.add_measurement(measurement)
            document.select_overlay_annotation(None)

        self._apply_document_change(document, "新增测量", mutate)
        self.statusBar().showMessage("快速测径已在后台完成并写入。", 3000)

    def _on_fiber_quick_commit_geometry_failed(self, document_id: str, request_id: int, reason: str) -> None:
        job_meta = self._fiber_quick_background_jobs.pop((document_id, request_id), None)
        if job_meta is None:
            return
        self.statusBar().showMessage(f"快速测径后台失败: {reason}", 4000)

    def _cancel_magic_segment_session(self) -> None:
        canvas = self.current_canvas()
        if canvas is None or not is_magic_segment_tool_mode(self._tool_mode):
            return
        if self._prompt_seg_worker is not None and canvas.document_id is not None:
            self._prompt_seg_worker.cancel_document(canvas.document_id)
        if canvas.cancel_magic_subtract_draft():
            self.statusBar().showMessage("已取消当前剔除草稿", 2500)
            self._update_magic_segment_controls()
            self._focus_current_canvas()
            return
        if canvas.has_magic_segment_session():
            canvas.clear_magic_segment_session()
            self._hide_small_object_preview()
            self.statusBar().showMessage("已放弃当前魔棒遮罩", 2500)
        self._update_magic_segment_controls()
        self._focus_current_canvas()

    def _cancel_active_magic_session(self) -> None:
        if is_magic_segment_tool_mode(self._tool_mode):
            self._cancel_magic_segment_session()
            return
        if is_fiber_quick_tool_mode(self._tool_mode):
            self._cancel_fiber_quick_session()
            return
        if is_reference_propagation_tool_mode(self._tool_mode):
            self._cancel_reference_instance_session()

    def _cancel_reference_instance_session(self) -> None:
        canvas = self.current_canvas()
        if canvas is None or not is_reference_propagation_tool_mode(self._tool_mode):
            return
        if canvas.has_reference_instance_session():
            canvas.clear_reference_instance_session()
            self.statusBar().showMessage("已放弃当前同类扩选", 2500)
        self._update_magic_segment_controls()
        self._focus_current_canvas()

    def _cancel_fiber_quick_session(self) -> None:
        canvas = self.current_canvas()
        if canvas is None or not is_fiber_quick_tool_mode(self._tool_mode):
            return
        if self._fiber_quick_geometry_worker is not None and canvas.document_id is not None:
            self._fiber_quick_geometry_worker.cancel_document(canvas.document_id)
        if self._prompt_seg_worker is not None and canvas.document_id is not None:
            self._prompt_seg_worker.cancel_document(canvas.document_id)
        if canvas.has_fiber_quick_session():
            canvas.clear_fiber_quick_session()
            self.statusBar().showMessage("已放弃当前快速测径", 2500)
        self._update_magic_segment_controls()
        self._focus_current_canvas()

    def _clear_magic_segment_sessions(self, *, except_document_id: str | None = None) -> None:
        should_hide_small_object_preview = except_document_id is None
        for document_id, canvas in self._canvases.items():
            if document_id == except_document_id:
                continue
            if canvas.has_magic_segment_session():
                if self._prompt_seg_worker is not None:
                    self._prompt_seg_worker.cancel_document(document_id)
                canvas.clear_magic_segment_session()
                should_hide_small_object_preview = True
            if canvas.has_reference_instance_session():
                canvas.clear_reference_instance_session()
            if canvas.has_fiber_quick_session():
                if self._fiber_quick_geometry_worker is not None:
                    self._fiber_quick_geometry_worker.cancel_document(document_id)
                if self._prompt_seg_worker is not None:
                    self._prompt_seg_worker.cancel_document(document_id)
                canvas.clear_fiber_quick_session()
        if should_hide_small_object_preview:
            self._hide_small_object_preview()

    def _overlay_metrics(self, width: int, height: int, render_mode: str) -> dict[str, float]:
        metrics = overlay_metrics(width, height, render_mode)
        return {
            "line_width": metrics.line_width,
            "endpoint_radius": metrics.endpoint_radius,
            "scale_bg_width": metrics.scale_bg_width,
            "scale_fg_width": metrics.scale_fg_width,
            "font_px": metrics.font_px,
        }

    def _create_export_surface(self, width: int, height: int) -> QImage:
        image = QImage(max(1, width), max(1, height), QImage.Format.Format_ARGB32_Premultiplied)
        image.fill(QColor("#00000000"))
        return image

    def _export_render_contexts(
        self,
        documents: list[ImageDocument],
        render_mode: str,
    ) -> dict[str, ExportRenderContext]:
        contexts: dict[str, ExportRenderContext] = {}
        for document in documents:
            if not document.is_digital_slide():
                continue
            if render_mode != ExportImageRenderMode.CURRENT_VIEWPORT:
                raise ValueError(
                    "数字切片仅支持导出当前焦层的原始 viewport 像素。"
                )
            canvas = self._canvases.get(document.id)
            store = self._slide_stores.get(document.id)
            if not isinstance(canvas, DigitalSlideCanvas) or store is None:
                raise RuntimeError("数字切片尚未挂载，无法冻结导出 viewport。")
            origin = canvas.viewport_origin()
            manifest = store.read_manifest()
            contexts[document.id] = ExportRenderContext(
                document_id=document.id,
                render_mode=render_mode,
                focus_index=int(canvas.focus_index()),
                origin_x=int(round(origin.x)),
                origin_y=int(round(origin.y)),
                viewport_width=int(manifest.viewport_width),
                viewport_height=int(manifest.viewport_height),
            )
        return contexts

    def _export_protected_source_paths(
        self,
        documents: list[ImageDocument],
    ) -> list[Path]:
        paths: list[Path] = []
        for document in documents:
            resolved = self._resolved_document_path(document)
            if resolved:
                paths.append(Path(resolved).expanduser().resolve())
        return paths

    def _render_overlay_image(
        self,
        document: ImageDocument,
        output_path: Path,
        *,
        include_measurements: bool,
        include_scale: bool,
        include_construction_geometry: bool = False,
        render_mode: str,
        render_context: ExportRenderContext | None = None,
    ) -> RenderedExport:
        viewport_origin: Point | None = None
        if document.is_digital_slide():
            if render_mode != ExportImageRenderMode.CURRENT_VIEWPORT:
                raise ValueError(
                    "数字切片仅支持当前焦层原始 viewport 像素导出，不能导出整张切片 PNG。"
                )
            canvas = self._canvases.get(document.id)
            store = self._slide_stores.get(document.id)
            if not isinstance(canvas, DigitalSlideCanvas) or store is None:
                raise RuntimeError("数字切片尚未挂载，无法导出当前 viewport。")
            # Freeze the complete viewport identity before any rendering work.
            manifest = store.read_manifest()
            if render_context is not None:
                if (
                    render_context.document_id != document.id
                    or render_context.render_mode != render_mode
                ):
                    raise ValueError("冻结的数字切片 viewport 与当前导出目标不一致。")
                origin_x = int(render_context.origin_x)
                origin_y = int(render_context.origin_y)
                focus_index = int(render_context.focus_index)
                viewport_width = int(render_context.viewport_width or manifest.viewport_width)
                viewport_height = int(render_context.viewport_height or manifest.viewport_height)
            else:
                origin = canvas.viewport_origin()
                origin_x = int(round(origin.x))
                origin_y = int(round(origin.y))
                focus_index = int(canvas.focus_index())
                viewport_width = int(manifest.viewport_width)
                viewport_height = int(manifest.viewport_height)
            viewport_origin = Point(float(origin_x), float(origin_y))
            metadata = manifest.metadata if isinstance(manifest.metadata, dict) else {}
            try:
                blend_width = int(metadata.get("blend_width", 0) or 0)
            except (TypeError, ValueError):
                blend_width = 0
            source_image = store.render_viewport(
                x=origin_x,
                y=origin_y,
                width=viewport_width,
                height=viewport_height,
                z_index=focus_index,
                blend_width=blend_width,
            )
            if source_image.isNull():
                raise RuntimeError("数字切片当前 viewport 渲染为空。")
        else:
            source_image = self._images.get(document.id, QImage())
            if source_image.isNull():
                raise RuntimeError(f"图片尚未加载，无法导出：{document.path}")
        mounted_canvas = self._canvases.get(document.id)
        if mounted_canvas is not None:
            screen_scale = mounted_canvas.view_zoom()
        else:
            persisted_zoom = float(document.view_state.zoom or 1.0)
            if not math.isfinite(persisted_zoom) or persisted_zoom <= 0:
                persisted_zoom = 1.0
            screen_scale = max(MIN_VIEW_ZOOM, persisted_zoom)

        if document.is_digital_slide():
            image = self._create_export_surface(source_image.width(), source_image.height())
            image_to_output_scale = 1.0
            assert viewport_origin is not None

            def image_to_output(point) -> QPointF:
                return QPointF(point.x - viewport_origin.x, point.y - viewport_origin.y)

            visible_construction_rect = QRectF(
                viewport_origin.x,
                viewport_origin.y,
                source_image.width(),
                source_image.height(),
            )
        elif render_mode == ExportImageRenderMode.FULL_RESOLUTION:
            image = self._create_export_surface(source_image.width(), source_image.height())
            image_to_output_scale = 1.0

            def image_to_output(point) -> QPointF:
                return QPointF(point.x, point.y)

            visible_construction_rect = QRectF(
                0.0,
                0.0,
                source_image.width(),
                source_image.height(),
            )
        elif render_mode == ExportImageRenderMode.CURRENT_VIEWPORT:
            canvas = mounted_canvas
            viewport_width = max(200, canvas.width()) if canvas is not None else max(400, min(1400, source_image.width()))
            viewport_height = max(160, canvas.height()) if canvas is not None else max(300, min(900, source_image.height()))
            image = self._create_export_surface(viewport_width, viewport_height)
            image_to_output_scale = screen_scale

            def image_to_output(point) -> QPointF:
                return QPointF(
                    document.view_state.pan.x + (point.x * screen_scale),
                    document.view_state.pan.y + (point.y * screen_scale),
                )

            visible_left = max(
                0.0,
                -document.view_state.pan.x / screen_scale,
            )
            visible_top = max(
                0.0,
                -document.view_state.pan.y / screen_scale,
            )
            visible_right = min(
                float(source_image.width()),
                (image.width() - document.view_state.pan.x) / screen_scale,
            )
            visible_bottom = min(
                float(source_image.height()),
                (image.height() - document.view_state.pan.y) / screen_scale,
            )
            visible_construction_rect = QRectF(
                visible_left,
                visible_top,
                max(0.0, visible_right - visible_left),
                max(0.0, visible_bottom - visible_top),
            )
        else:
            output_width = max(1, int(round(source_image.width() * screen_scale)))
            output_height = max(1, int(round(source_image.height() * screen_scale)))
            image = self._create_export_surface(output_width, output_height)
            image_to_output_scale = screen_scale

            def image_to_output(point) -> QPointF:
                return QPointF(point.x * screen_scale, point.y * screen_scale)

            visible_construction_rect = QRectF(
                0.0,
                0.0,
                source_image.width(),
                source_image.height(),
            )

        painter = QPainter(image)
        if not painter.isActive():
            raise RuntimeError("无法创建可绘制的导出画布。")
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        painter.setRenderHint(QPainter.RenderHint.TextAntialiasing, True)

        if document.is_digital_slide():
            painter.drawImage(QPointF(0.0, 0.0), source_image)
        elif render_mode == ExportImageRenderMode.FULL_RESOLUTION:
            painter.drawImage(QPointF(0.0, 0.0), source_image)
        elif render_mode == ExportImageRenderMode.CURRENT_VIEWPORT:
            painter.fillRect(image.rect(), QColor("#101820"))
            target_rect = QRectF(
                document.view_state.pan.x,
                document.view_state.pan.y,
                source_image.width() * screen_scale,
                source_image.height() * screen_scale,
            )
            painter.drawImage(target_rect, source_image)
        else:
            painter.drawImage(
                QRectF(0.0, 0.0, image.width(), image.height()),
                source_image,
                QRectF(0.0, 0.0, source_image.width(), source_image.height()),
            )

        metrics = self._overlay_metrics(image.width(), image.height(), render_mode)
        line_width = metrics["line_width"]
        endpoint_radius = metrics["endpoint_radius"]
        scale_bg_width = metrics["scale_bg_width"]
        scale_fg_width = metrics["scale_fg_width"]
        font_px = metrics["font_px"]

        if include_construction_geometry:
            construction_resolver = make_construction_resolver(document)
            draw_construction_entities(
                painter,
                (
                    (entity, construction_resolver.resolve(entity))
                    for entity in document.construction_entities
                ),
                image_to_output,
                visible_image_rect=visible_construction_rect,
            )

        if include_measurements:
            draw_measurements(
                painter,
                document,
                image_to_output,
                self._app_settings,
                line_width=line_width,
                endpoint_radius=endpoint_radius,
                show_area_fill=self._show_area_fill,
                area_geometry_mode=AREA_GEOMETRY_RAW,
            )

        if include_measurements or include_scale:
            draw_overlay_annotations(
                painter,
                document,
                image_to_output,
                self._app_settings,
                selected_overlay_id=None,
                render_mode=render_mode,
            )

        if include_scale:
            if (
                self._app_settings.scale_overlay_placement_mode == ScaleOverlayPlacementMode.MANUAL
                and document.scale_overlay_anchor is None
            ):
                self.statusBar().showMessage(
                    f"{Path(document.path).name} 尚未指定手动比例尺位置，已回退到左下角导出。",
                    5000,
                )
            draw_scale_overlay(
                painter,
                document,
                self._app_settings,
                image_width=image.width(),
                image_height=image.height(),
                image_to_output_scale=image_to_output_scale,
                scale_bg_width=scale_bg_width,
                scale_fg_width=scale_fg_width,
                font_px=font_px,
                render_mode=render_mode,
                image_origin=viewport_origin,
            )

        painter.end()
        if not image.save(str(output_path)):
            raise OSError(f"无法写入导出文件：{output_path}")
        return RenderedExport(output_path, image.width(), image.height())

    def _color_icon(self, color_value: str, *, size: int = 12) -> QIcon:
        pixmap = QPixmap(size, size)
        pixmap.fill(QColor(color_value))
        return QIcon(pixmap)

    def _contrast_color(self, color_value: str) -> str:
        color = QColor(color_value)
        luminance = (0.299 * color.red()) + (0.587 * color.green()) + (0.114 * color.blue())
        return "#111111" if luminance > 186 else "#FFFFFF"

    def keyPressEvent(self, event) -> None:
        canvas = self.current_canvas()
        if event.key() == Qt.Key.Key_Space:
            if (
                canvas is not None
                and not getattr(event, "isAutoRepeat", lambda: False)()
            ):
                canvas.set_temporary_grab_pressed(True)
            event.accept()
            return
        if (
            self._should_handle_digital_slide_jog_hotkeys()
            and event.modifiers() == Qt.KeyboardModifier.NoModifier
            and event.key() in (Qt.Key.Key_Left, Qt.Key.Key_Right, Qt.Key.Key_Up, Qt.Key.Key_Down)
        ):
            if not getattr(event, "isAutoRepeat", lambda: False)():
                mapping = {
                    Qt.Key.Key_Left: (AXIS_X, DIR_NEG),
                    Qt.Key.Key_Right: (AXIS_X, DIR_POS),
                    Qt.Key.Key_Up: (AXIS_Y, DIR_NEG),
                    Qt.Key.Key_Down: (AXIS_Y, DIR_POS),
                }
                axis, direction = mapping[event.key()]
                self._begin_digital_slide_jog(axis, direction)
            event.accept()
            return
        if self._preview_analysis_mode != "none" and event.modifiers() == Qt.KeyboardModifier.NoModifier:
            if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_F):
                self._finalize_preview_analysis_session()
                event.accept()
                return
            if event.key() == Qt.Key.Key_Escape:
                self._cancel_preview_analysis_session()
                event.accept()
                return
        if self._tool_mode in {"polygon_area", "freehand_area", "continuous_manual"} and event.modifiers() == Qt.KeyboardModifier.NoModifier:
            if self._tool_mode in {"polygon_area", "freehand_area"} and event.key() == Qt.Key.Key_T:
                self._cycle_area_edit_operation_mode()
                event.accept()
                return
            if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_F):
                if self._commit_active_path_drawing():
                    event.accept()
                    return
            if event.key() == Qt.Key.Key_Escape:
                if self._cancel_active_path_drawing():
                    event.accept()
                    return
        if is_magic_toolbar_tool_mode(self._tool_mode) and event.modifiers() == Qt.KeyboardModifier.NoModifier:
            if is_magic_segment_tool_mode(self._tool_mode):
                if event.key() == Qt.Key.Key_R:
                    self._cycle_magic_segment_prompt_type()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_Y:
                    self._toggle_active_magic_roi()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_T:
                    self._cycle_magic_segment_operation_mode()
                    event.accept()
                    return
                if (
                    canvas is not None
                    and canvas.current_magic_segment_operation_mode() == MagicSegmentOperationMode.SUBTRACT
                    and event.key() in (Qt.Key.Key_1, Qt.Key.Key_2, Qt.Key.Key_3)
                ):
                    mode_by_key = {
                        Qt.Key.Key_1: MagicSegmentSubtractInputMode.SMART,
                        Qt.Key.Key_2: MagicSegmentSubtractInputMode.POLYGON,
                        Qt.Key.Key_3: MagicSegmentSubtractInputMode.FREEHAND,
                    }
                    self._set_magic_subtract_input_mode(mode_by_key[event.key()])
                    event.accept()
                    return
                if (
                    event.key() == Qt.Key.Key_S
                    and canvas is not None
                    and canvas.current_magic_segment_operation_mode() == MagicSegmentOperationMode.SUBTRACT
                ):
                    if self._confirm_current_magic_subtract_shape():
                        event.accept()
                        return
                    return
                if event.key() == Qt.Key.Key_S:
                    return
                if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_F):
                    if canvas is not None and canvas.complete_magic_manual_subtract_draft():
                        self.statusBar().showMessage("已生成剔除草稿，可点击加入剔除继续", 2500)
                        self._update_magic_segment_controls()
                        event.accept()
                        return
                    self._commit_magic_segment_preview()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_Escape:
                    if (
                        canvas is not None
                        and (
                            canvas.has_magic_segment_session()
                            or canvas.has_magic_manual_subtract_draft()
                        )
                    ):
                        self._cancel_magic_segment_session()
                        event.accept()
                        return
            elif is_fiber_quick_tool_mode(self._tool_mode):
                if event.key() == Qt.Key.Key_R:
                    self._cycle_fiber_quick_prompt_type()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_Y:
                    self._toggle_active_magic_roi()
                    event.accept()
                    return
                if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_F):
                    self._commit_fiber_quick_preview()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_Escape:
                    if canvas is not None and canvas.has_fiber_quick_session():
                        self._cancel_fiber_quick_session()
                        event.accept()
                        return
            elif is_reference_propagation_tool_mode(self._tool_mode):
                if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_F):
                    self._commit_reference_instance_preview()
                    event.accept()
                    return
                if event.key() == Qt.Key.Key_Escape:
                    if (
                        canvas is not None
                        and canvas.has_reference_instance_session()
                    ):
                        self._cancel_reference_instance_session()
                        event.accept()
                        return
        if (
            event.modifiers() == Qt.KeyboardModifier.NoModifier
            and event.key() == Qt.Key.Key_Escape
            and self._fullscreen_controller is not None
            and self._fullscreen_controller.is_active
        ):
            self._fullscreen_controller.exit()
            event.accept()
            return
        if event.modifiers() == Qt.KeyboardModifier.NoModifier and event.key() == Qt.Key.Key_A:
            if self._tool_mode == "select":
                if self._last_non_select_tool and self._last_non_select_tool != "select":
                    self.set_tool_mode(self._last_non_select_tool)
            else:
                self._last_non_select_tool = self._tool_mode
                self.set_tool_mode("select")
            event.accept()
            return
        if (
            event.modifiers() == Qt.KeyboardModifier.NoModifier
            and event.key() == Qt.Key.Key_V
            and self._should_handle_group_hotkeys()
        ):
            self._show_area_fill = not self._show_area_fill
            for canvas in self._canvases.values():
                canvas.set_show_area_fill(self._show_area_fill)
            self.statusBar().showMessage("面积填充已开启" if self._show_area_fill else "面积填充已关闭，仅显示轮廓", 3000)
            event.accept()
            return
        if (
            event.modifiers() == Qt.KeyboardModifier.NoModifier
            and Qt.Key.Key_1 <= event.key() <= Qt.Key.Key_9
            and self._should_handle_group_hotkeys()
        ):
            number = event.key() - Qt.Key.Key_0
            if self._switch_active_group_by_number(number):
                event.accept()
                return
        if self._tool_mode != "calibration" and event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
            self.delete_selected_measurement()
            return
        super().keyPressEvent(event)

    def keyReleaseEvent(self, event) -> None:
        if event.key() == Qt.Key.Key_Space:
            canvas = self.current_canvas()
            if (
                canvas is not None
                and not getattr(event, "isAutoRepeat", lambda: False)()
            ):
                canvas.set_temporary_grab_pressed(False)
            event.accept()
            return
        if (
            self._should_handle_digital_slide_jog_hotkeys()
            and event.modifiers() == Qt.KeyboardModifier.NoModifier
            and event.key() in (Qt.Key.Key_Left, Qt.Key.Key_Right, Qt.Key.Key_Up, Qt.Key.Key_Down)
        ):
            if not getattr(event, "isAutoRepeat", lambda: False)():
                self._end_digital_slide_jog()
            event.accept()
            return
        super().keyReleaseEvent(event)

    def _choose_acquisition_transition_disposition(
        self,
        intent: TransitionIntent,
    ) -> AcquisitionDisposition:
        labels = {
            TransitionIntent.CLOSE_WINDOW: "关闭窗口",
            TransitionIntent.OPEN_DOCUMENT: "打开外部文件",
            TransitionIntent.OPEN_PROJECT: "打开其他项目",
            TransitionIntent.RESET_WORKSPACE: "重置工作区",
            TransitionIntent.SWITCH_DEVICE: "切换采集设备",
        }
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.Warning)
        box.setWindowTitle("数字化切片仍在采集")
        box.setText(f"{labels.get(intent, '继续操作')}前，请选择如何处理已经接受的采集数据。")
        keep_button = box.addButton("保留部分并继续", QMessageBox.ButtonRole.AcceptRole)
        discard_button = box.addButton("丢弃并继续", QMessageBox.ButtonRole.DestructiveRole)
        cancel_button = box.addButton("取消", QMessageBox.ButtonRole.RejectRole)
        box.setDefaultButton(keep_button)
        box.exec()
        clicked = box.clickedButton()
        if clicked == keep_button:
            return AcquisitionDisposition.KEEP_PARTIAL
        if clicked == discard_button:
            return AcquisitionDisposition.DISCARD
        if clicked == cancel_button:
            return AcquisitionDisposition.CANCEL
        return AcquisitionDisposition.CANCEL

    def _preflight_acquisition_disposition(
        self,
        intent: TransitionIntent,
    ) -> AcquisitionDisposition | None:
        """Collect acquisition intent without stopping or mutating the session."""

        if not self._slide_acquisition_active():
            return None
        previous_transition_state = self._transition_in_progress
        self._transition_in_progress = True
        try:
            return self._choose_acquisition_transition_disposition(intent)
        finally:
            self._transition_in_progress = previous_transition_state

    def _wait_for_slide_acquisition_exit(self, timeout_ms: int = 10_000) -> bool:
        if not self._slide_acquisition_active():
            return True
        loop = QEventLoop(self)
        poll = QTimer(loop)
        poll.setInterval(25)

        def check_finished() -> None:
            if not self._slide_acquisition_active():
                loop.quit()

        poll.timeout.connect(check_finished)
        deadline = QTimer(loop)
        deadline.setSingleShot(True)
        deadline.timeout.connect(loop.quit)
        poll.start()
        deadline.start(max(1, int(timeout_ms)))
        loop.exec()
        poll.stop()
        deadline.stop()
        return not self._slide_acquisition_active()

    def _prepare_transition(
        self,
        intent: TransitionIntent,
        *,
        disposition: AcquisitionDisposition | None = None,
    ) -> TransitionResult:
        task_results = []
        self._transition_in_progress = True
        try:
            if self._slide_acquisition_active():
                chosen = disposition or self._choose_acquisition_transition_disposition(intent)
                if chosen == AcquisitionDisposition.CANCEL:
                    return TransitionResult(intent=intent, completed=False, cancelled=True, reason="操作已取消。")
                self._slide_acquisition_timer.stop()
                self._slide_jog_single_shot_timer.stop()
                self._slide_jog_timer.stop()
                self._slide_jog_request = None
                if chosen == AcquisitionDisposition.KEEP_PARTIAL:
                    self._request_digital_slide_acquisition_finish(
                        status="interrupted",
                        message="转换前已保留部分数字化切片",
                    )
                else:
                    self._request_digital_slide_acquisition_discard(
                        message="转换前已丢弃数字化切片",
                    )
                if not self._wait_for_slide_acquisition_exit():
                    return TransitionResult(
                        intent=intent,
                        completed=False,
                        timed_out=True,
                        reason="数字化切片写入线程未能在时限内退出，转换已阻止。",
                    )

            # No new callbacks may enter the next session after this point.
            self._slide_jog_single_shot_timer.stop()
            self._slide_jog_timer.stop()
            self._slide_jog_request = None
            if not self._stop_image_batch_tasks(wait=True):
                return TransitionResult(
                    intent=intent,
                    completed=False,
                    timed_out=True,
                    reason="图像批处理任务未能在时限内退出，转换已阻止。",
                    task_results=tuple(task_results),
                )
            if not self._stop_analysis_batch_tasks(wait=True):
                return TransitionResult(
                    intent=intent,
                    completed=False,
                    timed_out=True,
                    reason="批量分析任务未能在时限内退出，转换已阻止。",
                    task_results=tuple(task_results),
                )
            if not self._stop_image_analysis_tasks(wait=True):
                return TransitionResult(
                    intent=intent,
                    completed=False,
                    timed_out=True,
                    reason="图像分析任务未能在时限内退出，转换已阻止。",
                    task_results=tuple(task_results),
                )
            if self._capture_manager.is_preview_active():
                capture_result = self._capture_manager.stop_preview()
                if not capture_result:
                    return TransitionResult(
                        intent=intent,
                        completed=False,
                        reason=capture_result.message or "相机 backend 未能确认退出。",
                        task_results=tuple(task_results),
                    )
            else:
                self._preview_active = False
            motion_result = self._slide_motion.shutdown(f"transition:{intent.value}")
            if not motion_result.closed:
                return TransitionResult(
                    intent=intent,
                    completed=False,
                    reason=f"电机串口未能关闭：{motion_result.error or '未知错误'}",
                )
            task_results.extend(self._shutdown_background_threads())
            timed_out = [result for result in task_results if result.timed_out]
            if timed_out:
                names = ", ".join(result.name for result in timed_out)
                return TransitionResult(
                    intent=intent,
                    completed=False,
                    timed_out=True,
                    reason=f"后台任务未能在时限内退出：{names}。转换已阻止。",
                    task_results=tuple(task_results),
                )
            return TransitionResult(intent=intent, completed=True, task_results=tuple(task_results))
        finally:
            self._transition_in_progress = False

    def _shutdown_background_threads(self):
        results = []
        writer_result = self._stop_digital_slide_writer(cancel=True)
        results.append(writer_result)
        if self._preview_analysis_mode != "none":
            preview_result = self._teardown_preview_analysis_session(cancel_worker=True)
            if preview_result is not None:
                results.append(preview_result)
        document_ids = list(self._canvases.keys())
        commit_document_ids = {
            document_id
            for document_id, _request_id in self._fiber_quick_background_jobs.keys()
        }
        commit_document_ids.update(document_ids)
        results.extend(
            self.background_task_controller.shutdown_all(
                document_ids=document_ids,
                commit_document_ids=list(commit_document_ids),
            )
        )
        if writer_result.stopped and all(result.stopped for result in results):
            self._fiber_quick_geometry_request_ids.clear()
            self._fiber_quick_background_jobs.clear()
            self._prompt_request_tool_modes.clear()
        return results

    def closeEvent(self, event: QCloseEvent) -> None:
        intent = TransitionIntent.CLOSE_WINDOW
        disposition = self._preflight_acquisition_disposition(intent)
        if disposition == AcquisitionDisposition.CANCEL:
            self.statusBar().showMessage("操作已取消。", 6000)
            event.ignore()
            return
        if not self._confirm_close_documents(self.project.documents):
            event.ignore()
            return
        transition = self._prepare_transition(intent, disposition=disposition)
        if not transition.completed:
            if transition.reason:
                self.statusBar().showMessage(transition.reason, 6000)
            event.ignore()
            return
        if not self._close_image_processing_workbench(wait=True):
            event.ignore()
            return
        self._close_threshold_adjustment_dialog()
        self._close_display_adjustment_dialog()
        if not self._close_image_batch_dialog(wait=True):
            event.ignore()
            return
        if not self._close_analysis_batch_dialog(wait=True):
            event.ignore()
            return
        try:
            self._close_document_slide_stores()
        except RuntimeError as exc:
            self.statusBar().showMessage(str(exc), 8000)
            event.ignore()
            return
        self._persist_window_geometry()
        self._hide_small_object_preview()
        self._clear_prompt_segmentation_cache()
        for canvas in self._canvases.values():
            self._release_document_canvas(canvas)
        self._cleanup_session_processed_assets()
        self.image_batch_task_controller.close()
        if not self.image_batch_task_controller.wait_for_done(5_000):
            event.ignore()
            return
        self.analysis_batch_controller.close()
        if not self.analysis_batch_controller.wait_for_done(5_000):
            event.ignore()
            return
        self.image_analysis_task_controller.close()
        if not self.image_analysis_task_controller.wait_for_done(5_000):
            event.ignore()
            return
        if self._analysis_results_center is not None:
            self._analysis_results_center.close()
        self._cleanup_session_analysis_assets()
        self._digital_slide_local_cache.cleanup()
        app = QApplication.instance()
        if self._application_key_filter_installed and app is not None:
            app.removeEventFilter(self)
            self._application_key_filter_installed = False
        event.accept()
